/// Phase D3b: admin-management dialog above the composer. Three flows
/// share one slot:
/// - `Promote`: member picker (search + member list from
///   `getSupergroupMembers`) followed by the rights checkboxes; the
///   checkboxes start with every right enabled (mirrors the official
///   clients' "all rights" default).
/// - `EditRights`: rights checkboxes for an existing administrator,
///   pre-filled from `Session::admin_rights` once the `getChatMember`
///   lookup lands (`rights` stays `None` until then).
/// - `DemoteConfirm`: demote confirmation for one administrator.
pub struct AdminDialog {
    chat_id: ChatId,
    kind: AdminDialogKind,
}

pub enum AdminDialogKind {
    Promote {
        search_input: Entity<TextareaState>,
        rights: ChatAdminRights,
        selected_user: Option<i64>,
    },
    EditRights {
        user_id: i64,
        rights: Option<ChatAdminRights>,
    },
    DemoteConfirm {
        user_id: i64,
    },
}

impl AdminDialog {
    fn promote(window: &mut Window, cx: &mut Context<QuillApp>, chat_id: ChatId) -> Self {
        let search_input = cx.new(|cx| {
            TextareaState::new(window, cx)
                .placeholder("Search members")
                .auto_grow(1, 1)
                .submit_on_enter(false)
        });
        Self {
            chat_id,
            kind: AdminDialogKind::Promote {
                search_input,
                rights: ChatAdminRights::all(),
                selected_user: None,
            },
        }
    }

    fn edit_rights(chat_id: ChatId, user_id: i64, rights: Option<ChatAdminRights>) -> Self {
        Self {
            chat_id,
            kind: AdminDialogKind::EditRights { user_id, rights },
        }
    }

    fn demote_confirm(chat_id: ChatId, user_id: i64) -> Self {
        Self {
            chat_id,
            kind: AdminDialogKind::DemoteConfirm { user_id },
        }
    }
}

/// Slice G1: which chat to create. Basic groups use
/// `createNewBasicGroupChat` (schema 1.8.67, line 13327); supergroups
/// and channels use `createNewSupergroupChat` (line 13337) with the
/// `is_channel` flag.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CreateChatKind {
    BasicGroup,
    Supergroup,
    Channel,
}

impl CreateChatKind {
    fn title(self) -> &'static str {
        match self {
            Self::BasicGroup => "New group",
            Self::Supergroup => "New supergroup",
            Self::Channel => "New channel",
        }
    }

    /// Only basic groups take members at creation
    /// (`createNewBasicGroupChat.user_ids`); supergroup members are
    /// added afterwards from the member dialog.
    fn picks_members(self) -> bool {
        matches!(self, Self::BasicGroup)
    }
}

/// Slice G1: group/supergroup/channel creation dialog (sidebar "New"
/// entries). Title input (plus description for supergroups/channels)
/// and, for basic groups, a contact picker with multi-select whose ids
/// ride `createNewBasicGroupChat.user_ids`.
pub struct CreateChatDialog {
    kind: CreateChatKind,
    title_input: Entity<TextareaState>,
    description_input: Entity<TextareaState>,
    search_input: Entity<TextareaState>,
    selected_users: Vec<i64>,
}

impl CreateChatDialog {
    fn new(window: &mut Window, cx: &mut Context<QuillApp>, kind: CreateChatKind) -> Self {
        let title_input = cx.new(|cx| {
            TextareaState::new(window, cx)
                .placeholder("Name")
                .auto_grow(1, 1)
                .submit_on_enter(false)
        });
        let description_input = cx.new(|cx| {
            TextareaState::new(window, cx)
                .placeholder("Description (optional)")
                .auto_grow(1, 3)
                .submit_on_enter(false)
        });
        let search_input = cx.new(|cx| {
            TextareaState::new(window, cx)
                .placeholder("Search contacts")
                .auto_grow(1, 1)
                .submit_on_enter(false)
        });
        Self {
            kind,
            title_input,
            description_input,
            search_input,
            selected_users: Vec::new(),
        }
    }
}

/// Slice G1: member-management dialog tabs.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MemberTab {
    All,
    Administrators,
    Restricted,
    Banned,
}

impl MemberTab {
    fn label(self) -> &'static str {
        match self {
            Self::All => "Members",
            Self::Administrators => "Admins",
            Self::Restricted => "Restricted",
            Self::Banned => "Banned",
        }
    }

    fn filter(self) -> Option<MemberListFilter> {
        match self {
            Self::All => None,
            Self::Administrators => Some(MemberListFilter::Administrators),
            Self::Restricted => Some(MemberListFilter::Restricted),
            Self::Banned => Some(MemberListFilter::Banned),
        }
    }
}

/// Slice G1: member-management dialog for a basic group or
/// supergroup. `All` browses Recent/Search pages (basic groups read
/// their full member list from `getBasicGroupFullInfo`); the other
/// tabs read the matching `getSupergroupMembers` filter. The add
/// section at the bottom picks contacts to add via `addChatMember`
/// (basic groups) / `addChatMembers` (supergroups).
pub struct MemberDialog {
    chat_id: ChatId,
    is_basic_group: bool,
    tab: MemberTab,
    search_input: Entity<TextareaState>,
    add_open: bool,
    add_search: Entity<TextareaState>,
    add_selected: Vec<i64>,
}

/// B1: password prompt for an `inlineKeyboardButtonTypeCallbackWithPassword`
/// button press (TDLib 1.8.67, `schema/td_api.tl:3789`). Submits the entered
/// Slice A2: which form the two-step verification overlay shows.
/// The status screen is the hub; each form submits one TDLib request
/// and the status screen renders the authoritative answer.
#[derive(Clone, Copy, PartialEq, Eq, Default)]
enum TwofaView {
    #[default]
    Status,
    Enable,
    Change,
    Disable,
    Email,
}

/// 2-step password with the button's callback `data` via
