    /// Slice CL3: multi-select mode — enter with one chat checked (from
    /// the row-menu "Select" item).
    fn enter_select_mode(&mut self, chat_id: ChatId, cx: &mut Context<Self>) {
        self.selected_chats.insert(chat_id.0);
        cx.notify();
    }

    /// Slice CL3: leave multi-select mode, clearing the checks.
    fn exit_select_mode(&mut self, cx: &mut Context<Self>) {
        self.selected_chats.clear();
        cx.notify();
    }

    /// Slice CL3: toggle one row's check in multi-select mode; the last
    /// uncheck exits the mode.
    fn toggle_chat_selected(&mut self, chat_id: ChatId, cx: &mut Context<Self>) {
        if !self.selected_chats.remove(&chat_id.0) {
            self.selected_chats.insert(chat_id.0);
        }
        cx.notify();
    }

    /// Slice CL3: "Select unread" — check every listed chat with unread
    /// messages or a marked-as-unread flag (TGX `ChatsController`
    /// select-unread), main list and archive alike.
    fn select_unread_chats(&mut self, cx: &mut Context<Self>) {
        // Collect first: `session()` borrows `self`, so the ids must be
        // owned before touching `selected_chats`.
        let unread: Vec<i64> = self
            .session()
            .map(|session| {
                session
                    .ordered_chats()
                    .into_iter()
                    .chain(session.ordered_archived_chats())
                    .filter(|chat| chat.is_unread())
                    .map(|chat| chat.id.0)
                    .collect()
            })
            .unwrap_or_default();
        for id in unread {
            self.selected_chats.insert(id);
        }
        cx.notify();
    }

    /// Slice CL3: bulk pin for the selection, all-or-nothing like TGX:
    /// if any selected chat is unpinned, pin all; otherwise unpin all.
    /// Reuses `toggle_chat_pin` (with its rollback note) per chat that
    /// still needs the change.
    fn toggle_selected_pins(&mut self, cx: &mut Context<Self>) {
        let chats = self.selected_chat_pin_states();
        let pin_all = chats.iter().any(|(_, pinned)| !pinned);
        for (id, pinned) in chats {
            if pinned != pin_all {
                self.toggle_chat_pin(id, cx);
            }
        }
        self.selected_chats.clear();
        cx.notify();
    }

    /// Slice CL3: bulk mark-as-read for the selection, reusing the
    /// single-chat mark-read path (`toggle_chat_marked_as_unread`
    /// does the TGX `viewMessages` flow when there is unread state).
    fn mark_selected_read(&mut self, cx: &mut Context<Self>) {
        let ids: Vec<ChatId> = self.selected_chats.iter().map(|id| ChatId(*id)).collect();
        for id in ids {
            // `toggle_chat_marked_as_unread` is a genuine toggle: calling it
            // on a fully-read chat would mark it *unread* — never do that
            // under a "Read" button.
            let unread = self
                .session()
                .and_then(|s| s.chats.get(&id.0))
                .is_some_and(|chat| chat.is_unread());
            if unread {
                self.toggle_chat_marked_as_unread(id, cx);
            }
        }
        self.selected_chats.clear();
        cx.notify();
    }

    /// Slice CL3: bulk mute for the selection, all-or-nothing like TGX:
    /// if any selected chat is unmuted, mute all; otherwise unmute all.
    /// Reuses `apply_chat_mute` (mute-forever / unmute, like the row menu)
    /// per chat that still needs the change.
    fn toggle_selected_mute(&mut self, cx: &mut Context<Self>) {
        let chats: Vec<(ChatId, bool)> = self
            .selected_chats
            .iter()
            .map(|&id| {
                let muted = self
                    .session()
                    .and_then(|s| s.chats.get(&id))
                    .is_some_and(|chat| chat.is_muted());
                (ChatId(id), muted)
            })
            .collect();
        let mute_all = chats.iter().any(|(_, muted)| !muted);
        for (id, muted) in chats {
            if muted != mute_all {
                self.apply_chat_mute(id, if mute_all { MUTE_FOREVER } else { 0 }, cx);
            }
        }
        self.selected_chats.clear();
        cx.notify();
    }

    /// Slice CL3: bulk archive for the selection, all-or-nothing like
    /// TGX: if any selected chat is unarchived, archive all; otherwise
    /// unarchive all. Reuses `toggle_archive` per chat that still needs
    /// the change.
    fn toggle_selected_archive(&mut self, cx: &mut Context<Self>) {
        let chats: Vec<(ChatId, bool)> = self
            .selected_chats
            .iter()
            .map(|&id| {
                let archived = self
                    .session()
                    .and_then(|s| s.chats.get(&id))
                    .is_some_and(|chat| chat.in_archive);
                (ChatId(id), archived)
            })
            .collect();
        let archive_all = chats.iter().any(|(_, archived)| !archived);
        for (id, archived) in chats {
            if archived != archive_all {
                self.toggle_archive(id, cx);
            }
        }
        self.selected_chats.clear();
        cx.notify();
    }

    /// Slice CL3: per-selected-chat pin state, honoring the pinned flag
    /// of the list the chat actually sits in (main vs archive).
    fn selected_chat_pin_states(&self) -> Vec<(ChatId, bool)> {
        self.selected_chats
            .iter()
            .map(|&id| {
                let pinned = self
                    .session()
                    .and_then(|s| s.chats.get(&id))
                    .is_some_and(|chat| {
                        if chat.in_archive {
                            chat.archive_is_pinned
                        } else {
                            chat.is_pinned
                        }
                    });
                (ChatId(id), pinned)
            })
            .collect()
    }

    /// Slice CL3: bulk delete — confirms first, like the single-chat
    /// row-menu path.
    fn delete_selected_chats(&mut self, cx: &mut Context<Self>) {
        // The dialog needs a chat id; the ids to delete are read from
        // the live selection at submit time.
        if let Some(first) = self.selected_chats.iter().next().map(|id| ChatId(*id)) {
            self.open_group_confirm(first, GroupConfirmAction::RemoveSelectedChats, cx);
        }
    }

    /// Slice G1: run the confirmed action — `deleteChat` (schema
    /// 1.8.67, line 11850; driver checks
    /// `chat.can_be_deleted_for_all_users`), `leaveChat`, or the
    /// one-way `toggleSupergroupIsBroadcastGroup` upgrade (schema
    /// 1.8.67, line 15221).
    fn submit_group_confirm(&mut self, cx: &mut Context<Self>) {
        let Some(dialog) = self.group_confirm_dialog.take() else {
            return;
        };
        // A driver's `Ok(None)` means the request was refused or is
        // already in flight — never report it as sent.
        fn sent_note(sent: Option<RequestId>, note: &str) -> String {
            if sent.is_some() {
                note.to_string()
            } else {
                "request already in flight".to_string()
            }
        }
        // Slice B2: read before the live borrow — the RestartBot arm
        // needs the session while `live` is mutably borrowed.
        let restart_bot_user_id = if matches!(dialog.action, GroupConfirmAction::RestartBot) {
            self.session()
                .and_then(|session| session.bot_user_id_for_chat(dialog.chat_id))
        } else {
            None
        };
        let note = match self.live.as_mut() {
            Some(live) => {
                let result = match dialog.action {
                    GroupConfirmAction::DeleteChat => live
                        .driver
                        .delete_chat(dialog.chat_id)
                        .map(|sent| sent_note(sent, "chat deleted")),
                    GroupConfirmAction::LeaveChat => live
                        .driver
                        .leave_channel(dialog.chat_id)
                        .map(|_| "left the chat".to_string()),
                    GroupConfirmAction::BroadcastUpgrade => live
                        .driver
                        .upgrade_to_broadcast_group(dialog.chat_id)
                        // Ongoing, not done: TDLib answers `ok`/`error`
                        // asynchronously; the error arm rolls the
                        // optimistic flag back.
                        .map(|sent| sent_note(sent, "converting to broadcast group…")),
                    // Slice CL1: `deleteChatHistory` (schema 1.8.67,
                    // line 11845). TDLib answers `ok`/`error`
                    // asynchronously; a refusal surfaces via
                    // `Session::chat_action_error`.
                    GroupConfirmAction::ClearHistory { revoke } => live
                        .driver
                        .clear_chat_history(dialog.chat_id, revoke)
                        .map(|sent| sent_note(sent, "clearing history…")),
                    // Slice B2: "Restart bot" — `deleteChatHistory` +
                    // `sendBotStartMessage` (schema lines 11845 / 12216).
                    // The bot user id is read from the session before the
                    // live borrow; a missing id fails closed with a status
                    // note, never silently.
                    GroupConfirmAction::RestartBot => match restart_bot_user_id {
                        Some(bot_user_id) => live
                            .driver
                            .restart_bot(dialog.chat_id, bot_user_id)
                            .map(|sent| sent_note(sent, "restarting bot…")),
                        None => Ok("This chat is no longer a bot chat.".to_string()),
                    },
                    // Slice CL1: chat-list "Delete chat" —
                    // `deleteChatHistory` with `remove_from_chat_list:
                    // true` (Telegram X `Tdlib.deleteChat`).
                    GroupConfirmAction::RemoveFromList => live
                        .driver
                        .remove_chat_from_list(dialog.chat_id)
                        .map(|sent| sent_note(sent, "deleting chat…")),
                    // Slice CL3: row-menu Report (`reportChat`, schema
                    // 1.8.67, line 15693). TDLib answers
                    // `ReportChatResult` asynchronously; the outcome
                    // surfaces via `Session::report_chat_outcome`.
                    GroupConfirmAction::ReportChat => live
                        .driver
                        .report_chat(dialog.chat_id)
                        .map(|sent| sent_note(sent, "reporting chat…")),
                    // Slice CL3: row-menu Block/Unblock
                    // (`setMessageSenderBlockList`, schema 1.8.67, line
                    // 14492). TDLib answers `ok`; the new state arrives
                    // via `updateChatBlockList`.
                    GroupConfirmAction::BlockUser { block } => live
                        .driver
                        .set_chat_user_blocked(dialog.chat_id, block)
                        .map(|sent| {
                            sent_note(
                                sent,
                                if block {
                                    "blocking user…"
                                } else {
                                    "unblocking user…"
                                },
                            )
                        }),
                    // Slice CL3: multi-select bulk delete — one
                    // `deleteChatHistory(remove_from_chat_list:true)`
                    // per selected chat; the selection clears on
                    // confirm. The ids come from the live selection
                    // (the dialog blocks selection changes while
                    // open), so the enum stays `Copy`.
                    GroupConfirmAction::RemoveSelectedChats => {
                        let chat_ids: Vec<ChatId> =
                            self.selected_chats.iter().map(|id| ChatId(*id)).collect();
                        let mut sent = 0;
                        for id in &chat_ids {
                            if live
                                .driver
                                .remove_chat_from_list(*id)
                                .is_ok_and(|sent| sent.is_some())
                            {
                                sent += 1;
                            }
                        }
                        let total = chat_ids.len();
                        self.selected_chats.clear();
                        Ok(format!("deleting {sent} of {total} chats…"))
                    }
                    // Slice A2: abort the pending recovery-email setup
                    // (`cancelRecoveryEmailAddressVerification`, schema
                    // 1.8.67, line 11467). The dialog carries no chat, so
                    // `dialog.chat_id` is unused here.
                    GroupConfirmAction::AbortRecoveryEmailSetup => live
                        .driver
                        .cancel_recovery_email_setup()
                        .map(|_| "aborting email setup…".to_string()),
                };
                match result {
                    Ok(note) => note,
                    Err(_) => {
                        self.group_confirm_dialog = Some(dialog);
                        "action failed".to_string()
                    }
                }
            }
            None => {
                self.group_confirm_dialog = Some(dialog);
                "chat actions need a live connection (demo)".to_string()
            }
        };
        self.status_note = note;
        cx.notify();
    }

    /// Slice G1: open the partial-quote dialog for a text message.
    fn open_quote_reply_dialog(
        &mut self,
        chat_id: ChatId,
        message_id: MessageId,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let full_text = self
            .session()
            .and_then(|session| session.histories.get(&chat_id.0))
            .and_then(|history| history.messages.get(&message_id.0))
            .and_then(|message| {
                Self::message_copyable_text(effective_content(
                    &message.content,
                    message.ephemeral.as_ref(),
                ))
            })
            .unwrap_or_default();
        if full_text.trim().is_empty() {
            self.status_note = "only text messages can be quoted".into();
            cx.notify();
            return;
        }
        self.quote_reply_dialog = Some(QuoteReplyDialog::new(
            window, cx, chat_id, message_id, full_text,
        ));
        cx.notify();
    }

    fn close_quote_reply_dialog(&mut self, cx: &mut Context<Self>) {
        self.quote_reply_dialog = None;
        cx.notify();
    }

    /// Slice G1: validate the trimmed quote against the original text
    /// and set the composer's reply with its UTF-16 offset. A quote
    /// that is no longer a verbatim substring keeps the dialog open
    /// with an explanatory note.
    fn submit_quote_reply_dialog(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let Some(dialog) = self.quote_reply_dialog.take() else {
            return;
        };
        let quote_text = dialog.input.read(cx).value();
        let quote_text = quote_text.trim();
        match quill::composer::quote_position(&dialog.full_text, quote_text) {
            Some(position) => {
                let preview = dialog.full_text.chars().take(80).collect::<String>();
                let reply = quill::composer::ComposerReplyTo::with_quote(
                    dialog.chat_id,
                    dialog.message_id,
                    preview,
                    quill::composer::QuoteSelection {
                        text: quote_text.to_string(),
                        position,
                    },
                );
                self.begin_reply_to(reply, window, cx);
                self.status_note = "quoting part of the message".into();
            }
            None => {
                self.quote_reply_dialog = Some(dialog);
                self.status_note = "the quote must be an unedited part of the message".into();
            }
        }
        cx.notify();
    }

    /// Phase D3a: open the invite-link create dialog for a chat.
    fn open_invite_link_dialog(
        &mut self,
        chat_id: ChatId,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.invite_link_dialog = Some(InviteLinkDialog::new(window, cx, chat_id));
        cx.notify();
    }

    /// Phase D3a: close the invite-link create dialog.
    fn close_invite_link_dialog(&mut self, cx: &mut Context<Self>) {
        self.invite_link_dialog = None;
        cx.notify();
    }

    /// Phase D3a: validate the dialog and send `createChatInviteLink`.
    fn submit_invite_link_dialog(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let (chat_id, name, expiration_date, member_limit, creates_join_request) =
            match self.invite_link_dialog.as_ref() {
                Some(dialog) => {
                    let name = dialog.name_input.read(cx).value().to_string();
                    let days = dialog.expiration_days_input.read(cx).value().to_string();
                    let limit = dialog.member_limit_input.read(cx).value().to_string();
                    let days: i64 = match days.trim().parse() {
                        Ok(days) if days >= 0 => days,
                        _ => {
                            self.status_note =
                                "expiration must be a non-negative number of days".into();
                            cx.notify();
                            return;
                        }
                    };
                    let member_limit: i32 = match limit.trim().parse() {
                        Ok(limit) if limit >= 0 => limit,
                        _ => {
                            self.status_note = "member limit must be a non-negative number".into();
                            cx.notify();
                            return;
                        }
                    };
                    let now = std::time::SystemTime::now()
                        .duration_since(std::time::UNIX_EPOCH)
                        .map(|duration| duration.as_secs() as i64)
                        .unwrap_or(0);
                    let expiration_date = if days == 0 {
                        0
                    } else {
                        now.saturating_add(days.saturating_mul(86_400))
                            .min(i64::from(i32::MAX)) as i32
                    };
                    (
                        dialog.chat_id,
                        name,
                        expiration_date,
                        member_limit,
                        dialog.creates_join_request,
                    )
                }
                None => return,
            };
        if let Some(live) = self.live.as_mut() {
            match live.driver.create_chat_invite_link(
                chat_id,
                &name,
                expiration_date,
                member_limit,
                creates_join_request,
            ) {
                Ok(_) => {
                    self.invite_link_dialog = None;
                    self.status_note = "creating invite link…".into();
                }
                Err(_) => {
                    self.status_note = "could not create invite link".into();
                }
            }
        } else {
            // Screenshot demos have no live driver; close the dialog honestly.
            self.invite_link_dialog = None;
            self.status_note = "invite links need a live connection (demo)".into();
        }
        let _ = window;
        cx.notify();
    }

    fn kill_shared_player(&mut self) {
        if let Some(mut child) = self.voice_player.take() {
            let _ = child.kill();
            let _ = child.wait();
        }
    }

    fn stop_voice_playback(&mut self) {
        if self.playing_voice.is_some() {
            self.kill_shared_player();
        }
        // Save the position before clearing the id: clear_playback_state
        // reads active_playback_id().
        self.clear_playback_state();
        self.playing_voice = None;
    }

    fn stop_audio_playback(&mut self) {
        if self.playing_audio.is_some() {
            self.kill_shared_player();
        }
        self.clear_playback_state();
        self.playing_audio = None;
        self.pending_audio_play = None;
    }

    /// Drop the seek-bar state for the active track (clock, slider entity,
    /// scrub preview). Idempotent: both stop functions call it. The
    /// remembered per-message position in `playback_positions` is kept so a
    /// stopped row still shows where it got to.
    fn clear_playback_state(&mut self) {
        if let (Some(message_id), Some(clock)) =
            (self.active_playback_id(), self.playback_clock.as_ref())
        {
            self.playback_positions
                .insert(message_id, clock.elapsed_secs());
        }
        self.playback_clock = None;
        self.playback_path = None;
        self.seek_slider = None;
        self.seek_scrubbing = false;
        self.seek_preview_secs = None;
    }

    /// Message id of the active (playing or paused) track, if any.
    fn active_playback_id(&self) -> Option<MessageId> {
        self.playing_voice.or(self.playing_audio)
    }

    /// Kind of the active track, for status notes.
    fn active_playback_kind(&self) -> PlaybackKind {
        if self.playing_voice.is_some() {
            PlaybackKind::Voice
        } else {
            PlaybackKind::Audio
        }
    }

    /// Mark the given row as the active track: sets `playing_voice` /
    /// `playing_audio`, starts the playback clock at `offset_secs`, builds
    /// the seek slider entity, and starts the progress tick. Does not spawn
    /// ffplay — the caller does that (the screenshot demo fakes playback
    /// without a subprocess).
    fn begin_track_playback(
        &mut self,
        kind: PlaybackKind,
        message_id: MessageId,
        duration_secs: f64,
        offset_secs: f64,
        cx: &mut Context<Self>,
    ) {
        self.stop_voice_playback();
        self.stop_audio_playback();
        self.stop_viewer_video();
        self.playback_error = None;
        match kind {
            PlaybackKind::Voice => self.playing_voice = Some(message_id),
            PlaybackKind::Audio => self.playing_audio = Some(message_id),
        }
        let mut clock = PlaybackClock::new(duration_secs);
        clock.set_rate(self.playback_speed);
        clock.seek(offset_secs);
        clock.resume();
        self.playback_clock = Some(clock);
        let slider = cx.new(|_| {
            SliderState::new()
                .min(0.0)
                .max(duration_secs.max(0.1) as f32)
                .step(0.1)
                .default_value(offset_secs.clamp(0.0, duration_secs.max(0.0)) as f32)
        });
        cx.subscribe(&slider, |this, _entity, event: &SliderEvent, cx| {
            this.on_seek_event(event, cx);
        })
        .detach();
        self.seek_slider = Some(slider);
        self.seek_scrubbing = false;
        self.seek_preview_secs = None;
        self.spawn_playback_tick(cx);
    }

    /// Spawn ffplay for `path`, seeking to `offset_secs` first when positive.
    /// ffplay takes no seek commands on stdin, so seeking restarts the player
    /// with `-ss` (input seeking — fast on local files; see DECISIONS.md).
    /// Returns true when the child spawned.
    fn spawn_ffplay(&mut self, path: &std::path::Path, offset_secs: f64) -> bool {
        self.kill_shared_player();
        let mut command = self.ffplay_command(offset_secs);
        match command
            .arg(path)
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .spawn()
        {
            Ok(child) => {
                self.voice_player = Some(child);
                self.playback_error = None;
                true
            }
            // MED1: honest error instead of the old silent failure.
            Err(_) => {
                self.playback_error = Some("audio player (ffplay) couldn't start".into());
                false
            }
        }
    }

    /// MED1: ffplay command with volume (`-volume`) and speed
    /// (`-af atempo=` when != 1x) baked in. `atempo` only accepts
    /// 0.5–2.0 — the TGX speed span, enforced by `PlaybackClock`.
    fn ffplay_command(&self, offset_secs: f64) -> Command {
        let mut command = Command::new("ffplay");
        command.args(["-nodisp", "-autoexit", "-loglevel", "quiet"]);
        if offset_secs > 0.05 {
            command.arg("-ss").arg(format!("{offset_secs:.1}"));
        }
        let volume = (self.playback_volume.clamp(0.0, 1.0) * 100.0).round() as i32;
        command.arg("-volume").arg(volume.to_string());
        if (self.playback_speed - 1.0).abs() > 0.01 {
            command
                .arg("-af")
                .arg(format!("atempo={:.2}", self.playback_speed));
        }
        command
    }

    /// Restart the active track's player at `offset_secs` (seek while playing).
    fn restart_player_at(&mut self, offset_secs: f64) {
        if let Some(path) = self.playback_path.clone() {
            self.spawn_ffplay(&path, offset_secs);
        }
    }

    /// Pause the active track: freeze the clock, kill ffplay, keep the row
    /// active so the seek bar stays interactive and Play resumes from here.
    fn pause_active_playback(&mut self) {
        let id = self.active_playback_id();
        if let Some(clock) = self.playback_clock.as_mut() {
            clock.pause();
            if let Some(id) = id {
                self.playback_positions.insert(id, clock.elapsed_secs());
            }
        }
        self.kill_shared_player();
    }

    /// Resume the active track from the frozen clock position.
    fn resume_active_playback(&mut self) {
        let offset = self.playback_clock.as_ref().map(|c| c.elapsed_secs());
        let path = self.playback_path.clone();
        match (offset, path) {
            (Some(offset), Some(path)) => {
                self.spawn_ffplay(&path, offset);
                if let Some(clock) = self.playback_clock.as_mut() {
                    clock.resume();
                }
            }
            _ => {
                self.stop_voice_playback();
                self.stop_audio_playback();
            }
        }
    }

    /// `SliderEvent` sink for the active row's seek slider.
    fn on_seek_event(&mut self, event: &SliderEvent, cx: &mut Context<Self>) {
        match event {
            SliderEvent::Change(value) => {
                // Drag (or track click) in progress: show the preview in the
                // time label, but don't touch the player until Release.
                self.seek_scrubbing = true;
                self.seek_preview_secs = Some(f64::from(value.end()));
                cx.notify();
            }
            SliderEvent::Release(value) => {
                self.seek_scrubbing = false;
                self.seek_preview_secs = None;
                self.seek_active_to(f64::from(value.end()), cx);
            }
        }
    }

    /// Apply a finished seek: clamp, move the clock, and restart ffplay at
    /// the new offset when the track is playing. Seeking while paused just
    /// moves the frozen position (no player restart).
    fn seek_active_to(&mut self, secs: f64, cx: &mut Context<Self>) {
        let Some(clock) = self.playback_clock.as_mut() else {
            return;
        };
        clock.seek(secs);
        let offset = clock.elapsed_secs();
        let was_playing = clock.is_playing();
        if let Some(id) = self.active_playback_id() {
            self.playback_positions.insert(id, offset);
        }
        if was_playing {
            self.restart_player_at(offset);
            self.status_note = format!(
                "{} — seek {}",
                match self.active_playback_kind() {
                    PlaybackKind::Voice => "playing voice note",
                    PlaybackKind::Audio => "playing audio",
                },
                format_voice_duration(offset as i32)
            );
        }
        cx.notify();
    }

    /// 250 ms progress tick while a track is active: re-renders so the seek
    /// bar advances, and auto-stops when the clock reaches the duration
    /// (ffplay `-autoexit` exits on its own; this clears our state to match).
    fn spawn_playback_tick(&mut self, cx: &mut Context<Self>) {
        if self.playback_tick {
            return;
        }
        self.playback_tick = true;
        cx.spawn(async move |this, cx| {
            loop {
                cx.background_executor()
                    .timer(Duration::from_millis(250))
                    .await;
                let cont = this
                    .update(cx, |this, cx| {
                        let active = this.active_playback_id().is_some();
                        if !active {
                            return false;
                        }
                        let finished = this
                            .playback_clock
                            .as_ref()
                            .is_some_and(|clock| clock.is_playing() && clock.finished());
                        if finished && !this.seek_scrubbing {
                            // Capture the id first: the stops below save the
                            // (now end-of-track) position via clear_playback_state,
                            // then reset to 0.0 so replay-after-finish starts at the top.
                            let finished_id = this.active_playback_id();
                            this.stop_voice_playback();
                            this.stop_audio_playback();
                            if let Some(id) = finished_id {
                                this.playback_positions.insert(id, 0.0);
                            }
                            this.status_note = "playback finished".into();
                        }
                        cx.notify();
                        true
                    })
                    .unwrap_or(false);
                if !cont {
                    break;
                }
            }
            let _ = this.update(cx, |this, _| {
                this.playback_tick = false;
            });
        })
        .detach();
    }

    /// Push the playback clock into the seek slider entity so the thumb
    /// follows elapsed time. Called at the top of `render` (the tick has no
    /// `&mut Window`, which `SliderState::set_value` needs). Skipped while
    /// scrubbing so the user's drag is never fought.
    fn sync_seek_slider(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if self.seek_scrubbing {
            return;
        }
        if let (Some(slider), Some(clock)) =
            (self.seek_slider.as_ref(), self.playback_clock.as_ref())
        {
            let value = clock.elapsed_secs().clamp(0.0, clock.duration_secs()) as f32;
            // `set_value` calls `cx.notify()` unconditionally — only push when
            // the value actually changed, otherwise this render-triggered sync
            // loops at frame rate instead of the tick cadence.
            let changed = slider.read(cx).value() != SliderValue::Single(value);
            if changed {
                slider.update(cx, |state, cx| {
                    state.set_value(value, window, cx);
                });
            }
        }
    }

    /// View model for one audio/voice row's seek bar.
    fn seek_bar_view(&self, message_id: MessageId, duration_secs: f64) -> SeekBarView {
        let active = self.active_playback_id() == Some(message_id);
        if active {
            let display = self.seek_preview_secs.or_else(|| {
                self.playback_clock
                    .as_ref()
                    .map(|clock| clock.elapsed_secs())
            });
            SeekBarView {
                slider: self.seek_slider.clone(),
                display_secs: display.unwrap_or(0.0),
                duration_secs,
                is_playing: self
                    .playback_clock
                    .as_ref()
                    .is_some_and(PlaybackClock::is_playing),
                // MED1: speed/mute/error shown on the active row.
                speed: self.playback_speed,
                muted: self.playback_volume < 0.01,
                error: self.playback_error.clone(),
            }
        } else {
            SeekBarView {
                slider: None,
                display_secs: self
                    .playback_positions
                    .get(&message_id)
                    .copied()
                    .unwrap_or(0.0),
                duration_secs,
                is_playing: false,
                speed: self.playback_speed,
                muted: false,
                error: None,
            }
        }
    }

    fn toggle_voice_playback(
        &mut self,
        chat_id: ChatId,
        message_id: MessageId,
        file_id: FileId,
        listened: bool,
        duration_secs: f64,
        cx: &mut Context<Self>,
    ) {
        if self.playing_voice == Some(message_id) {
            // Active row: pause ↔ resume (the row stays active so the seek
            // bar keeps working and Play resumes from the frozen position).
            let playing = self
                .playback_clock
                .as_ref()
                .is_some_and(PlaybackClock::is_playing);
            if playing {
                self.pause_active_playback();
                self.status_note = "voice note paused".into();
            } else {
                self.resume_active_playback();
                self.status_note = "playing voice note".into();
            }
            cx.notify();
            return;
        }
        let path = self.session().and_then(|session| {
            session
                .files
                .get(&file_id.0)
                .and_then(|file| file.usable_path())
                .map(str::to_string)
        });
        let Some(path) = path else {
            self.request_media_download(file_id, None, cx);
            return;
        };
        let roots = self.media_display_roots();
        let Some(safe) = sandboxed_display_path(&path, &roots) else {
            self.status_note = "voice file is outside the account files".into();
            cx.notify();
            return;
        };
        self.stop_video_playback();
        let offset = self
            .playback_positions
            .get(&message_id)
            .copied()
            .unwrap_or(0.0);
        self.begin_track_playback(PlaybackKind::Voice, message_id, duration_secs, offset, cx);
        self.playback_path = Some(safe.clone().into());
        if !listened {
            self.mark_voice_opened(chat_id, message_id);
        }
        self.spawn_ffplay(&safe, offset);
        self.status_note = if self.voice_player.is_some() {
            "playing voice note".into()
        } else {
            "playing voice note (no audio player)".into()
        };
        cx.notify();
    }

    fn toggle_audio_playback(
        &mut self,
        message_id: MessageId,
        file_id: FileId,
        duration_secs: f64,
        cx: &mut Context<Self>,
    ) {
        if self.playing_audio == Some(message_id) {
            // Active row: pause ↔ resume (see voice toggle).
            let playing = self
                .playback_clock
                .as_ref()
                .is_some_and(PlaybackClock::is_playing);
            if playing {
                self.pause_active_playback();
                self.status_note = "audio paused".into();
            } else {
                self.resume_active_playback();
                self.status_note = "playing audio".into();
            }
            cx.notify();
            return;
        }
        let path = self.session().and_then(|session| {
            session
                .files
                .get(&file_id.0)
                .and_then(|file| file.usable_path())
                .map(str::to_string)
        });
        let Some(path) = path else {
            self.pending_audio_play = Some((message_id, file_id, duration_secs));
            self.request_media_download(file_id, None, cx);
            self.status_note = "downloading audio".into();
            return;
        };
        self.pending_audio_play = None;
        let roots = self.media_display_roots();
        let Some(safe) = sandboxed_display_path(&path, &roots) else {
            self.status_note = "audio file is outside the account files".into();
            cx.notify();
            return;
        };
        self.stop_video_playback();
        self.stop_animation_playback();
        let offset = self
            .playback_positions
            .get(&message_id)
            .copied()
            .unwrap_or(0.0);
        self.begin_track_playback(PlaybackKind::Audio, message_id, duration_secs, offset, cx);
        self.playback_path = Some(safe.clone().into());
        self.spawn_ffplay(&safe, offset);
        self.status_note = if self.voice_player.is_some() {
            "playing audio".into()
        } else {
            "playing audio (no audio player)".into()
        };
        cx.notify();
    }

    fn resume_pending_audio(&mut self, cx: &mut Context<Self>) {
        let Some((message_id, file_id, duration_secs)) = self.pending_audio_play else {
            return;
        };
        let ready = self.session().is_some_and(|session| {
            session
                .files
                .get(&file_id.0)
                .and_then(|file| file.usable_path())
                .is_some()
        });
        if ready {
            self.toggle_audio_playback(message_id, file_id, duration_secs, cx);
        }
    }

    fn mark_voice_opened(&mut self, chat_id: ChatId, message_id: MessageId) {
        if let Some(live) = self.live.as_mut() {
            let _ = live.driver.open_voice_content(chat_id, message_id);
            return;
        }
        let Some(session) = self.demo_session.as_mut() else {
            return;
        };
        let dyn_sink: Arc<dyn DiagnosticSink> = self.demo_sink.clone();
        let json = format!(
            r#"{{"@type":"updateMessageContentOpened","chat_id":{},"message_id":{}}}"#,
            chat_id.0, message_id.0
        );
        if let Some(owned) = copy_and_parse(&json, &self.demo_seq, &dyn_sink) {
            session.apply(owned);
        }
    }

    fn gif_panel_open(&self) -> bool {
        self.session().is_some_and(|session| session.gifs.open)
    }

    fn toggle_gif_panel(&mut self, cx: &mut Context<Self>) {
        if self.recording_active() {
            self.cancel_recording(cx);
        }
        if self.gif_panel_open() {
            self.close_gif_panel(cx);
            return;
        }
        if self.sticker_panel_open() {
            self.close_sticker_panel(cx);
        }
        if let Some(live) = self.live.as_mut() {
            self.status_note = match live.driver.open_gif_panel() {
                Ok(_) => "GIFs".into(),
                Err(_) => "could not open GIFs".into(),
            };
        } else if let Some(session) = self.demo_session.as_mut() {
            session.gifs.open = true;
            self.status_note = "GIFs".into();
        }
        cx.notify();
    }

    fn close_gif_panel(&mut self, cx: &mut Context<Self>) {
        if let Some(live) = self.live.as_mut() {
            live.driver.close_gif_panel();
        } else if let Some(session) = self.demo_session.as_mut() {
            session.gifs.close();
        }
        self.status_note = "GIFs closed".into();
        cx.notify();
    }

    fn send_gif_pick(
        &mut self,
        file_id: FileId,
        duration: i32,
        width: i32,
        height: i32,
        cx: &mut Context<Self>,
    ) {
        let chat_id = self.session().and_then(|session| session.open_chat);
        let Some(chat_id) = chat_id else {
            return;
        };
        // Phase A1: slow-mode gate applies to GIF sends too.
        if self.slow_mode_blocked(chat_id, cx) {
            return;
        }
        let reply = self
            .pending_reply
            .as_ref()
            .filter(|reply| reply.chat_id == chat_id)
            .map(|reply| quill::telegram::SendReply {
                message_id: reply.message_id,
                quote: reply
                    .quote
                    .as_ref()
                    .map(|quote| (quote.text.clone(), quote.position)),
            });
        let sent = if let Some(live) = self.live.as_mut() {
            self.status_note = match live.driver.send_animation(
                chat_id,
                quill::telegram::requests::AnimationSend {
                    file_id,
                    duration,
                    width,
                    height,
                    reply_to: reply,
                    // Parity slice 4: the driver addresses the open topic
                    // from the session; the UI passes no topic.
                    topic_id: None,
                },
            ) {
                Ok(_) => "sending GIF".into(),
                Err(_) => "could not send GIF".into(),
            };
            self.status_note == "sending GIF"
        } else if self.demo_session.is_some() {
            self.apply_demo_gif(chat_id, file_id, duration, width, height, reply);
            self.status_note = "demo GIF applied locally (no live Telegram)".into();
            true
        } else {
            false
        };
        if sent {
            self.consume_sent_reply(chat_id, cx);
        }
        cx.notify();
    }

    fn sticker_panel_open(&self) -> bool {
        self.session().is_some_and(|session| session.stickers.open)
    }

    fn toggle_sticker_panel(&mut self, cx: &mut Context<Self>) {
        if self.recording_active() {
            self.cancel_recording(cx);
        }
        if self.sticker_panel_open() {
            self.close_sticker_panel(cx);
            return;
        }
        if self.gif_panel_open() {
            self.close_gif_panel(cx);
        }
        if let Some(live) = self.live.as_mut() {
            self.status_note = match live.driver.open_sticker_panel() {
                Ok(_) => "stickers".into(),
                Err(_) => "could not open stickers".into(),
            };
        } else if let Some(session) = self.demo_session.as_mut() {
            session.stickers.open = true;
            self.status_note = "stickers".into();
        }
        cx.notify();
    }

    fn close_sticker_panel(&mut self, cx: &mut Context<Self>) {
        if let Some(live) = self.live.as_mut() {
            live.driver.close_sticker_panel();
        } else if let Some(session) = self.demo_session.as_mut() {
            session.stickers.close();
        }
        self.status_note = "stickers closed".into();
        cx.notify();
    }

    fn select_sticker_set(&mut self, set_id: i64, cx: &mut Context<Self>) {
        if let Some(live) = self.live.as_mut() {
            self.status_note = match live.driver.select_sticker_set(set_id) {
                Ok(_) => "sticker set".into(),
                Err(_) => "could not open sticker set".into(),
            };
        } else if let Some(session) = self.demo_session.as_mut() {
            session.select_sticker_set(set_id);
            self.status_note = "sticker set".into();
        }
        cx.notify();
    }

    fn send_sticker_pick(
        &mut self,
        file_id: FileId,
        emoji: String,
        width: i32,
        height: i32,
        thumb: Option<(FileId, i32, i32)>,
        cx: &mut Context<Self>,
    ) {
        let chat_id = self.session().and_then(|session| session.open_chat);
        let Some(chat_id) = chat_id else {
            return;
        };
        // Phase A1: slow-mode gate applies to sticker sends too.
        if self.slow_mode_blocked(chat_id, cx) {
            return;
        }
        let reply = self
            .pending_reply
            .as_ref()
            .filter(|reply| reply.chat_id == chat_id)
            .map(|reply| quill::telegram::SendReply {
                message_id: reply.message_id,
                quote: reply
                    .quote
                    .as_ref()
                    .map(|quote| (quote.text.clone(), quote.position)),
            });
        let sent = if let Some(live) = self.live.as_mut() {
            self.status_note = match live.driver.send_sticker(
                chat_id,
                quill::telegram::requests::StickerSend {
                    file_id,
                    emoji: &emoji,
                    width,
                    height,
                    thumb,
                    reply_to: reply,
                    // Parity slice 4: the driver addresses the open topic
                    // from the session; the UI passes no topic.
                    topic_id: None,
                },
            ) {
                Ok(_) => "sticker sent".into(),
                Err(_) => "could not send sticker".into(),
            };
            self.status_note == "sticker sent"
        } else if self.demo_session.is_some() {
            self.apply_demo_sticker(chat_id, &emoji, file_id, reply);
            self.status_note = "sticker sent".into();
            true
        } else {
            false
        };
        if sent {
            self.consume_sent_reply(chat_id, cx);
        }
        cx.notify();
    }

    /// Sticker/GIF/voice sends consume the composer reply. Drop it from the UI
    /// and from the stored draft, and keep any unsent text.
    fn consume_sent_reply(&mut self, chat_id: ChatId, cx: &mut Context<Self>) {
        self.pending_reply = None;
        if self.pending_edit.is_some() {
            self.saved_edit_reply = None;
            return;
        }
        let text = self.composer.read(cx).value().to_string();
        self.save_chat_draft(chat_id, &text, None, false, cx);
    }

    fn toggle_emoji_reaction(
        &mut self,
        chat_id: ChatId,
        message_id: MessageId,
        emoji: String,
        cx: &mut Context<Self>,
    ) {
        if self.live.is_some() {
            let result = self
                .live
                .as_mut()
                .expect("live")
                .driver
                .toggle_message_reaction(chat_id, message_id, &emoji);
            self.status_note = match result {
                Ok(_) => "updating reaction…".into(),
                Err(_) => "could not update reaction".into(),
            };
            cx.notify();
            return;
        }
        if self.demo_session.is_some() {
            self.apply_demo_reaction_toggle(chat_id, message_id, &emoji);
            self.status_note = "reaction updated".into();
            cx.notify();
        }
    }

    fn apply_demo_reaction_toggle(&mut self, chat_id: ChatId, message_id: MessageId, emoji: &str) {
        let Some(session) = self.demo_session.as_mut() else {
            return;
        };
        let current = session
            .histories
            .get(&chat_id.0)
            .and_then(|history| history.messages.get(&message_id.0))
            .and_then(|message| message.interaction_info.clone());
        let next = toggle_chosen_emoji_reaction(current.as_ref(), emoji);
        let json = interaction_info_update_json(chat_id, message_id, &next);
        let dyn_sink: Arc<dyn DiagnosticSink> = self.demo_sink.clone();
        if let Some(owned) = copy_and_parse(&json, &self.demo_seq, &dyn_sink) {
            session.apply(owned);
        }
    }

    /// Phase 4.2: poll option tap → `setPollAnswer` through the live driver
    /// (same guard style as the other send methods). In screenshot demos the
    /// tap flips the chosen marks locally (no live Telegram); the fixture
    /// already carries voted counts.
    fn vote_on_poll(
        &mut self,
        chat_id: ChatId,
        message_id: MessageId,
        option_index: usize,
        cx: &mut Context<Self>,
    ) {
        if let Some(live) = self.live.as_mut() {
            let result = live
                .driver
                .send_poll_answer(chat_id, message_id, option_index);
            self.status_note = match result {
                Ok(_) => "voting…".into(),
                Err(_) => "could not vote".into(),
            };
            cx.notify();
            return;
        }
        if self.demo_session.is_some() {
            self.apply_demo_poll_vote(chat_id, message_id, option_index);
            self.status_note = "vote updated (demo)".into();
            cx.notify();
        }
    }

    /// Demo-only vote: resolve the tap with the same `poll_answer_for_tap`
    /// semantics as the live driver, then flip the chosen marks in place
    /// (counts stay as the fixture set them).
    fn apply_demo_poll_vote(
        &mut self,
        chat_id: ChatId,
        message_id: MessageId,
        option_index: usize,
    ) {
        let Some(session) = self.demo_session.as_mut() else {
            return;
        };
        let answer = session
            .histories
            .get(&chat_id.0)
            .and_then(|history| history.messages.get(&message_id.0))
            .and_then(|message| match &message.content {
                MessageContent::Poll(poll) => Some(poll.poll.clone()),
                _ => None,
            })
            .and_then(|poll| quill::poll::poll_answer_for_tap(&poll, option_index));
        let Some(answer) = answer else {
            return;
        };
        if let Some(history) = session.histories.get_mut(&chat_id.0)
            && let Some(message) = history.messages.get_mut(&message_id.0)
            && let MessageContent::Poll(poll_content) = &mut message.content
        {
            let chosen: HashSet<i32> = answer.into_iter().collect();
            for (index, option) in poll_content.poll.options.iter_mut().enumerate() {
                option.is_chosen = chosen.contains(&(index as i32));
            }
        }
    }

    /// Phase 4.2: open the poll creation dialog above the composer.
    fn open_poll_dialog(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.poll_dialog = Some(PollDialog::new(window, cx));
        if let Some(dialog) = &self.poll_dialog {
            dialog
                .question_input
                .update(cx, |input, cx| input.focus(window, cx));
        }
        cx.notify();
    }

    fn close_poll_dialog(&mut self, cx: &mut Context<Self>) {
        self.poll_dialog = None;
        cx.notify();
    }

    // ------------------------------------------------------------------
    // Phase 6: Contacts tab, info panels, add-contact dialog.
    // ------------------------------------------------------------------

    /// Sidebar "Chats | Contacts | Calls" tabs (Ready mode). Other modes
    /// keep the plain "Chats" title.
    fn list_tabs(&self, cx: &mut Context<Self>) -> impl IntoElement {
        if self.pane_mode() != PaneMode::Ready {
            return div().font_semibold().child("Chats").into_any_element();
        }
        let chats_active = !self.contacts_tab_open && !self.calls_tab_open;
        let tab = |id: &'static str, label: &'static str, active: bool| {
            div()
                .id(id)
                .cursor_pointer()
                .px_2()
                .py_1()
                .rounded_md()
                .text_sm()
                .font_medium()
                .bg(if active {
                    cx.theme().accent.opacity(0.15)
                } else {
                    cx.theme().sidebar
                })
                .child(label)
        };
        div()
            .flex()
            .items_center()
            .gap_2()
            .child(
                tab("tab-chats", "Chats", chats_active).on_click(cx.listener(|this, _, _, cx| {
                    this.open_chats_tab(cx);
                })),
            )
            .child(
                tab("tab-contacts", "Contacts", self.contacts_tab_open).on_click(cx.listener(
                    |this, _, _, cx| {
                        this.open_contacts_tab(cx);
                    },
                )),
            )
            // Phase C2i: Recent-calls tab (server-side `searchCallMessages`
            // history + call settings).
            .child(
                tab("tab-calls", "Calls", self.calls_tab_open).on_click(cx.listener(
                    |this, _, _, cx| {
                        this.open_calls_tab(cx);
                    },
                )),
            )
            .into_any_element()
    }

    /// Phase 9.1: tdesktop-style active-stories tray above the chat list.
    /// Each entry shows the poster's avatar with an unread (accent) or read
    /// (muted) ring; tapping opens the story viewer on that chat's latest
    /// story (`getStory` prefetches any missing story details first).
    /// Phase 9.3: the row always renders — the leading "+" tile is the
    /// story composer entry point (kept visible even with no active
    /// stories).
    fn story_tray(&self, cx: &mut Context<Self>) -> AnyElement {
        let entries: Vec<quill::telegram::envelope::ChatActiveStoriesView> = self
            .session()
            .map(|s| s.ordered_story_tray().into_iter().cloned().collect())
            .unwrap_or_default();
        let mut row = div()
            .id("story-tray")
            .flex()
            .flex_row()
            .flex_wrap()
            .items_start()
            .gap_2()
            .px_3()
            .py_2()
            .child(
                div()
                    .id("story-tray-add")
                    .cursor_pointer()
                    .flex()
                    .flex_col()
                    .items_center()
                    .w(px(60.))
                    .gap_1()
                    .child(
                        div()
                            .rounded_full()
                            .p(px(2.))
                            .border_2()
                            .border_color(cx.theme().accent)
                            .child(
                                div()
                                    .w(px(40.))
                                    .h(px(40.))
                                    .rounded_full()
                                    .flex()
                                    .items_center()
                                    .justify_center()
                                    .text_xl()
                                    .text_color(cx.theme().accent)
                                    .child("+"),
                            ),
                    )
                    .child(div().text_xs().child("Post"))
                    .on_click(cx.listener(|this, _, window, cx| {
                        this.open_story_composer(window, cx);
                    })),
            );
        for entry in entries {
            let unread = entry.has_unread();
            let chat_id = entry.chat_id;
            let title = self
                .session()
                .and_then(|s| s.chats.get(&chat_id))
                .map(|chat| chat.title.clone())
                .unwrap_or_else(|| format!("Chat {chat_id}"));
            let latest_story = entry
                .stories
                .iter()
                .map(|info| info.story_id)
                .max()
                .unwrap_or(0);
            row = row.child(
                div()
                    .id(("story-tray-item", chat_id as u64))
                    .cursor_pointer()
                    .flex()
                    .flex_col()
                    .items_center()
                    .w(px(60.))
                    .gap_1()
                    .child(
                        div()
                            .rounded_full()
                            .p(px(2.))
                            .border_2()
                            .border_color(if unread {
                                cx.theme().accent
                            } else {
                                cx.theme().border
                            })
                            .child(initials_avatar(&title, 40.0)),
                    )
                    .child(div().text_xs().max_w(px(60.)).child(title))
                    .on_click(cx.listener(move |this, _, _, cx| {
                        this.open_story_viewer(ChatId(chat_id), latest_story, cx);
                    })),
            );
        }
        row.into_any_element()
    }

    fn open_chats_tab(&mut self, cx: &mut Context<Self>) {
        self.contacts_tab_open = false;
        self.calls_tab_open = false;
        cx.notify();
    }

    fn open_contacts_tab(&mut self, cx: &mut Context<Self>) {
        self.contacts_tab_open = true;
        self.calls_tab_open = false;
        if let Some(live) = self.live.as_mut()
            && let Err(err) = live.driver.fetch_contacts()
        {
            self.status_note = format!("contacts request failed: {err:?}");
        }
        cx.notify();
    }

    /// Phase C2i: open the Recent-calls tab — first page of the
    /// server-side call history plus both call privacy settings. Demo
    /// mode injects synthetic data instead (screenshot proof).
    fn open_calls_tab(&mut self, cx: &mut Context<Self>) {
        self.contacts_tab_open = false;
        self.calls_tab_open = true;
        if let Some(live) = self.live.as_mut() {
            if let Err(err) = live.driver.fetch_call_history() {
                self.status_note = format!("call history request failed: {err:?}");
            }
            if let Err(err) = live.driver.fetch_call_privacy() {
                self.status_note = format!("call privacy request failed: {err:?}");
            }
        }
        cx.notify();
    }

    /// Phase 7.1: folder tabs (`Main` + `updateChatFolders` folders) above
    /// the search field. Selecting a folder filters the chat list to
    /// `chatListFolder` chats; selecting it live also fires a single-shot
    /// `loadChats(chatListFolder)` so TDLib delivers the folder's chats.
    /// Only rendered when the account actually has folders.
    fn folder_tabs(&self, cx: &mut Context<Self>) -> impl IntoElement {
        let folders: Vec<(i32, String)> = self
            .session()
            .map(|s| {
                s.chat_folders
                    .iter()
                    .map(|f| (f.id, f.name.clone()))
                    .collect()
            })
            .unwrap_or_default();
        let selected = self.folder_tab;
        let mut row = div()
            .id("folder-tabs")
            .flex()
            .flex_row()
            .flex_wrap()
            .items_center()
            .gap_1();
        // Parity slice: the manage entry is always present so folders can
        // be created even when the account has none yet.
        let tabs: Vec<(Option<i32>, String)> = std::iter::once((None, "Main".to_string()))
            .chain(folders.into_iter().map(|(id, name)| (Some(id), name)))
            .collect();
        for (folder, name) in tabs {
            let active = selected == folder;
            let id = match folder {
                Some(folder_id) => format!("tab-folder-{folder_id}"),
                None => "tab-folder-main".to_string(),
            };
            row = row.child(
                div()
                    .id(id)
                    .cursor_pointer()
                    .px_2()
                    .py_1()
                    .rounded_md()
                    .text_xs()
                    .font_medium()
                    .bg(if active {
                        cx.theme().accent.opacity(0.15)
                    } else {
                        cx.theme().sidebar
                    })
                    .child(name)
                    .on_click(cx.listener(move |this, _, _, cx| {
                        this.open_folder_tab(folder, cx);
                    })),
            );
        }
        row = row.child(
            Button::new("folder-manage")
                .label("⋯")
                .ghost()
                .on_click(cx.listener(|this, _, _, cx| {
                    this.open_folder_manage(cx);
                })),
        );
        // Slice CL2: category filters (TGX `ChatFilter` unread category
        // and the archive pager category). They filter the loaded model
        // — never the server query. `Archived` is global, so it leaves
        // any folder tab.
        for (filter, name) in [
            (ChatListFilter::Unread, "Unread"),
            (ChatListFilter::Archived, "Archived"),
        ] {
            let active = self.chat_filter == filter;
            let id = match filter {
                ChatListFilter::Unread => "tab-filter-unread",
                ChatListFilter::Archived => "tab-filter-archived",
                ChatListFilter::All => "tab-filter-all",
            };
            row = row.child(
                div()
                    .id(id)
                    .cursor_pointer()
                    .px_2()
                    .py_1()
                    .rounded_md()
                    .text_xs()
                    .font_medium()
                    .bg(if active {
                        cx.theme().accent.opacity(0.15)
                    } else {
                        cx.theme().sidebar
                    })
                    .child(name)
                    .on_click(cx.listener(move |this, _, _, cx| {
                        this.chat_filter = filter;
                        if filter == ChatListFilter::Archived {
                            this.folder_tab = None;
                        }
                        cx.notify();
                    })),
            );
        }
        row.into_any_element()
    }

    fn open_folder_tab(&mut self, folder: Option<i32>, cx: &mut Context<Self>) {
        self.folder_tab = folder;
        self.chat_filter = ChatListFilter::All;
        self.contacts_tab_open = false;
        if let (Some(live), Some(folder_id)) = (self.live.as_mut(), folder)
            && let Err(err) = live.driver.load_folder_chats(folder_id)
        {
            self.status_note = format!("folder load failed: {err:?}");
        }
        cx.notify();
    }

    /// Slice CL2: pin-drag drop — moves the dragged pinned chat to the
    /// drop target's slot, then sends the full reordered pinned-id list
    /// via `setPinnedChats` (TGX `ChatsAdapter.movePinnedChat`). A drop
    /// onto its own row is a no-op.
    fn drop_pinned_chat(
        &mut self,
        dragged: ChatId,
        archived: bool,
        target: ChatId,
        cx: &mut Context<Self>,
    ) {
        if dragged == target {
            return;
        }
        let mut ids = match self.session() {
            Some(s) => s.pinned_chat_ids(archived),
            None => return,
        };
        if !ids.contains(&dragged.0) || !ids.contains(&target.0) {
            return;
        }
        ids.retain(|id| *id != dragged.0);
        let at = ids
            .iter()
            .position(|id| *id == target.0)
            .unwrap_or(ids.len());
        ids.insert(at, dragged.0);
        if let Some(live) = self.live.as_mut() {
            if let Err(err) = live.driver.set_pinned_chat_order(archived, ids) {
                self.status_note = format!("pin reorder failed: {err:?}");
            }
        } else if let Some(session) = self.demo_session.as_mut() {
            session.reorder_pinned_chats(archived, &ids);
        }
        cx.notify();
    }

    /// Slice CL2: "Mark all as read" for a chat list — `readChatList`
    /// (schema 1.8.67, line 13684). The badges clear via the server
    /// updates; nothing is faked locally.
    fn mark_all_chats_as_read(&mut self, archived: bool, cx: &mut Context<Self>) {
        if let Some(live) = self.live.as_mut() {
            if let Err(err) = live.driver.mark_all_chats_as_read(archived) {
                self.status_note = format!("mark all read failed: {err:?}");
            }
        } else if let Some(session) = self.demo_session.as_mut() {
            // Demo: clear the badges directly so the fixture shows the
            // result (no server sends updates in a screenshot demo).
            for chat in session.chats.values_mut() {
                let in_list = if archived {
                    chat.in_archive
                } else {
                    chat.in_main_list
                };
                if in_list {
                    chat.unread_count = 0;
                    chat.is_marked_as_unread = false;
                }
            }
        }
        cx.notify();
    }

    /// Slice CL2: archive section collapse toggle.
    fn toggle_archive_collapsed(&mut self, cx: &mut Context<Self>) {
        if let Some(live) = self.live.as_mut() {
            let collapsed = live.driver.session.archive_collapsed;
            live.driver.session.archive_collapsed = !collapsed;
        } else if let Some(session) = self.demo_session.as_mut() {
            session.archive_collapsed = !session.archive_collapsed;
        }
        cx.notify();
    }

    /// Slice CL2: Saved Messages entry — opens the private chat with
    /// yourself (schema 1.8.67, line 9590: "Call createPrivateChat
    /// with getOption(\"my_id\") and open the chat"). An already-listed
    /// self chat opens directly; otherwise `createPrivateChat` is sent
    /// and its answer opens the chat.
    fn open_saved_messages(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let self_chat = self.session().and_then(|s| {
            let my_id = s.my_user_id?;
            s.chats
                .values()
                .find(|c| matches!(c.kind, ChatKind::Private { user_id } if user_id.0 == my_id))
                .map(|c| c.id)
        });
        if let Some(chat_id) = self_chat {
            self.select_listed_chat(chat_id, window, cx);
            return;
        }
        if self.live.is_some() {
            // Flush the open chat's composer before switching away — the
            // answer arrives asynchronously, so the driver can't do it.
            self.flush_leaving_draft(cx);
        }
        if let Some(live) = self.live.as_mut() {
            match live.driver.create_private_chat_with_self() {
                Ok(Some(_)) => {}
                Ok(None) if live.driver.session.my_user_id.is_none() => {
                    self.status_note = "account info not loaded yet".into();
                }
                Ok(None) => {}
                Err(err) => self.status_note = format!("saved messages failed: {err:?}"),
            }
        } else {
            self.status_note = "no Saved Messages chat in this demo".into();
        }
        cx.notify();
    }

    /// Slice CL2: "Clear" on the Recent searches heading —
    /// `clearRecentlyFoundChats` (schema 1.8.67, line 11671); the
    /// recents clear optimistically (TGX `SearchManager` clears
    /// locally too, lines 788-796).
    fn clear_search_recents(&mut self, cx: &mut Context<Self>) {
        if let Some(live) = self.live.as_mut() {
            if let Err(err) = live.driver.clear_recently_found_chats() {
                self.status_note = format!("clear recents failed: {err:?}");
            }
        } else if let Some(session) = self.demo_session.as_mut() {
            session.search.chat_ids.clear();
            session.search.status = SearchStatus::Idle;
        }
        cx.notify();
    }

    /// Slice CL2: open the archive auto-settings dialog (TGX
    /// `SettingsArchiveChatListController` fetches
    /// `getArchiveChatListSettings` on open).
    fn open_archive_settings(&mut self, cx: &mut Context<Self>) {
        if let Some(live) = self.live.as_mut() {
            live.driver.session.archive_settings_open = true;
            if let Err(err) = live.driver.fetch_archive_chat_list_settings() {
                self.status_note = format!("archive settings failed: {err:?}");
            }
        } else if let Some(session) = self.demo_session.as_mut() {
            session.archive_settings_open = true;
        }
        cx.notify();
    }

    /// Slice CL2: flip one archive auto-setting — optimistic local flip
    /// plus `setArchiveChatListSettings`; a refusal restores the old
    /// values (driver rollback).
    fn toggle_archive_setting(&mut self, index: usize, cx: &mut Context<Self>) {
        if let Some(live) = self.live.as_mut() {
            let Some(mut settings) = live.driver.session.archive_chat_list_settings else {
                self.status_note = "archive settings still loading…".into();
                cx.notify();
                return;
            };
            let enabled = archive_setting_get(&settings, index);
            archive_setting_set(&mut settings, index, !enabled);
            if let Err(err) = live.driver.set_archive_chat_list_settings(settings) {
                self.status_note = format!("archive setting failed: {err:?}");
            }
        } else if let Some(session) = self.demo_session.as_mut() {
            if let Some(mut settings) = session.archive_chat_list_settings {
                let enabled = archive_setting_get(&settings, index);
                archive_setting_set(&mut settings, index, !enabled);
                session.archive_chat_list_settings = Some(settings);
            }
        }
        cx.notify();
    }

    /// Slice CL2: the archive auto-settings dialog — the three
    /// schema-backed toggles (schema 1.8.67, line 3512), with TGX's
    /// labels (`SettingsArchiveChatListController`). TGX's fourth
    /// "archive as folder" appearance toggle is a client-side display
    /// preference and stays out of scope.
    fn archive_settings_overlay(&self, cx: &mut Context<Self>) -> AnyElement {
        let settings = self.session().and_then(|s| s.archive_chat_list_settings);
        let loading = self.session().is_some_and(|s| s.archive_settings_loading);
        let mut body = div().flex().flex_col().gap_3();
        if loading {
            body = body.child(
                div()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child("Loading archive settings…"),
            );
        } else if settings.is_none() {
            body = body
                .child(
                    div()
                        .text_xs()
                        .text_color(cx.theme().muted_foreground)
                        .child("Could not load archive settings."),
                )
                .child(
                    Button::new("archive-settings-retry")
                        .label("Retry")
                        .ghost()
                        .on_click(cx.listener(|this, _, _, cx| {
                            this.open_archive_settings(cx);
                        })),
                );
        } else {
            let settings = settings.expect("checked");
            for (index, (title, label, desc)) in ARCHIVE_SETTING_ROWS.iter().enumerate() {
                let enabled = archive_setting_get(&settings, index);
                body = body.child(
                    div()
                        .flex()
                        .flex_col()
                        .gap_1()
                        .child(div().text_xs().font_semibold().child(*title))
                        .child(
                            Button::new(format!("archive-setting-{index}"))
                                .label(if enabled {
                                    format!("☑ {label}")
                                } else {
                                    format!("☐ {label}")
                                })
                                .ghost()
                                .on_click(cx.listener(move |this, _, _, cx| {
                                    this.toggle_archive_setting(index, cx);
                                })),
                        )
                        .child(
                            div()
                                .text_xs()
                                .text_color(cx.theme().muted_foreground)
                                .child(*desc),
                        ),
                );
            }
        }
        div()
            .id("archive-settings-overlay")
            .absolute()
            .top_0()
            .left_0()
            .right_0()
            .bottom_0()
            .flex()
            .items_center()
            .justify_center()
            .child(
                div()
                    .id("archive-settings-backdrop")
                    .absolute()
                    .top_0()
                    .left_0()
                    .right_0()
                    .bottom_0()
                    .bg(rgba(0x000000e6))
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.set_archive_settings_open(false);
                        cx.notify();
                    })),
            )
            .child(
                div()
                    .id("archive-settings-dialog")
                    .flex()
                    .flex_col()
                    .gap_2()
                    .px_4()
                    .py_3()
                    .rounded_lg()
                    .bg(cx.theme().sidebar)
                    .border_1()
                    .border_color(cx.theme().border)
                    .min_w(px(360.))
                    .max_w(px(480.))
                    .child(
                        div()
                            .flex()
                            .items_center()
                            .justify_between()
                            .child(div().font_semibold().child("Archive settings"))
                            .child(
                                Button::new("close-archive-settings")
                                    .label("Close")
                                    .ghost()
                                    .on_click(cx.listener(|this, _, _, cx| {
                                        this.set_archive_settings_open(false);
                                        cx.notify();
                                    })),
                            ),
                    )
                    .child(body),
            )
            .into_any_element()
    }

    /// Slice CL2: show/hide the archive settings dialog on the active
    /// session.
    fn set_archive_settings_open(&mut self, open: bool) {
        if let Some(live) = self.live.as_mut() {
            live.driver.session.archive_settings_open = open;
        } else if let Some(session) = self.demo_session.as_mut() {
            session.archive_settings_open = open;
        }
    }

    fn retry_contacts(&mut self, cx: &mut Context<Self>) {
        if let Some(live) = self.live.as_mut()
            && let Err(err) = live.driver.fetch_contacts()
        {
            self.status_note = format!("contacts request failed: {err:?}");
        }
        cx.notify();
    }

    /// Contacts list for the Contacts tab: loading / error / empty /
    /// rows. A tap opens the user info panel.
    fn contacts_list(&self, cx: &mut Context<Self>) -> impl IntoElement {
        let rows: Vec<ContactRow> = self.session().map(|s| s.contact_rows()).unwrap_or_default();
        let failed = self.session().is_some_and(|s| s.contacts_error);
        let loading = self.session().is_some_and(|s| s.contacts.is_none()) && !failed;
        let mut list = div().id("contacts-list").flex().flex_col().gap_1();
        if failed {
            list = list
                .child(
                    div()
                        .text_xs()
                        .text_color(cx.theme().muted_foreground)
                        .child("Couldn’t load contacts."),
                )
                .child(
                    Button::new("contacts-retry")
                        .label("Retry")
                        .ghost()
                        .on_click(cx.listener(|this, _, _, cx| {
                            this.retry_contacts(cx);
                        })),
                );
        } else if loading {
            list = list.child(
                div()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child("Loading contacts…"),
            );
        } else if rows.is_empty() {
            list = list.child(
                div()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child("No contacts yet."),
            );
        } else {
            for row in rows {
                list = list.child(self.contact_row(&row, cx));
            }
        }
        list
    }

    fn contact_row(&self, row: &ContactRow, cx: &mut Context<Self>) -> impl IntoElement {
        let user_id = row.user_id;
        let name = row.name.clone();
        let status = row.status_text.clone();
        let selected =
            self.session().and_then(|s| s.open_info_panel) == Some(InfoPanelTarget::User(user_id));
        div()
            .id(("contact-row", user_id as u64))
            .px_2()
            .py_2()
            .rounded_md()
            .cursor_pointer()
            .bg(if selected {
                cx.theme().accent.opacity(0.15)
            } else {
                cx.theme().sidebar
            })
            .on_click(cx.listener(move |this, _, window, cx| {
                this.open_user_panel(user_id, window, cx);
            }))
            .child(
                div()
                    .flex()
                    .items_center()
                    .gap_2()
                    .child(initials_avatar(&name, 32.))
                    .child(
                        div()
                            .flex()
                            .flex_col()
                            .min_w_0()
                            .child(div().font_medium().text_sm().child(name))
                            .child(
                                div()
                                    .text_xs()
                                    .text_color(cx.theme().muted_foreground)
                                    .child(status),
                            ),
                    ),
            )
    }

    /// Phase C2i: the peer (user id + display name) of a call entry,
    /// when the call message is in a 1:1 chat. Group calls have no
    /// single peer — `None` hides "Call again".
    fn recent_call_peer(&self, chat_id: ChatId) -> Option<(i64, String)> {
        call_message_peer(self.session(), chat_id)
    }

    /// Phase C2i: `messageCall` service row — the reason-aware label
    /// (Telegram X `TD.getCallName` style) with duration and a "Call
    /// again" button for 1:1 chats.
    fn call_message_row(
        message: &HistoryMessage,
        is_video: bool,
        discard_reason: &CallDiscardReason,
        duration: i32,
        session: Option<&Session>,
        cx: &mut Context<QuillApp>,
    ) -> impl IntoElement {
        let label = call_entry_label(is_video, discard_reason, duration, message.is_outgoing);
        let peer = call_message_peer(session, message.chat_id);
        let missed = discard_reason == &CallDiscardReason::Missed;
        div()
            .id(("call-message-row", message.id.0 as u64))
            .flex()
            .items_center()
            .gap_2()
            .px_3()
            .py_1()
            .child(div().text_sm().child(if is_video { "📹" } else { "📞" }))
            .child(
                div().flex().flex_col().min_w_0().flex_1().child(
                    div()
                        .text_sm()
                        .when(missed, |this| this.text_color(rgb(0xe17076)))
                        .child(label),
                ),
            )
            .child(if let Some((user_id, _)) = peer {
                Button::new(("call-message-again", message.id.0 as u64))
                    .label("Call again")
                    .ghost()
                    .on_click(cx.listener(move |this, _, _, cx| {
                        this.call_again(user_id, is_video, cx);
                    }))
                    .into_any_element()
            } else {
                div().into_any_element()
            })
    }

    /// Phase C2i: busy-decline banner for `call_busy_declined` — the
    /// incoming calls declined while another call was active.
    fn call_busy_banner(&self, cx: &mut Context<Self>) -> Option<AnyElement> {
        let declined = self.session()?.call_busy_declined.clone();
        if declined.is_empty() {
            return None;
        }
        let names: Vec<String> = declined
            .iter()
            .map(|(user_id, is_video)| {
                let name = self
                    .session()
                    .and_then(|session| session.user(*user_id))
                    .map(|user| user.display_name())
                    .unwrap_or_else(|| format!("User {user_id}"));
                format!("{name} ({})", if *is_video { "video" } else { "voice" })
            })
            .collect();
        Some(
            div()
                .id("call-busy-banner")
                .flex()
                .items_center()
                .gap_2()
                .px_3()
                .py_2()
                .border_b_1()
                .border_color(cx.theme().border)
                .bg(cx.theme().accent.opacity(0.12))
                .child(div().text_sm().flex_1().child(format!(
                    "Missed call{} from {} — declined because another call was active.",
                    if declined.len() == 1 { "" } else { "s" },
                    names.join(", ")
                )))
                .child(
                    Button::new("call-busy-dismiss")
                        .label("Dismiss")
                        .ghost()
                        .on_click(cx.listener(|this, _, _, cx| {
                            if let Some(live) = this.live.as_mut() {
                                live.driver.session.call_busy_declined.clear();
                            } else if let Some(session) = this.demo_session.as_mut() {
                                session.call_busy_declined.clear();
                            }
                            cx.notify();
                        })),
                )
                .into_any_element(),
        )
    }

    /// Phase C2i: "Call again" from a history row — honours the
    /// confirm-before-calling preference before dialling.
    fn call_again(&mut self, user_id: i64, is_video: bool, cx: &mut Context<Self>) {
        let confirm = self
            .session()
            .is_some_and(|session| session.call_prefs.confirm_before_calling);
        if confirm {
            self.call_confirm = Some((user_id, is_video));
            cx.notify();
            return;
        }
        self.dial_user(user_id, is_video, cx);
    }

    /// Phase C2i: Recent-calls list + call settings for the Calls tab.
    fn calls_list(&self, cx: &mut Context<Self>) -> impl IntoElement {
        let mut list = div().id("calls-list").flex().flex_col().gap_1().px_1();
        list = list.child(div().text_sm().font_semibold().px_1().child("Recent calls"));
        let (entries, loading, failed, has_more) = self
            .session()
            .map(|session| {
                (
                    session.recent_calls.clone(),
                    session.recent_calls_loading,
                    session.recent_calls_error,
                    !session.recent_calls_offset.is_empty(),
                )
            })
            .unwrap_or_default();
        if failed {
            list = list
                .child(
                    div()
                        .text_xs()
                        .text_color(cx.theme().muted_foreground)
                        .child("Couldn’t load call history."),
                )
                .child(
                    Button::new("calls-retry")
                        .label("Retry")
                        .ghost()
                        .on_click(cx.listener(|this, _, _, cx| {
                            if let Some(live) = this.live.as_mut()
                                && let Err(err) = live.driver.fetch_call_history()
                            {
                                this.status_note = format!("call history request failed: {err:?}");
                            }
                            cx.notify();
                        })),
                );
        } else if loading && entries.is_empty() {
            list = list.child(
                div()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child("Loading calls…"),
            );
        } else if entries.is_empty() {
            list = list.child(
                div()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child("No recent calls."),
            );
        } else {
            for entry in &entries {
                list = list.child(self.recent_call_row(entry, cx));
            }
            if has_more {
                list = list.child(
                    Button::new("calls-load-more")
                        .label("Load more")
                        .ghost()
                        .on_click(cx.listener(|this, _, _, cx| {
                            if let Some(live) = this.live.as_mut()
                                && let Err(err) = live.driver.fetch_more_call_history()
                            {
                                this.status_note = format!("call history request failed: {err:?}");
                            }
                            cx.notify();
                        })),
                );
            }
        }
        list = list.child(self.call_settings_section(cx));
        list = list.child(self.media_settings_section(cx));
        list
    }

    /// Phase C2i: one row of the server-side recent-calls list, with a
    /// reason-aware label (Telegram X `TD.getCallName` style) and
    /// "Call again" for 1:1 calls.
    fn recent_call_row(&self, entry: &ParsedMessage, cx: &mut Context<Self>) -> impl IntoElement {
        let (label, is_video) = match &entry.content {
            MessageContent::Call {
                is_video,
                discard_reason,
                duration,
            } => (
                call_entry_label(*is_video, discard_reason, *duration, entry.is_outgoing),
                *is_video,
            ),
            MessageContent::GroupCallInvitation { .. } => ("Group call".to_owned(), false),
            _ => ("Call".to_owned(), false),
        };
        let peer = self.recent_call_peer(entry.chat_id);
        let name = peer
            .as_ref()
            .map(|(_, name)| name.clone())
            .unwrap_or_else(|| "Call".to_owned());
        let missed = !entry.is_outgoing
            && matches!(
                entry.content,
                MessageContent::Call {
                    discard_reason: CallDiscardReason::Missed,
                    ..
                }
            );
        div()
            .id(("call-row", entry.id.0 as u64))
            .px_2()
            .py_2()
            .rounded_md()
            .flex()
            .items_center()
            .gap_2()
            .child(
                div()
                    .flex()
                    .flex_col()
                    .min_w_0()
                    .flex_1()
                    .child(div().font_medium().text_sm().child(name))
                    .child(
                        div()
                            .text_xs()
                            .text_color(cx.theme().muted_foreground)
                            .child(label),
                    ),
            )
            .child(if missed {
                div()
                    .text_xs()
                    .font_medium()
                    .text_color(rgb(0xe17076))
                    .child("missed")
                    .into_any_element()
            } else {
                div().into_any_element()
            })
            .child(if let Some((user_id, _)) = peer {
                Button::new(("call-again", entry.id.0 as u64))
                    .label("Call again")
                    .ghost()
                    .on_click(cx.listener(move |this, _, _, cx| {
                        this.call_again(user_id, is_video, cx);
                    }))
                    .into_any_element()
            } else {
                div().into_any_element()
            })
    }

    /// Phase C2i: call settings — confirm-before-calling (real +
    /// persisted), who-can-call-me and P2P (real TDLib privacy), and
    /// the honest "saved, not yet applied" less-data toggle.
    fn call_settings_section(&self, cx: &mut Context<Self>) -> impl IntoElement {
        let prefs = self
            .session()
            .map(|session| session.call_prefs.clone())
            .unwrap_or_default();
        let allow_calls = self
            .session()
            .and_then(|session| session.call_privacy_allow_calls);
        let p2p = self.session().and_then(|session| session.call_privacy_p2p);
        let privacy_loading = self
            .session()
            .is_some_and(|session| session.call_privacy_loading);
        let privacy_failed = self
            .session()
            .is_some_and(|session| session.call_privacy_error);
        let radio_row = |id: &'static str,
                         label: &'static str,
                         current: Option<PrivacyWho>,
                         set: CallPrivacySetting,
                         who: PrivacyWho| {
            let selected = current == Some(who);
            div()
                .id(id)
                .cursor_pointer()
                .flex()
                .items_center()
                .gap_2()
                .px_2()
                .py_1()
                .rounded_md()
                .bg(if selected {
                    cx.theme().accent.opacity(0.15)
                } else {
                    cx.theme().background
                })
                .child(div().text_xs().child(if selected { "●" } else { "○" }))
                .child(div().text_sm().child(label))
                .on_click(cx.listener(move |this, _, _, cx| {
                    if let Some(live) = this.live.as_mut()
                        && let Err(err) = live.driver.set_call_privacy(set, who)
                    {
                        this.status_note = format!("privacy update failed: {err:?}");
                    } else if let Some(demo) = this.demo_session.as_mut() {
                        // Demo: show the chosen value immediately (no
                        // live TDLib to confirm it).
                        match set {
                            CallPrivacySetting::AllowCalls => {
                                demo.call_privacy_allow_calls = Some(who)
                            }
                            CallPrivacySetting::PeerToPeer => demo.call_privacy_p2p = Some(who),
                        }
                    }
                    cx.notify();
                }))
        };
        div()
            .flex()
            .flex_col()
            .gap_1()
            .mt_2()
            .child(
                div()
                    .text_sm()
                    .font_semibold()
                    .px_1()
                    .child("Call settings"),
            )
            .child(
                div()
                    .id("call-pref-confirm")
                    .cursor_pointer()
                    .flex()
                    .items_center()
                    .gap_2()
                    .px_2()
                    .py_1()
                    .rounded_md()
                    .child(div().text_xs().child(if prefs.confirm_before_calling {
                        "●"
                    } else {
                        "○"
                    }))
                    .child(
                        div().text_sm().child("Confirm before calling").child(
                            div()
                                .text_xs()
                                .text_color(cx.theme().muted_foreground)
                                .child("Ask before placing a call"),
                        ),
                    )
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.toggle_call_pref_confirm(cx);
                    })),
            )
            .child(
                div()
                    .id("call-pref-less-data")
                    .cursor_pointer()
                    .flex()
                    .items_center()
                    .gap_2()
                    .px_2()
                    .py_1()
                    .rounded_md()
                    .child(div().text_xs().child(if prefs.less_data_for_calls {
                        "●"
                    } else {
                        "○"
                    }))
                    .child(
                        div().text_sm().child("Use less data for calls").child(
                            div()
                                .text_xs()
                                .text_color(cx.theme().muted_foreground)
                                .child("Saved here — the call engine doesn’t support it yet"),
                        ),
                    )
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.toggle_call_pref_less_data(cx);
                    })),
            )
            .child(
                div()
                    .text_xs()
                    .font_medium()
                    .px_2()
                    .pt_1()
                    .child("Who can call me"),
            )
            .child(if privacy_failed {
                div()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .px_2()
                    .child("Couldn’t load privacy settings.")
                    .into_any_element()
            } else if privacy_loading && allow_calls.is_none() {
                div()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .px_2()
                    .child("Loading privacy settings…")
                    .into_any_element()
            } else {
                div()
                    .flex()
                    .flex_col()
                    .gap_0()
                    .child(radio_row(
                        "call-privacy-allow-everybody",
                        "Everybody",
                        allow_calls,
                        CallPrivacySetting::AllowCalls,
                        PrivacyWho::Everybody,
                    ))
                    .child(radio_row(
                        "call-privacy-allow-contacts",
                        "My Contacts",
                        allow_calls,
                        CallPrivacySetting::AllowCalls,
                        PrivacyWho::Contacts,
                    ))
                    .child(radio_row(
                        "call-privacy-allow-nobody",
                        "Nobody",
                        allow_calls,
                        CallPrivacySetting::AllowCalls,
                        PrivacyWho::Nobody,
                    ))
                    .into_any_element()
            })
            .child(
                div()
                    .text_xs()
                    .font_medium()
                    .px_2()
                    .pt_1()
                    .child("Peer-to-peer calls"),
            )
            .child(if privacy_failed {
                div()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .px_2()
                    .child("Couldn’t load privacy settings.")
                    .into_any_element()
            } else if privacy_loading && p2p.is_none() {
                div()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .px_2()
                    .child("Loading privacy settings…")
                    .into_any_element()
            } else {
                div()
                    .flex()
                    .flex_col()
                    .gap_0()
                    .child(radio_row(
                        "call-privacy-p2p-everybody",
                        "Everybody",
                        p2p,
                        CallPrivacySetting::PeerToPeer,
                        PrivacyWho::Everybody,
                    ))
                    .child(radio_row(
                        "call-privacy-p2p-contacts",
                        "My Contacts",
                        p2p,
                        CallPrivacySetting::PeerToPeer,
                        PrivacyWho::Contacts,
                    ))
                    .child(radio_row(
                        "call-privacy-p2p-nobody",
                        "Nobody",
                        p2p,
                        CallPrivacySetting::PeerToPeer,
                        PrivacyWho::Nobody,
                    ))
                    .into_any_element()
            })
    }

    /// MED2: media settings section — the HQ round-video toggle (TGX
    /// "Record HQ Round Videos" / `UseHqRoundVideos`). Persisted in
    /// `MediaPrefs`; 480px captures when on, 280px otherwise.
    fn media_settings_section(&self, cx: &mut Context<Self>) -> impl IntoElement {
        let hq = self
            .session()
            .is_some_and(|session| session.media_prefs.hq_round_videos);
        // MED4: Instant View mode (TGX: None / Telegram-internal / All).
        let iv_mode = self
            .session()
            .map(|session| session.media_prefs.instant_view_mode)
            .unwrap_or(quill::settings::InstantViewMode::Telegram);
        let iv_label = match iv_mode {
            quill::settings::InstantViewMode::Off => "Off",
            quill::settings::InstantViewMode::Telegram => "Telegram links",
            quill::settings::InstantViewMode::All => "All links",
        };
        div()
            .flex()
            .flex_col()
            .gap_1()
            .mt_2()
            .child(
                div()
                    .text_sm()
                    .font_semibold()
                    .px_1()
                    .child("Media settings"),
            )
            .child(
                div()
                    .id("media-pref-hq-round")
                    .cursor_pointer()
                    .flex()
                    .items_center()
                    .gap_2()
                    .px_2()
                    .py_1()
                    .rounded_md()
                    .child(div().text_xs().child(if hq { "●" } else { "○" }))
                    .child(
                        div().text_sm().child("Record HQ round videos").child(
                            div()
                                .text_xs()
                                .text_color(cx.theme().muted_foreground)
                                .child("Capture round video notes at 480px instead of 280px"),
                        ),
                    )
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.toggle_hq_round_videos(cx);
                    })),
            )
            .child(
                div()
                    .id("media-pref-instant-view")
                    .cursor_pointer()
                    .flex()
                    .items_center()
                    .gap_2()
                    .px_2()
                    .py_1()
                    .rounded_md()
                    .child(div().text_sm().font_medium().child("Instant View"))
                    .child(
                        div()
                            .text_xs()
                            .text_color(cx.theme().muted_foreground)
                            .child(format!("{iv_label} — tap to cycle")),
                    )
                    .on_click(cx.listener(|this, _, _, cx| {
                        // MED4: cycle Off → Telegram links → All links.
                        this.set_media_pref(
                            |prefs| {
                                prefs.instant_view_mode = match prefs.instant_view_mode {
                                    quill::settings::InstantViewMode::Off => {
                                        quill::settings::InstantViewMode::Telegram
                                    }
                                    quill::settings::InstantViewMode::Telegram => {
                                        quill::settings::InstantViewMode::All
                                    }
                                    quill::settings::InstantViewMode::All => {
                                        quill::settings::InstantViewMode::Off
                                    }
                                };
                            },
                            cx,
                        );
                    })),
            )
            // MED3: auto-download settings below the media prefs.
            .child(self.auto_download_settings_section(cx))
    }

    /// MED3: auto-download settings — data-saver master toggle plus the
    /// per-chat-kind × media-type grid. The bit model mirrors TGX
    /// `settings_autodownload` (private/group/channel shifts); desktop has
    /// no mobile/wifi/roaming distinction, so TGX's per-connection grids
    /// collapse into this one (Telegram Desktop's own dialog is the same
    /// grid). Persisted client-side in `media_prefs.json`.
    fn auto_download_settings_section(&self, cx: &mut Context<Self>) -> impl IntoElement {
        let prefs = self
            .session()
            .map(|s| s.media_prefs.clone())
            .unwrap_or_default();
        let section = div()
            .flex()
            .flex_col()
            .gap_1()
            .mt_2()
            .child(
                div()
                    .text_sm()
                    .font_semibold()
                    .px_1()
                    .child("Auto-download"),
            )
            .child(
                div()
                    .id("media-pref-data-saver")
                    .cursor_pointer()
                    .flex()
                    .items_center()
                    .gap_2()
                    .px_2()
                    .py_1()
                    .rounded_md()
                    .child(
                        div()
                            .text_xs()
                            .child(if prefs.data_saver { "●" } else { "○" }),
                    )
                    .child(
                        div().text_sm().child("Data saver").child(
                            div()
                                .text_xs()
                                .text_color(cx.theme().muted_foreground)
                                .child("Pause all automatic media downloads"),
                        ),
                    )
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.set_media_pref(|prefs| prefs.data_saver = !prefs.data_saver, cx);
                    })),
            );
        const ROWS: [(&str, u8); 7] = [
            ("Photos", AUTO_DOWNLOAD_PHOTO),
            ("Voice messages", AUTO_DOWNLOAD_VOICE),
            ("Video messages", AUTO_DOWNLOAD_VIDEO_NOTE),
            ("Videos", AUTO_DOWNLOAD_VIDEO),
            ("Files", AUTO_DOWNLOAD_FILE),
            ("Music", AUTO_DOWNLOAD_MUSIC),
            ("GIFs", AUTO_DOWNLOAD_GIF),
        ];
        let kinds = [
            ("Private", prefs.auto_download_private),
            ("Groups", prefs.auto_download_groups),
            ("Channels", prefs.auto_download_channels),
        ];
        let mut grid = div().flex().flex_col().gap_1().px_2().mt_1();
        let mut header = div().flex().items_center().gap_2();
        header = header.child(div().w(px(110.)).child(""));
        for (kind, _) in &kinds {
            header = header.child(
                div()
                    .flex_1()
                    .text_xs()
                    .text_center()
                    .text_color(cx.theme().muted_foreground)
                    .child(*kind),
            );
        }
        grid = grid.child(header);
        for (row_idx, (label, flag)) in ROWS.iter().enumerate() {
            let mut row = div().flex().items_center().gap_2();
            row = row.child(div().w(px(110.)).text_sm().child(*label));
            for (kind_idx, (_, bits)) in kinds.iter().enumerate() {
                let on = bits & flag != 0;
                let flag = *flag;
                row = row.child(
                    div()
                        .id(format!("auto-dl-{row_idx}-{kind_idx}"))
                        .flex_1()
                        .text_center()
                        .cursor_pointer()
                        .text_sm()
                        .child(if on { "●" } else { "○" })
                        .on_click(cx.listener(move |this, _, _, cx| {
                            this.set_media_pref(
                                move |prefs| {
                                    let bits = match kind_idx {
                                        0 => &mut prefs.auto_download_private,
                                        1 => &mut prefs.auto_download_groups,
                                        _ => &mut prefs.auto_download_channels,
                                    };
                                    *bits ^= flag;
                                },
                                cx,
                            );
                        })),
                );
            }
            grid = grid.child(row);
        }
        section.child(grid)
    }

    fn open_user_panel(&mut self, user_id: i64, window: &mut Window, cx: &mut Context<Self>) {
        self.open_info_panel_target(InfoPanelTarget::User(user_id), window, cx);
    }

    /// Phase S1: "New secret chat" contact picker — eligible contacts
    /// (non-bot, not self, via `can_start_secret_chat_with`) rendered in
    /// the contacts-list style; picking one calls
    /// `start_secret_chat_for_user` and closes the picker.
    fn new_secret_picker_panel(&self, cx: &mut Context<Self>) -> impl IntoElement {
        let rows: Vec<ContactRow> = self
            .session()
            .map(|s| {
                s.contact_rows()
                    .into_iter()
                    .filter(|row| Self::can_start_secret_chat_with(s, row.user_id))
                    .collect()
            })
            .unwrap_or_default();
        let mut panel = div()
            .id("new-secret-picker")
            .flex()
            .flex_col()
            .gap_1()
            .p_2()
            .rounded_md()
            .border_1()
            .border_color(cx.theme().border)
            .child(
                div()
                    .text_xs()
                    .font_semibold()
                    .text_color(cx.theme().muted_foreground)
                    .child("Start a secret chat with:"),
            );
        if rows.is_empty() {
            panel = panel.child(
                div()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child("No eligible contacts."),
            );
        }
        for row in rows {
            let user_id = row.user_id;
            let name = row.name.clone();
            let status = row.status_text.clone();
            panel = panel.child(
                div()
                    .id(("new-secret-contact", user_id as u64))
                    .px_2()
                    .py_2()
                    .rounded_md()
                    .cursor_pointer()
                    .bg(cx.theme().sidebar)
                    .on_click(cx.listener(move |this, _, _, cx| {
                        this.new_secret_picker_open = false;
                        this.start_secret_chat_for_user(user_id, cx);
                    }))
                    .child(
                        div()
                            .flex()
                            .items_center()
                            .gap_2()
                            .child(initials_avatar(&name, 32.))
                            .child(
                                div()
                                    .flex()
                                    .flex_col()
                                    .min_w_0()
                                    .child(div().font_medium().text_sm().child(name))
                                    .child(
                                        div()
                                            .text_xs()
                                            .text_color(cx.theme().muted_foreground)
                                            .child(status),
                                    ),
                            ),
                    ),
            );
        }
        panel
    }

    fn open_supergroup_panel(
        &mut self,
        supergroup_id: i64,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.open_info_panel_target(InfoPanelTarget::Supergroup(supergroup_id), window, cx);
    }

    /// Open an info panel: set the target, then fetch its data on the live
    /// path (full info + profile photo for users, full info for
    /// supergroups). The demo path only sets the target — the fixture
    /// pre-seeds the data.
    fn open_info_panel_target(
        &mut self,
        target: InfoPanelTarget,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        // Phase D3a: resolve the chat for a supergroup info-panel target
        // before the live driver is borrowed mutably below.
        let invite_panel_chat_id = match target {
            InfoPanelTarget::Supergroup(supergroup_id) => self.session().and_then(|session| {
                session.chats.values().find_map(|chat| match chat.kind {
                    ChatKind::Supergroup {
                        supergroup_id: id, ..
                    } if id == supergroup_id => Some(chat.id),
                    _ => None,
                })
            }),
            _ => None,
        };
        // Slice G1: resolve the basic-group chat before the driver
        // borrow below.
        let g1_basic_chat = match target {
            InfoPanelTarget::BasicGroup(basic_group_id) => self.session().and_then(|session| {
                session.chats.values().find_map(|chat| match chat.kind {
                    ChatKind::BasicGroup { basic_group_id: id } if id == basic_group_id => {
                        Some(chat.id)
                    }
                    _ => None,
                })
            }),
            _ => None,
        };
        if let Some(live) = self.live.as_mut() {
            live.driver.set_info_panel(Some(target));
            let fetch = match target {
                InfoPanelTarget::User(user_id) => {
                    live.driver.fetch_user_full_info(user_id).map(|_| ())
                }
                InfoPanelTarget::Supergroup(supergroup_id) => {
                    let mut result = live
                        .driver
                        .fetch_supergroup_full_info(supergroup_id)
                        .map(|_| ());
                    if let Some(chat_id) = invite_panel_chat_id {
                        // Phase D3a: invite-link / join-request lists for
                        // admins; the driver no-ops when the
                        // `can_invite_users` gate is closed.
                        // Phase D3b: administrator list; the driver
                        // no-ops unless the viewer may manage admins
                        // (owner or `can_promote_members`).
                        // Phase D3c: recent-actions log; the driver no-ops
                        // unless the viewer is an administrator/creator.
                        for fetch in [
                            live.driver.fetch_chat_invite_links(chat_id).map(|_| ()),
                            live.driver.fetch_chat_join_requests(chat_id).map(|_| ()),
                            live.driver.fetch_chat_administrators(chat_id).map(|_| ()),
                            live.driver.fetch_chat_event_log(chat_id).map(|_| ()),
                        ] {
                            if fetch.is_err() {
                                result = fetch;
                            }
                        }
                        // Slice G2: channel boost status (channels only;
                        // cached and deduped by the driver).
                        let is_channel =
                            live.driver
                                .session
                                .chats
                                .get(&chat_id.0)
                                .is_some_and(|chat| {
                                    matches!(
                                        chat.kind,
                                        ChatKind::Supergroup {
                                            is_channel: true,
                                            ..
                                        }
                                    )
                                });
                        if is_channel && let Err(err) = live.driver.fetch_chat_boost_status(chat_id)
                        {
                            result = Err(err);
                        }
                        // Slice G2: welcome-message pack for admins who may
                        // send them (the driver dedupes on a cached pack).
                        if live.driver.session.chat_can_send_welcome_messages(chat_id)
                            && let Err(err) = live.driver.load_chat_welcome_messages(chat_id)
                        {
                            result = Err(err);
                        }
                    }
                    result
                }
                // Phase D2: `is_dark` only tints server-rendered graph
                // images; Quill draws its own sparklines from `json_data`
                // and the app has no dark-mode concept, so `false`.
                InfoPanelTarget::Statistics(chat_id) => live
                    .driver
                    .fetch_chat_statistics(ChatId(chat_id), false)
                    .map(|_| ()),
                // Slice G1: basic-group member list; the chat lookup
                // happened before the driver borrow.
                InfoPanelTarget::BasicGroup(_) => match g1_basic_chat {
                    Some(chat_id) => live.driver.fetch_basic_group_members(chat_id).map(|_| ()),
                    None => Ok(()),
                },
            };
            if let Err(err) = fetch {
                self.status_note = format!("info request failed: {err:?}");
            } else if let InfoPanelTarget::User(user_id) = target
                && let Err(err) = live.driver.download_user_photo(user_id)
            {
                self.status_note = format!("photo download failed: {err:?}");
            }
        } else if let Some(session) = self.demo_session.as_mut() {
            session.open_info_panel = Some(target);
        }
        // Slice G2: the event-log section's search box (created lazily;
        // its value syncs to the panel chat's stored query). The per-admin
        // filter resets whenever the panel target changes.
        self.event_log_admin_filter = None;
        if self.event_log_search.is_none() {
            self.event_log_search = Some(cx.new(|cx| {
                TextareaState::new(window, cx)
                    .placeholder("Search recent actions")
                    .auto_grow(1, 1)
                    .submit_on_enter(false)
            }));
        }
        if let Some(chat_id) = invite_panel_chat_id {
            let query = self
                .session()
                .and_then(|session| session.event_log_queries.get(&chat_id.0).cloned())
                .unwrap_or_default();
            if let Some(input) = self.event_log_search.clone() {
                input.update(cx, |state, cx| state.set_value(&query, window, cx));
            }
        }
        cx.notify();
    }

    fn close_info_panel(&mut self, cx: &mut Context<Self>) {
        if let Some(live) = self.live.as_mut() {
            live.driver.set_info_panel(None);
        } else if let Some(session) = self.demo_session.as_mut() {
            session.open_info_panel = None;
        }
        cx.notify();
    }

    /// Right-side info panel for the open `InfoPanelTarget` (user profile
    /// or group info). Rendered next to the conversation in the shell.
    fn info_panel(&self, cx: &mut Context<Self>) -> Option<AnyElement> {
        let target = self.session()?.open_info_panel?;
        let (title, content) = match target {
            InfoPanelTarget::User(user_id) => ("Contact info", self.user_info_panel(user_id, cx)),
            InfoPanelTarget::Supergroup(supergroup_id) => {
                ("Group info", self.supergroup_info_panel(supergroup_id, cx))
            }
            // Slice G1: basic-group info panel (members, permissions,
            // invite link, leave/delete).
            InfoPanelTarget::BasicGroup(basic_group_id) => (
                "Group info",
                self.basic_group_info_panel(basic_group_id, cx),
            ),
            // Phase D2: channel/group statistics view.
            InfoPanelTarget::Statistics(chat_id) => {
                ("Statistics", self.chat_statistics_panel(chat_id, cx))
            }
        };
        Some(
            div()
                .id("info-panel")
                .w(px(300.))
                .h_full()
                .flex_shrink_0()
                .border_l_1()
                .border_color(cx.theme().border)
                .bg(cx.theme().sidebar)
                .flex()
                .flex_col()
                .child(
                    div()
                        .flex()
                        .items_center()
                        .justify_between()
                        .px_3()
                        .py_2()
                        .border_b_1()
                        .border_color(cx.theme().border)
                        .child(div().font_semibold().child(title))
                        .child(
                            div()
                                .id("info-panel-close")
                                .cursor_pointer()
                                .px_2()
                                .py_1()
                                .rounded_md()
                                .text_color(cx.theme().muted_foreground)
                                .child("✕")
                                .on_click(cx.listener(|this, _, _, cx| {
                                    this.close_info_panel(cx);
                                })),
                        ),
                )
                // Phase B2: the content scrolls — the encryption-key
                // section can push a contact panel past the window
                // height.
                .child(
                    div()
                        .id("info-panel-body")
                        .flex_1()
                        .overflow_y_scroll()
                        .child(content),
                )
                .into_any_element(),
        )
    }

    /// MED3: downloads manager panel (TGX side-menu Downloads, empty state
    /// `NoDownloadFilesFound`). Lists user-initiated active downloads with
    /// live progress + cancel, and recently completed downloads with
    /// open / reveal actions. Sits beside the conversation like the info
    /// panel; toggled from the sidebar "Downloads" entry.
    fn downloads_panel(&self, cx: &mut Context<Self>) -> Option<AnyElement> {
        let session = self.session()?;
        if !session.downloads_panel_open {
            return None;
        }
        let mut active: Vec<i32> = session.user_downloads.iter().copied().collect();
        active.sort_unstable();
        let recent: Vec<i32> = session.completed_downloads.iter().copied().collect();
        let mut failed: Vec<i32> = session.failed_downloads.iter().copied().collect();
        failed.sort_unstable();
        let mut panel = div()
            .id("downloads-panel")
            .w(px(300.))
            .h_full()
            .flex_shrink_0()
            .border_l_1()
            .border_color(cx.theme().border)
            .bg(cx.theme().sidebar)
            .flex()
            .flex_col()
            .child(
                div()
                    .flex()
                    .items_center()
                    .justify_between()
                    .px_3()
                    .py_2()
                    .border_b_1()
                    .border_color(cx.theme().border)
                    .child(div().font_semibold().child("Downloads"))
                    .child(
                        div()
                            .id("downloads-panel-close")
                            .cursor_pointer()
                            .px_2()
                            .py_1()
                            .rounded_md()
                            .text_color(cx.theme().muted_foreground)
                            .child("✕")
                            .on_click(cx.listener(|this, _, _, cx| {
                                if let Some(live) = this.live.as_mut() {
                                    live.driver.session.downloads_panel_open = false;
                                } else if let Some(session) = this.demo_session.as_mut() {
                                    session.downloads_panel_open = false;
                                }
                                cx.notify();
                            })),
                    ),
            );
        if active.is_empty() && recent.is_empty() {
            panel = panel.child(
                div()
                    .px_3()
                    .py_4()
                    .text_sm()
                    .text_color(cx.theme().muted_foreground)
                    .child("No downloads yet."),
            );
        } else {
            if !active.is_empty() {
                panel = panel.child(
                    div()
                        .px_3()
                        .pt_2()
                        .text_xs()
                        .font_semibold()
                        .text_color(cx.theme().muted_foreground)
                        .child("Active"),
                );
                for file_id in active {
                    panel = panel.child(self.download_row(file_id, true, false, cx));
                }
            }
            if !failed.is_empty() {
                panel = panel.child(
                    div()
                        .px_3()
                        .pt_2()
                        .text_xs()
                        .font_semibold()
                        .text_color(cx.theme().muted_foreground)
                        .child("Failed"),
                );
                for file_id in failed {
                    panel = panel.child(self.download_row(file_id, false, true, cx));
                }
            }
            if !recent.is_empty() {
                panel = panel.child(
                    div()
                        .px_3()
                        .pt_2()
                        .text_xs()
                        .font_semibold()
                        .text_color(cx.theme().muted_foreground)
                        .child("Recent"),
                );
                for file_id in recent.into_iter().rev() {
                    panel = panel.child(self.download_row(file_id, false, false, cx));
                }
            }
        }
        Some(panel.into_any_element())
    }

    /// MED3: one downloads-manager row. Active rows show the live progress
    /// bar + percent + a cancel button; failed rows show a retry button;
    /// recent rows show size + open / reveal actions.
    fn download_row(
        &self,
        file_id: i32,
        active: bool,
        failed: bool,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let session = self.session();
        let file = session.as_ref().and_then(|s| s.files.get(&file_id));
        let name = session
            .as_ref()
            .map(|s| download_display_name(s, file_id))
            .unwrap_or_else(|| format!("File {file_id}"));
        let size_label = file
            .map(|f| f.display_size())
            .map(format_bytes)
            .unwrap_or_default();
        let progress = file.and_then(|f| f.download_progress());
        let status = if active {
            match progress {
                Some(p) => format!("{}%", (p * 100.0).round() as i32),
                None => "downloading…".to_string(),
            }
        } else if failed {
            "download failed".to_string()
        } else {
            size_label.clone()
        };
        let mut row = div()
            .id(("download-row", file_id as u64))
            .px_3()
            .py_2()
            .flex()
            .flex_col()
            .gap_1()
            .child(div().text_sm().font_medium().child(name))
            .child(
                div()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child(status),
            );
        if active {
            row = row.child(
                div()
                    .w_full()
                    .h(px(4.))
                    .rounded_full()
                    .bg(rgb(0x30363d))
                    .child(
                        div()
                            .h_full()
                            .w(relative(progress.unwrap_or(0.0)))
                            .rounded_full()
                            .bg(rgb(0x58a6ff)),
                    ),
            );
        }
        let actions = if active {
            div().flex().gap_2().child(
                div()
                    .id(("download-cancel", file_id as u64))
                    .cursor_pointer()
                    .text_xs()
                    .text_color(rgb(0x58a6ff))
                    .child("Cancel")
                    .on_click(cx.listener(move |this, _, _, cx| {
                        this.cancel_media_download(FileId(file_id), cx);
                    })),
            )
        } else if failed {
            div().flex().gap_2().child(
                div()
                    .id(("download-retry", file_id as u64))
                    .cursor_pointer()
                    .text_xs()
                    .text_color(rgb(0x58a6ff))
                    .child("Retry")
                    .on_click(cx.listener(move |this, _, _, cx| {
                        this.request_media_download(FileId(file_id), None, cx);
                    })),
            )
        } else {
            div()
                .flex()
                .gap_2()
                .child(
                    div()
                        .id(("download-open", file_id as u64))
                        .cursor_pointer()
                        .text_xs()
                        .text_color(rgb(0x58a6ff))
                        .child("Open")
                        .on_click(cx.listener(move |this, _, _, cx| {
                            this.open_downloaded_file(FileId(file_id), cx);
                        })),
                )
                .child(
                    div()
                        .id(("download-reveal", file_id as u64))
                        .cursor_pointer()
                        .text_xs()
                        .text_color(rgb(0x58a6ff))
                        .child("Show in folder")
                        .on_click(cx.listener(move |this, _, _, cx| {
                            this.reveal_downloaded_file(FileId(file_id), cx);
                        })),
                )
        };
        row.child(actions).into_any_element()
    }

    /// Phase B2: the "Encryption key" section of a secret chat partner's
    /// info panel — the 12×12 fingerprint grid from `secretChat.key_hash`
    /// (schema 1.8.67 lines 2812–2813: 36 little-endian bytes → 144
    /// two-bit pixels in FFFFFF / D5E6F3 / 2D5775 / 2F99C9) with
    /// Telegram-style verification copy. A Ready record whose hash isn't
    /// 36 bytes yet (still resolving) shows a loading note instead of
    /// the grid — graceful missing-key handling.
    ///
    /// Security: `record.key_hash` bytes are passed straight into
    /// `key_fingerprint::key_hash_pixels`; only pixel indices / colors
    /// enter the element tree — raw key bytes never leave `Session`.
    fn encryption_key_section(
        &self,
        record: &ParsedSecretChat,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        const CELL_PX: f32 = 18.0;
        let pixels = key_fingerprint::key_hash_pixels(&record.key_hash);
        let mut body = div()
            .flex()
            .flex_col()
            .w_full()
            .gap_2()
            .pt_2()
            .border_t_1()
            .border_color(cx.theme().border)
            .child(
                div()
                    .text_xs()
                    .font_semibold()
                    .text_color(cx.theme().muted_foreground)
                    .child("Encryption key"),
            );
        match pixels {
            Some(pixels) => {
                let mut grid = div().flex().flex_col();
                for row in pixels.chunks(key_fingerprint::KEY_GRID_SIZE) {
                    let mut line = div().flex().flex_row();
                    for pixel in row {
                        line = line.child(
                            div()
                                .w(px(CELL_PX))
                                .h(px(CELL_PX))
                                .bg(rgb(key_fingerprint::key_pixel_color(*pixel))),
                        );
                    }
                    grid = grid.child(line);
                }
                body = body
                    .child(
                        div()
                            .flex()
                            .flex_col()
                            .items_center()
                            .child(grid.border_1().border_color(cx.theme().border)),
                    )
                    .child({
                        // Phase S1: TGX `EncryptionKeyDescription`, verbatim,
                        // with the peer's display name.
                        let name =
                            Self::secret_peer_name(self.session(), record.user_id, "your contact");
                        div()
                            .text_xs()
                            .text_color(cx.theme().muted_foreground)
                            .child(format!(
                                "This image and text were derived from the encryption key for this \
                                 secret chat with {name}.\n\nIf they look the same on {name}'s \
                                 device, end-to-end encryption is guaranteed."
                            ))
                    });
            }
            None => {
                body = body.child(
                    div()
                        .text_xs()
                        .text_color(cx.theme().muted_foreground)
                        .child("Encryption key · still loading…"),
                );
            }
        }
        body.into_any_element()
    }

    /// User profile panel: photo (downloaded `userFullInfo.photo` size, or
    /// an initials avatar), name, status, username/phone rows, bio, and an
    /// Add contact affordance for known non-contacts.
    fn user_info_panel(&self, user_id: i64, cx: &mut Context<Self>) -> AnyElement {
        let session = self.session();
        let user = session.and_then(|s| s.user(user_id)).cloned();
        let info = session.and_then(|s| s.user_full_info(user_id)).cloned();
        let name = user
            .as_ref()
            .map(|u| u.display_name())
            .unwrap_or_else(|| format!("User {user_id}"));
        let status = user
            .as_ref()
            .map(|u| u.status.display())
            .unwrap_or_default();
        let username = user
            .as_ref()
            .map(|u| u.username.clone())
            .unwrap_or_default();
        let phone = user
            .as_ref()
            .map(|u| u.phone_number.clone())
            .unwrap_or_default();
        let bio = info.as_ref().map(|i| i.bio.clone()).unwrap_or_default();
        let show_add = user.as_ref().is_some_and(|u| !u.is_contact && !u.is_bot);
        let roots = self.media_display_roots();
        let photo_path: Option<PathBuf> = session
            .and_then(|s| {
                info.as_ref()
                    .and_then(|i| i.photo_file_id)
                    .and_then(|id| s.files.get(&id))
                    .and_then(|file| file.usable_path())
            })
            .and_then(|path| sandboxed_display_path(path, &roots));
        let avatar: AnyElement = match photo_path {
            Some(path) => img(path)
                .id(("info-panel-photo", user_id as u64))
                .w(px(96.))
                .h(px(96.))
                .rounded_full()
                .object_fit(ObjectFit::Cover)
                .into_any_element(),
            None => initials_avatar(&name, 96.).into_any_element(),
        };
        let mut detail_rows: Vec<(&str, String)> = Vec::new();
        if !username.is_empty() {
            detail_rows.push(("Username", format!("@{username}")));
        }
        if !phone.is_empty() {
            detail_rows.push(("Phone", phone));
        }
        let mut body = div()
            .flex()
            .flex_col()
            .items_center()
            .gap_3()
            .p_4()
            .child(avatar)
            .child(
                div()
                    .flex()
                    .flex_col()
                    .items_center()
                    .gap_1()
                    .child(div().text_lg().font_semibold().child(name.clone()))
                    .child(
                        div()
                            .text_sm()
                            .text_color(cx.theme().muted_foreground)
                            .child(status),
                    ),
            );
        for (label, value) in detail_rows {
            body = body.child(
                div()
                    .flex()
                    .w_full()
                    .justify_between()
                    .gap_2()
                    .child(
                        div()
                            .text_xs()
                            .text_color(cx.theme().muted_foreground)
                            .child(label),
                    )
                    .child(div().text_sm().child(value)),
            );
        }
        if !bio.is_empty() {
            body = body.child(
                div()
                    .flex()
                    .flex_col()
                    .w_full()
                    .gap_1()
                    .child(
                        div()
                            .text_xs()
                            .font_semibold()
                            .text_color(cx.theme().muted_foreground)
                            .child("Bio"),
                    )
                    .child(div().text_sm().child(bio)),
            );
        }
        if show_add {
            body = body.child(
                Button::new("info-panel-add-contact")
                    .label("Add contact")
                    .on_click(cx.listener(move |this, _, window, cx| {
                        this.open_add_contact_dialog(user_id, window, cx);
                    })),
            );
        }
        // Phase B1: "Start secret chat" from a user profile — E2E chat
        // with a non-bot user (`createNewSecretChat`, schema 1.8.67 line
        // 13340). Not offered for bots or for yourself.
        let show_start_secret = session
            .as_ref()
            .is_some_and(|s| Self::can_start_secret_chat_with(s, user_id));
        if show_start_secret {
            body = body.child(
                Button::new("info-panel-start-secret")
                    .label("Start secret chat")
                    .on_click(cx.listener(move |this, _, _, cx| {
                        this.start_secret_chat_for_user(user_id, cx);
                    })),
            );
        }
        // Phase C1: "Call" from a user profile — `createCall`
        // (audio-only). Phase C1b: "🎥 Video call" — `createCall` with
        // `is_video: true` (signaling only; media transport is C2). Same
        // gating as secret chats: non-bot users, not yourself.
        let show_call = show_start_secret;
        if show_call {
            body = body.child(
                div()
                    .flex()
                    .gap_2()
                    .child(
                        Button::new("info-panel-call")
                            .label("Call")
                            .on_click(cx.listener(move |this, _, _, cx| {
                                this.start_call_for_user(user_id, false, cx);
                            })),
                    )
                    .child(
                        Button::new("info-panel-video-call")
                            .label("🎥 Video call")
                            .on_click(cx.listener(move |this, _, _, cx| {
                                this.start_call_for_user(user_id, true, cx);
                            })),
                    ),
            );
        }
        // Phase B2: encryption-key section — only when the open chat is a
        // Ready secret chat with this user (the key is meaningful once
        // the session is established). Missing/short hashes render the
        // still-loading note inside the section.
        if let Some(record) = session
            .as_ref()
            .and_then(|s| s.open_ready_secret_chat_for_user(user_id))
        {
            body = body.child(self.encryption_key_section(record, cx));
            body = body.child(self.secret_passcode_hint(user_id, cx));
        }
        body.into_any_element()
    }

    /// Phase S1: per-secret-chat passcode hint (TGX `SecretPasscodeInfo`,
    /// paraphrased, with the peer's name). The hint only — setting an
    /// additional per-chat passcode needs a full app passcode feature,
    /// which is out of this slice.
    fn secret_passcode_hint(&self, user_id: i64, cx: &mut Context<Self>) -> AnyElement {
        let name = Self::secret_peer_name(self.session(), user_id, "this chat");
        div()
            .flex()
            .flex_col()
            .w_full()
            .gap_2()
            .pt_2()
            .border_t_1()
            .border_color(cx.theme().border)
            .child(
                div()
                    .text_xs()
                    .font_semibold()
                    .text_color(cx.theme().muted_foreground)
                    .child("Passcode"),
            )
            .child(
                div()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child(format!(
                        "When you set up an additional passcode, you'll need to enter it each \
                         time you access {name}. Message preview will be hidden on the chats \
                         page.\n\nNote: if you forget it, contents of this chat will be \
                         lost.\n\nIf you need a global passcode, use Settings > Privacy and \
                         Security > Passcode Lock."
                    )),
            )
            .into_any_element()
    }

    /// Supergroup/channel panel: title, member count, description.
    fn supergroup_info_panel(&self, supergroup_id: i64, cx: &mut Context<Self>) -> AnyElement {
        let session = self.session();
        let (title, chat_id, is_channel) = session
            .and_then(|s| {
                s.chats.values().find_map(|chat| match chat.kind {
                    ChatKind::Supergroup {
                        supergroup_id: id,
                        is_channel,
                    } if id == supergroup_id => Some((chat.title.clone(), chat.id, is_channel)),
                    _ => None,
                })
            })
            .unwrap_or_else(|| {
                (
                    format!("Group {supergroup_id}"),
                    ChatId(supergroup_id),
                    false,
                )
            });
        let info = session
            .and_then(|s| s.supergroup_full_infos.get(&supergroup_id))
            .cloned();
        let description = info
            .as_ref()
            .map(|i| i.description.clone())
            .unwrap_or_default();
        let members = info.as_ref().map(|i| i.member_count).unwrap_or(0);
        let username = session
            .and_then(|s| s.supergroup_username(supergroup_id))
            .filter(|name| !name.is_empty())
            .map(|name| name.to_string());
        // Parity slice: the panel avatar reuses the chat-list avatar (photo
        // or colored initials).
        let roots = self.media_display_roots();
        let photo = session
            .and_then(|s| s.chat_photo_path(chat_id))
            .and_then(|path| sandboxed_display_path(path, &roots));
        let noun = if is_channel { "subscribers" } else { "members" };
        let mut body = div()
            .flex()
            .flex_col()
            .items_center()
            .gap_3()
            .p_4()
            .child(chat_avatar(&title, chat_id.0, photo.as_deref(), 96.))
            .child(
                div()
                    .flex()
                    .flex_col()
                    .items_center()
                    .gap_1()
                    .child(div().text_lg().font_semibold().child(title.clone()))
                    .child(
                        div()
                            .text_sm()
                            .text_color(cx.theme().muted_foreground)
                            .child(if members > 0 {
                                format!("{} {noun}", compact_count(members))
                            } else {
                                format!("{noun} unknown")
                            }),
                    )
                    .when_some(username, |this, name| {
                        this.child(
                            div()
                                .text_sm()
                                .text_color(cx.theme().muted_foreground)
                                .child(format!("@{name}")),
                        )
                    }),
            );
        if !description.is_empty() {
            body = body.child(
                div()
                    .flex()
                    .flex_col()
                    .w_full()
                    .gap_1()
                    .child(
                        div()
                            .text_xs()
                            .font_semibold()
                            .text_color(cx.theme().muted_foreground)
                            .child("Description"),
                    )
                    .child(div().text_sm().child(description)),
            );
        }
        // Phase A1: slow-mode admin control (`setChatSlowModeDelay`,
        // schema 1.8.67 line 13551 — allowed values 0/5/10/30/60/300/900/
        // 3600, supergroups only, requires `can_restrict_members`).
        // Creators hold all rights implicitly; administrators need the
        // explicit `can_restrict_members` right (lines 2500/1092). The new
        // delay arrives via `updateSupergroupFullInfo`.
        if !is_channel && self.can_change_slow_mode(supergroup_id) {
            let current_delay = info.as_ref().map(|i| i.slow_mode_delay).unwrap_or(0);
            let mut value_row = div().id("slow-mode-values").flex().flex_wrap().gap_1();
            for (label, value) in [
                ("Off", 0),
                ("5s", 5),
                ("10s", 10),
                ("30s", 30),
                ("1m", 60),
                ("5m", 300),
                ("15m", 900),
                ("1h", 3600),
            ] {
                let label = if value == current_delay {
                    format!("✓ {label}")
                } else {
                    label.to_string()
                };
                value_row = value_row.child(
                    Button::new(format!("slow-mode-set-{value}"))
                        .label(label)
                        .ghost()
                        .on_click(cx.listener(move |this, _, _, cx| {
                            this.set_slow_mode_delay(chat_id, value, cx);
                        })),
                );
            }
            body = body.child(
                div()
                    .flex()
                    .flex_col()
                    .w_full()
                    .gap_1()
                    .child(
                        div()
                            .text_xs()
                            .font_semibold()
                            .text_color(cx.theme().muted_foreground)
                            .child("Slow mode"),
                    )
                    .child(
                        div()
                            .text_sm()
                            .text_color(cx.theme().muted_foreground)
                            .child("Delay between messages for members"),
                    )
                    .child(value_row),
            );
        }
        // Phase D2: statistics entry point — shown only when
        // `supergroupFullInfo.can_get_statistics` is true (schema 1.8.67,
        // line 2792); `getChatStatistics` errors when it is false.
        if info.as_ref().is_some_and(|i| i.can_get_statistics) {
            let stats_chat_id = chat_id;
            body = body.child(
                Button::new("open-channel-statistics")
                    .label("Statistics")
                    .on_click(cx.listener(move |this, _, window, cx| {
                        this.open_info_panel_target(
                            InfoPanelTarget::Statistics(stats_chat_id.0),
                            window,
                            cx,
                        );
                    })),
            );
        }
        // Phase D3a: invite-link + join-request management (admins with
        // `can_invite_users` only; the sections no-op otherwise).
        body = body.child(self.invite_links_section(chat_id, cx));
        body = body.child(self.join_requests_section(chat_id, cx));
        // Phase D3b: administrator management (owner / admins with
        // `can_promote_members` only; the section no-ops otherwise).
        body = body.child(self.administrators_section(chat_id, cx));
        // Slice G1: group/channel management — members, permissions,
        // invite link, join requests, username, broadcast upgrade,
        // leave/delete. Every row is capability-gated inside.
        body = body.child(self.group_management_section(chat_id, is_channel, false, cx));
        // Phase D3c: recent-actions admin log (administrators and the
        // creator only; the section no-ops otherwise).
        body = body.child(self.event_log_section(chat_id, cx));
        // Slice G2: channel boost status + boost action.
        body = body.child(self.boost_section(chat_id, cx));
        body.into_any_element()
    }

    /// Slice G2: channel boost status (`getChatBoostStatus`, schema
    /// 1.8.67, line 13917) with the one-tap `boostChat` action. Shown
    /// for channels only; honest states: loading (request in flight),
    /// failed-with-retry, loaded "Level N · M boosts". `getChatBoostStatus`
    /// errors when boosts are unavailable for the chat — the failure
    /// renders instead of a fake number.
    fn boost_section(&self, chat_id: ChatId, cx: &mut Context<Self>) -> AnyElement {
        let is_channel = self.session().is_some_and(|session| {
            session.chats.get(&chat_id.0).is_some_and(|chat| {
                matches!(
                    chat.kind,
                    ChatKind::Supergroup {
                        is_channel: true,
                        ..
                    }
                )
            })
        });
        if !is_channel {
            return div().into_any_element();
        }
        let status = self
            .session()
            .and_then(|session| session.chat_boost_status.get(&chat_id.0).copied());
        let in_flight = self.session().is_some_and(|session| {
            session
                .requests
                .has_purpose_for_chat(RequestPurpose::GetChatBoostStatus, chat_id)
        });
        let mut section = div().flex().flex_col().w_full().gap_1().child(
            div()
                .text_xs()
                .font_semibold()
                .text_color(cx.theme().muted_foreground)
                .child("Channel boosts"),
        );
        match status {
            Some((level, boost_count)) => {
                section = section.child(
                    div()
                        .flex()
                        .items_center()
                        .w_full()
                        .gap_2()
                        .child(
                            div()
                                .flex_1()
                                .text_sm()
                                .text_color(cx.theme().muted_foreground)
                                .child(format!("Level {level} · {boost_count} boosts")),
                        )
                        .child(
                            Button::new("g2-boost-channel")
                                .label("Boost channel")
                                .ghost()
                                .on_click(cx.listener(move |this, _, _, cx| {
                                    this.boost_channel(chat_id, cx);
                                })),
                        ),
                );
            }
            None if in_flight => {
                section = section.child(
                    div()
                        .text_sm()
                        .text_color(cx.theme().muted_foreground)
                        .child("Loading boost status…"),
                );
            }
            None => {
                section = section.child(
                    div()
                        .flex()
                        .items_center()
                        .w_full()
                        .gap_1()
                        .child(
                            div()
                                .flex_1()
                                .text_sm()
                                .text_color(cx.theme().muted_foreground)
                                .child("Boost status unavailable."),
                        )
                        .child(
                            Button::new("g2-boost-retry")
                                .label("Retry")
                                .ghost()
                                .on_click(cx.listener(move |this, _, _, cx| {
                                    this.refresh_boost_status(chat_id, cx);
                                })),
                        ),
                );
            }
        }
        section.into_any_element()
    }

    /// Slice G2: re-request the boost status (bypasses the cache).
    fn refresh_boost_status(&mut self, chat_id: ChatId, cx: &mut Context<Self>) {
        if let Some(live) = self.live.as_mut() {
            live.driver.session.chat_boost_status.remove(&chat_id.0);
            if live.driver.fetch_chat_boost_status(chat_id).is_err() {
                self.status_note = "could not load boost status".into();
            }
        }
        cx.notify();
    }

    /// Slice G1: group/channel management section for the info panel.
    /// Every row is capability-gated (`chat_can_restrict_members`,
    /// `chat_is_owner`, `chat_can_invite_users`,
    /// `can_be_deleted_for_all_users`) so buttons only appear when the
    /// action can succeed. Basic groups get members / permissions /
    /// invite link / leave / delete; supergroups additionally get
    /// join-request toggle, username, and the one-way broadcast
    /// upgrade; channels get members (subscribers), username, invite
    /// link, leave / delete.
    /// Slice G2: `(sign_messages, show_message_sender)` for the
    /// channel's supergroup (`updateSupergroup` flags; unset = off).
    fn sign_flags(&self, chat_id: ChatId) -> (bool, bool) {
        self.session()
            .and_then(|session| {
                session
                    .chats
                    .get(&chat_id.0)
                    .and_then(|chat| match chat.kind {
                        ChatKind::Supergroup { supergroup_id, .. } => Some((
                            session
                                .supergroup_sign_messages
                                .get(&supergroup_id)
                                .copied()
                                .unwrap_or(false),
                            session
                                .supergroup_show_message_sender
                                .get(&supergroup_id)
                                .copied()
                                .unwrap_or(false),
                        )),
                        _ => None,
                    })
            })
            .unwrap_or((false, false))
    }

    fn group_management_section(
        &self,
        chat_id: ChatId,
        is_channel: bool,
        is_basic_group: bool,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let session = self.session();
        let can_restrict = session.is_some_and(|s| s.chat_can_restrict_members(chat_id));
        let is_owner = session.is_some_and(|s| s.chat_is_owner(chat_id));
        let can_invite = session.is_some_and(|s| s.chat_can_invite_users(chat_id));
        let can_add = session.is_some_and(|s| s.chat_can_add_members(chat_id));
        let can_delete = session
            .as_ref()
            .and_then(|s| s.chats.get(&chat_id.0))
            .is_some_and(|chat| chat.can_be_deleted_for_all_users);
        let is_member = session
            .as_ref()
            .and_then(|s| s.chats.get(&chat_id.0))
            .and_then(|chat| chat.my_member_status)
            .is_some_and(|status| {
                matches!(
                    status,
                    ChannelMemberStatus::Creator
                        | ChannelMemberStatus::Administrator
                        | ChannelMemberStatus::Member
                        | ChannelMemberStatus::Restricted
                )
            });
        let mut section = div().flex().flex_col().w_full().gap_1().child(
            div()
                .text_xs()
                .font_semibold()
                .text_color(cx.theme().muted_foreground)
                .child(if is_channel {
                    "Manage channel"
                } else {
                    "Manage group"
                }),
        );
        macro_rules! row {
            ($id:expr, $label:expr, |$this:ident, $window:ident, $cx:ident| $action:block) => {
                section = section.child(
                    Button::new($id)
                        .label($label)
                        .ghost()
                        .on_click(cx.listener(move |$this, _, $window, $cx| $action)),
                );
            };
        }
        // Members / subscribers — everyone who can see the panel and
        // add or restrict may manage; plain members get a read-only
        // list through the dialog's All tab.
        if can_add || can_restrict || is_member {
            let label = if is_channel { "Subscribers" } else { "Members" };
            row!("g1-open-members", label, |this, window, cx| {
                this.open_member_dialog(chat_id, window, cx);
            });
        }
        if can_restrict {
            row!(
                "g1-open-permissions",
                "Default permissions",
                |this, _window, cx| {
                    this.open_permissions_dialog(chat_id, cx);
                }
            );
        }
        if can_invite {
            row!(
                "g1-replace-invite-link",
                "Replace primary invite link",
                |this, _window, cx| {
                    this.replace_primary_invite_link(chat_id, cx);
                }
            );
        }
        // Supergroup-only: join-request toggle, username, broadcast
        // upgrade. `setSupergroupUsername` is owner-only (driver
        // enforces); broadcast groups can't toggle join-by-request.
        if !is_channel && !is_basic_group {
            if can_restrict && !self.chat_is_broadcast(chat_id) {
                let enabled = self.chat_join_by_request(chat_id);
                let label = if enabled {
                    "✓ Approve new members"
                } else {
                    "Approve new members"
                };
                row!("g1-toggle-join-request", label, |this, _window, cx| {
                    this.toggle_join_by_request(chat_id, cx);
                });
            }
            if is_owner {
                let username = self.chat_username(chat_id);
                let label = if username.is_empty() {
                    "Set public username".to_string()
                } else {
                    format!("Public username (@{username})")
                };
                section = section.child(
                    Button::new("g1-open-username")
                        .label(label)
                        .ghost()
                        .on_click(cx.listener(move |this, _, window, cx| {
                            this.open_username_dialog(chat_id, window, cx);
                        })),
                );
                if !self.chat_is_broadcast(chat_id) {
                    row!(
                        "g1-broadcast-upgrade",
                        "Convert to broadcast group",
                        |this, _window, cx| {
                            this.open_group_confirm(
                                chat_id,
                                GroupConfirmAction::BroadcastUpgrade,
                                cx,
                            );
                        }
                    );
                }
            }
        }
        // Slice G2: channel signatures + show authors (Telegram X
        // ProfileController: two toggles, gated on `can_change_info`;
        // disabling signatures also hides authors, mirroring
        // `ToggleSupergroupSignMessages(id, sign, sign && show)`).
        if is_channel && session.is_some_and(|session| session.chat_can_change_info(chat_id)) {
            let (sign, show) = self.sign_flags(chat_id);
            let label = if sign {
                "✓ Sign messages"
            } else {
                "Sign messages"
            };
            row!("g2-toggle-sign-messages", label, |this, _window, cx| {
                let (sign, show) = this.sign_flags(chat_id);
                this.set_sign_messages(chat_id, !sign, !sign && show, cx);
            });
            let show_label = if show && sign {
                "✓ Show message authors"
            } else {
                "Show message authors"
            };
            row!("g2-toggle-show-authors", show_label, |this, _window, cx| {
                let (_, show) = this.sign_flags(chat_id);
                // Enabling authors implies signatures (Telegram X forces
                // `show = sign && show`).
                this.set_sign_messages(chat_id, true, !show, cx);
            });
        }
        // Slice G2: aggressive anti-spam toggle (supergroups only;
        // gated on `supergroupFullInfo.can_toggle_aggressive_anti_spam`).
        if !is_channel
            && !is_basic_group
            && session.is_some_and(|session| session.chat_can_toggle_anti_spam(chat_id))
        {
            let enabled = self
                .session()
                .and_then(|session| {
                    session
                        .chats
                        .get(&chat_id.0)
                        .and_then(|chat| match chat.kind {
                            ChatKind::Supergroup { supergroup_id, .. } => session
                                .supergroup_anti_spam_enabled
                                .get(&supergroup_id)
                                .copied(),
                            _ => None,
                        })
                })
                .unwrap_or(false);
            let label = if enabled {
                "✓ Aggressive anti-spam"
            } else {
                "Aggressive anti-spam"
            };
            row!("g2-toggle-anti-spam", label, |this, _window, cx| {
                let enabled = this
                    .session()
                    .and_then(|session| {
                        session
                            .chats
                            .get(&chat_id.0)
                            .and_then(|chat| match chat.kind {
                                ChatKind::Supergroup { supergroup_id, .. } => session
                                    .supergroup_anti_spam_enabled
                                    .get(&supergroup_id)
                                    .copied(),
                                _ => None,
                            })
                    })
                    .unwrap_or(false);
                this.set_anti_spam(chat_id, !enabled, cx);
            });
        }
        // Slice G2: forum-topic management (admins with
        // `can_manage_topics` in forum supergroups).
        if !is_channel
            && !is_basic_group
            && session.is_some_and(|session| {
                session
                    .chats
                    .get(&chat_id.0)
                    .is_some_and(|chat| chat.is_forum_chat())
                    && session.chat_can_manage_topics(chat_id)
            })
        {
            row!(
                "g2-open-forum-manage",
                "Manage topics",
                |this, window, cx| {
                    this.open_forum_manage_dialog(chat_id, window, cx);
                }
            );
        }
        // Slice G2: welcome-message editor (admins with
        // `can_send_welcome_messages`; the check mark reflects
        // `Session::chat_has_welcome_messages`).
        if session.is_some_and(|session| session.chat_can_send_welcome_messages(chat_id)) {
            let has_welcome = session
                .as_ref()
                .and_then(|session| session.chat_has_welcome_messages.get(&chat_id.0).copied())
                .unwrap_or(false);
            let label = if has_welcome {
                "✓ Welcome message"
            } else {
                "Welcome message"
            };
            row!("g2-open-welcome", label, |this, window, cx| {
                this.open_welcome_dialog(chat_id, window, cx);
            });
        }
        if is_member {
            let label = if is_channel {
                "Leave channel"
            } else {
                "Leave group"
            };
            row!("g1-leave-chat", label, |this, _window, cx| {
                this.open_group_confirm(chat_id, GroupConfirmAction::LeaveChat, cx);
            });
        }
        // `deleteChat` (schema 1.8.67, line 11850): TDLib deletes for
        // everyone only when `chat.can_be_deleted_for_all_users` —
        // creator of a group/channel, or any private chat.
        if can_delete {
            row!("g1-delete-chat", "Delete group", |this, _window, cx| {
                this.open_group_confirm(chat_id, GroupConfirmAction::DeleteChat, cx);
            });
        }
        section.into_any_element()
    }

    /// Slice G1: basic-group info panel. Basic groups have no
    /// `supergroupFullInfo` — the panel shows the title, the member
    /// list entry point (`getBasicGroupFullInfo`), and the management
    /// section.
    fn basic_group_info_panel(&self, basic_group_id: i64, cx: &mut Context<Self>) -> AnyElement {
        let (title, chat_id) = self
            .session()
            .and_then(|s| {
                s.chats.values().find_map(|chat| match chat.kind {
                    ChatKind::BasicGroup { basic_group_id: id } if id == basic_group_id => {
                        Some((chat.title.clone(), chat.id))
                    }
                    _ => None,
                })
            })
            .unwrap_or_else(|| (format!("Group {basic_group_id}"), ChatId(basic_group_id)));
        let member_count = self
            .session()
            .and_then(|s| s.basic_group_members.get(&chat_id.0))
            .and_then(|fetch| match fetch {
                SupergroupMembersFetch::Loaded { total_count, .. } => Some(*total_count),
                _ => None,
            });
        let roots = self.media_display_roots();
        let photo = self
            .session()
            .and_then(|s| s.chat_photo_path(chat_id))
            .and_then(|path| sandboxed_display_path(path, &roots));
        let mut body = div()
            .flex()
            .flex_col()
            .items_center()
            .gap_3()
            .p_4()
            .child(chat_avatar(&title, chat_id.0, photo.as_deref(), 96.))
            .child(
                div()
                    .flex()
                    .flex_col()
                    .items_center()
                    .gap_1()
                    .child(div().text_lg().font_semibold().child(title.clone()))
                    .child(
                        div()
                            .text_sm()
                            .text_color(cx.theme().muted_foreground)
                            .child(match member_count {
                                Some(count) => format!("{count} members"),
                                None => "members unknown".to_string(),
                            }),
                    ),
            );
        body = body.child(self.group_management_section(chat_id, false, true, cx));
        body.into_any_element()
    }

    /// Phase D3a: human expiry for an invite link (`expiration_date` is a
    /// unix timestamp; 0 = never expires).
    fn invite_link_expiry(expiration_date: i32) -> String {
        if expiration_date == 0 {
            return "Never expires".into();
        }
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|duration| duration.as_secs() as i64)
            .unwrap_or(0);
        let remaining = i64::from(expiration_date) - now;
        if remaining <= 0 {
            "Expired".into()
        } else if remaining < 86_400 {
            "Expires today".into()
        } else if remaining < 172_800 {
            "Expires tomorrow".into()
        } else {
            format!("Expires in {} days", remaining / 86_400)
        }
    }

    /// Phase D3a: invite-link management section for the channel/group
    /// info panel. Shown only to admins who may manage links
    /// (`ChatSummary::can_invite_users`). Honest states: loading /
    /// failed-with-retry / loaded list. Each row shows the link name (or
    /// "Primary link" / "Invite link" fallback), uses, expiry, a
    /// join-request badge when `pending_join_request_count` > 0, and
    /// Copy + Revoke buttons. Revoking is the delete path (TDLib 1.8.67
    /// has no `deleteChatInviteLink`).
    fn invite_links_section(&self, chat_id: ChatId, cx: &mut Context<Self>) -> AnyElement {
        let can_manage = self
            .session()
            .is_some_and(|session| session.chat_can_invite_users(chat_id));
        if !can_manage {
            return div().into_any_element();
        }
        let fetch = self
            .session()
            .and_then(|session| session.invite_links.get(&chat_id.0))
            .cloned();
        let mut section = div().flex().flex_col().w_full().gap_1().child(
            div()
                .flex()
                .items_center()
                .w_full()
                .gap_1()
                .child(
                    div()
                        .text_xs()
                        .font_semibold()
                        .text_color(cx.theme().muted_foreground)
                        .child("Invite links"),
                )
                .child(div().flex_1())
                .child(
                    Button::new("invite-links-refresh")
                        .label("Refresh")
                        .ghost()
                        .on_click(cx.listener(move |this, _, _, cx| {
                            this.refresh_invite_links(chat_id, cx);
                        })),
                )
                .child(
                    Button::new("invite-link-create")
                        .label("Create")
                        .ghost()
                        .on_click(cx.listener(move |this, _, window, cx| {
                            this.open_invite_link_dialog(chat_id, window, cx);
                        })),
                ),
        );
        match fetch {
            None | Some(InviteLinkFetch::Loading) => {
                section = section.child(
                    div()
                        .text_sm()
                        .text_color(cx.theme().muted_foreground)
                        .child("Loading invite links…"),
                );
            }
            Some(InviteLinkFetch::Failed(message)) => {
                section = section.child(
                    div()
                        .flex()
                        .items_center()
                        .w_full()
                        .gap_1()
                        .child(
                            div()
                                .flex_1()
                                .text_sm()
                                .text_color(cx.theme().muted_foreground)
                                .child(message),
                        )
                        .child(
                            Button::new("invite-links-retry")
                                .label("Retry")
                                .ghost()
                                .on_click(cx.listener(move |this, _, _, cx| {
                                    this.refresh_invite_links(chat_id, cx);
                                })),
                        ),
                );
            }
            Some(InviteLinkFetch::Loaded(list)) => {
                if list.links.is_empty() {
                    section = section.child(
                        div()
                            .text_sm()
                            .text_color(cx.theme().muted_foreground)
                            .child("No invite links."),
                    );
                } else {
                    for (index, link) in list.links.into_iter().enumerate() {
                        let name = if !link.name.is_empty() {
                            link.name.clone()
                        } else if link.is_primary {
                            "Primary link".into()
                        } else {
                            "Invite link".into()
                        };
                        let uses = if link.member_limit > 0 {
                            format!("{}/{} uses", link.member_count, link.member_limit)
                        } else {
                            format!("{} uses", link.member_count)
                        };
                        let expiry = Self::invite_link_expiry(link.expiration_date);
                        let copy_link = link.invite_link.clone();
                        let revoke_link = link.invite_link.clone();
                        let mut row = div()
                            .id(("invite-link-row", index as u64))
                            .flex()
                            .flex_col()
                            .w_full()
                            .gap_1()
                            .child(
                                div()
                                    .flex()
                                    .items_center()
                                    .w_full()
                                    .gap_1()
                                    .child(div().flex_1().text_sm().child(name))
                                    .child(
                                        div()
                                            .text_xs()
                                            .text_color(cx.theme().muted_foreground)
                                            .child(format!("{uses} · {expiry}")),
                                    ),
                            )
                            .child(
                                div()
                                    .text_xs()
                                    .text_color(cx.theme().muted_foreground)
                                    .child(link.invite_link),
                            );
                        if link.pending_join_request_count > 0 {
                            row = row.child(
                                div()
                                    .text_xs()
                                    .font_semibold()
                                    .text_color(cx.theme().muted_foreground)
                                    .child(format!(
                                        "{} pending requests",
                                        link.pending_join_request_count
                                    )),
                            );
                        }
                        row = row.child(
                            div()
                                .flex()
                                .items_center()
                                .gap_1()
                                .child(
                                    Button::new(format!("invite-link-copy-{index}"))
                                        .label("Copy")
                                        .ghost()
                                        .on_click(cx.listener(move |this, _, _, cx| {
                                            this.copy_invite_link(&copy_link, cx);
                                        })),
                                )
                                .child(
                                    Button::new(format!("invite-link-revoke-{index}"))
                                        .label("Revoke")
                                        .ghost()
                                        .on_click(cx.listener(move |this, _, _, cx| {
                                            this.revoke_invite_link(chat_id, &revoke_link, cx);
                                        })),
                                ),
                        );
                        section = section.child(row);
                    }
                }
            }
        }
        section.into_any_element()
    }

    /// Phase D3a: join-request section. Approve/Decline per request;
    /// shows the requester's name (falls back to "User <id>") and bio.
    fn join_requests_section(&self, chat_id: ChatId, cx: &mut Context<Self>) -> AnyElement {
        let can_manage = self
            .session()
            .is_some_and(|session| session.chat_can_invite_users(chat_id));
        if !can_manage {
            return div().into_any_element();
        }
        let fetch = self
            .session()
            .and_then(|session| session.join_requests.get(&chat_id.0))
            .cloned();
        let pending_count = match &fetch {
            Some(JoinRequestFetch::Loaded(list)) => list.total_count,
            _ => self
                .session()
                .and_then(|session| session.pending_join_request_counts.get(&chat_id.0).copied())
                .unwrap_or(0),
        };
        let mut header = div().flex().items_center().w_full().gap_1().child(
            div()
                .text_xs()
                .font_semibold()
                .text_color(cx.theme().muted_foreground)
                .child("Join requests"),
        );
        if pending_count > 0 {
            header = header.child(
                div()
                    .text_xs()
                    .font_semibold()
                    .text_color(cx.theme().muted_foreground)
                    .child(pending_count.to_string()),
            );
        }
        header = header.child(div().flex_1()).child(
            Button::new("join-requests-refresh")
                .label("Refresh")
                .ghost()
                .on_click(cx.listener(move |this, _, _, cx| {
                    this.refresh_join_requests(chat_id, cx);
                })),
        );
        let mut section = div().flex().flex_col().w_full().gap_1().child(header);
        match fetch {
            None | Some(JoinRequestFetch::Loading) => {
                section = section.child(
                    div()
                        .text_sm()
                        .text_color(cx.theme().muted_foreground)
                        .child("Loading join requests…"),
                );
            }
            Some(JoinRequestFetch::Failed(message)) => {
                section = section.child(
                    div()
                        .flex()
                        .items_center()
                        .w_full()
                        .gap_1()
                        .child(
                            div()
                                .flex_1()
                                .text_sm()
                                .text_color(cx.theme().muted_foreground)
                                .child(message),
                        )
                        .child(
                            Button::new("join-requests-retry")
                                .label("Retry")
                                .ghost()
                                .on_click(cx.listener(move |this, _, _, cx| {
                                    this.refresh_join_requests(chat_id, cx);
                                })),
                        ),
                );
            }
            Some(JoinRequestFetch::Loaded(list)) => {
                if list.requests.is_empty() {
                    section = section.child(
                        div()
                            .text_sm()
                            .text_color(cx.theme().muted_foreground)
                            .child("No pending join requests."),
                    );
                } else {
                    for request in list.requests {
                        let user_id = request.user_id;
                        let name = self
                            .session()
                            .and_then(|session| session.user(user_id))
                            .map(|user| {
                                format!("{} {}", user.first_name, user.last_name)
                                    .trim()
                                    .to_owned()
                            })
                            .filter(|name| !name.is_empty())
                            .unwrap_or_else(|| format!("User {user_id}"));
                        let mut details = div()
                            .flex()
                            .flex_col()
                            .flex_1()
                            .gap_1()
                            .child(div().text_sm().child(name));
                        if !request.bio.is_empty() {
                            details = details.child(
                                div()
                                    .text_xs()
                                    .text_color(cx.theme().muted_foreground)
                                    .child(request.bio),
                            );
                        }
                        section = section.child(
                            div()
                                .id(("join-request-row", user_id as u64))
                                .flex()
                                .items_center()
                                .w_full()
                                .gap_1()
                                .child(details)
                                .child(
                                    Button::new(format!("join-request-approve-{user_id}"))
                                        .label("Approve")
                                        .ghost()
                                        .on_click(cx.listener(move |this, _, _, cx| {
                                            this.process_join_request(chat_id, user_id, true, cx);
                                        })),
                                )
                                .child(
                                    Button::new(format!("join-request-decline-{user_id}"))
                                        .label("Decline")
                                        .ghost()
                                        .on_click(cx.listener(move |this, _, _, cx| {
                                            this.process_join_request(chat_id, user_id, false, cx);
                                        })),
                                ),
                        );
                    }
                }
            }
        }
        section.into_any_element()
    }

    /// Phase D3b: administrator management section for the channel /
    /// supergroup info panel. Shown only when the viewer may manage
    /// admins (`Session::chat_can_manage_admins`: owner, or admin with
    /// `can_promote_members` — deny-by-default otherwise). Honest
    /// states: loading / failed-with-retry / loaded list. Each row
    /// shows the admin's name, custom title (a crown badge for the
    /// owner), and Edit + Remove buttons when the entry is editable
    /// (`can_be_edited` and not the owner — TDLib rejects edits to the
    /// creator and to admins it does not allow editing).
    fn administrators_section(&self, chat_id: ChatId, cx: &mut Context<Self>) -> AnyElement {
        if !self
            .session()
            .is_some_and(|session| session.chat_can_manage_admins(chat_id))
        {
            return div().into_any_element();
        }
        let fetch = self
            .session()
            .and_then(|session| session.admin_lists.get(&chat_id.0))
            .cloned();
        let mut section = div().flex().flex_col().w_full().gap_1().child(
            div()
                .flex()
                .items_center()
                .w_full()
                .gap_1()
                .child(
                    div()
                        .text_xs()
                        .font_semibold()
                        .text_color(cx.theme().muted_foreground)
                        .child("Administrators"),
                )
                .child(div().flex_1())
                .child(
                    Button::new("admin-list-refresh")
                        .label("Refresh")
                        .ghost()
                        .on_click(cx.listener(move |this, _, _, cx| {
                            this.refresh_administrators(chat_id, cx);
                        })),
                )
                .child(
                    Button::new("admin-promote-open")
                        .label("Add")
                        .ghost()
                        .on_click(cx.listener(move |this, _, window, cx| {
                            this.open_promote_picker(chat_id, window, cx);
                        })),
                ),
        );
        match fetch {
            None | Some(AdminListFetch::Loading) => {
                section = section.child(
                    div()
                        .text_sm()
                        .text_color(cx.theme().muted_foreground)
                        .child("Loading administrators…"),
                );
            }
            Some(AdminListFetch::Failed(message)) => {
                section = section.child(
                    div()
                        .flex()
                        .items_center()
                        .w_full()
                        .gap_1()
                        .child(
                            div()
                                .flex_1()
                                .text_sm()
                                .text_color(cx.theme().muted_foreground)
                                .child(message),
                        )
                        .child(
                            Button::new("admin-list-retry")
                                .label("Retry")
                                .ghost()
                                .on_click(cx.listener(move |this, _, _, cx| {
                                    this.refresh_administrators(chat_id, cx);
                                })),
                        ),
                );
            }
            Some(AdminListFetch::Loaded(list)) => {
                if list.is_empty() {
                    section = section.child(
                        div()
                            .text_sm()
                            .text_color(cx.theme().muted_foreground)
                            .child("No administrators."),
                    );
                } else {
                    for entry in &list {
                        section = section.child(self.admin_row(chat_id, entry, cx));
                    }
                }
            }
        }
        section.into_any_element()
    }

    /// Phase D3b: one row of the administrators list — name, custom
    /// title or role badge, Edit + Remove buttons for editable admins.
    fn admin_row(
        &self,
        chat_id: ChatId,
        entry: &ChatAdministratorEntry,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let name = self
            .session()
            .and_then(|session| session.user(entry.user_id))
            .map(|user| user.display_name())
            .unwrap_or_else(|| format!("User {}", entry.user_id));
        let role = if entry.is_owner {
            "👑 Owner".to_string()
        } else if entry.custom_title.is_empty() {
            "Admin".to_string()
        } else {
            entry.custom_title.clone()
        };
        let mut row = div()
            .id(("admin-row", entry.user_id as u64))
            .flex()
            .items_center()
            .w_full()
            .gap_1()
            .child(
                div()
                    .flex()
                    .flex_col()
                    .flex_1()
                    .gap_1()
                    .child(div().text_sm().child(name))
                    .child(
                        div()
                            .text_xs()
                            .text_color(cx.theme().muted_foreground)
                            .child(role),
                    ),
            );
        // The owner cannot be edited or demoted; non-editable admins
        // (granted by someone else) are server-rejected too.
        if entry.can_be_edited && !entry.is_owner {
            let user_id = entry.user_id;
            row = row
                .child(
                    Button::new(format!("admin-edit-{user_id}"))
                        .label("Edit")
                        .ghost()
                        .on_click(cx.listener(move |this, _, _, cx| {
                            this.open_rights_editor(chat_id, user_id, cx);
                        })),
                )
                .child(
                    Button::new(format!("admin-demote-{user_id}"))
                        .label("Remove")
                        .ghost()
                        .on_click(cx.listener(move |this, _, _, cx| {
                            this.open_demote_confirm(chat_id, user_id, cx);
                        })),
                );
        }
        row.into_any_element()
    }

    /// Phase D3c: "Recent actions" admin-log section for the channel/group
    /// info panel. Shown only to administrators and the creator
    /// (`Session::chat_can_view_event_log` — `getChatEventLog` "requires
    /// administrator rights", schema 1.8.67 line 15252). Honest states:
    /// loading / failed-with-retry / loaded rows with actor name, action
    /// description, and relative timestamp, plus "Load more" while older
    /// pages exist. Unhandled event types render as generic rows — never
    /// faked details.
    fn event_log_section(&self, chat_id: ChatId, cx: &mut Context<Self>) -> AnyElement {
        if !self
            .session()
            .is_some_and(|session| session.chat_can_view_event_log(chat_id))
        {
            return div().into_any_element();
        }
        let fetch = self
            .session()
            .and_then(|session| session.event_logs.get(&chat_id.0))
            .cloned();
        let mut section = div()
            .id("event-log-section")
            .flex()
            .flex_col()
            .w_full()
            .gap_1()
            .child(
                div()
                    .flex()
                    .items_center()
                    .w_full()
                    .gap_1()
                    .child(
                        div()
                            .text_xs()
                            .font_semibold()
                            .text_color(cx.theme().muted_foreground)
                            .child("Recent actions"),
                    )
                    .child(div().flex_1())
                    .child(
                        Button::new("event-log-refresh")
                            .label("Refresh")
                            .ghost()
                            .on_click(cx.listener(move |this, _, _, cx| {
                                this.refresh_event_log(chat_id, cx);
                            })),
                    ),
            );
        // Slice G2: compact search + filter controls. The search box
        // feeds `getChatEventLog.query` (schema 1.8.67, line 15252);
        // the chips flip `chatEventLogFilters` categories (line 7956).
        // An empty selection means "all types" (the driver passes
        // `null`), so "Clear" just removes every active chip.
        let mut controls = div().flex().items_center().w_full().gap_1();
        if let Some(input) = self.event_log_search.clone() {
            controls = controls.child(div().flex_1().child(Textarea::new(&input).h(px(32.))));
        }
        controls = controls.child(
            Button::new("event-log-search")
                .label("Search")
                .ghost()
                .on_click(cx.listener(move |this, _, _, cx| {
                    this.apply_event_log_search(chat_id, cx);
                })),
        );
        section = section.child(controls);
        let active_filters = self
            .session()
            .and_then(|session| session.event_log_filters.get(&chat_id.0).copied())
            .unwrap_or_default();
        section = section.child(self.event_log_filter_chips(chat_id, active_filters, cx));
        match fetch {
            None | Some(ChatEventLogFetch::Loading) => {
                section = section.child(
                    div()
                        .text_sm()
                        .text_color(cx.theme().muted_foreground)
                        .child("Loading recent actions…"),
                );
            }
            Some(ChatEventLogFetch::Failed(message)) => {
                section = section.child(
                    div()
                        .flex()
                        .items_center()
                        .w_full()
                        .gap_1()
                        .child(
                            div()
                                .flex_1()
                                .text_sm()
                                .text_color(cx.theme().muted_foreground)
                                .child(message),
                        )
                        .child(
                            Button::new("event-log-retry")
                                .label("Retry")
                                .ghost()
                                .on_click(cx.listener(move |this, _, _, cx| {
                                    this.refresh_event_log(chat_id, cx);
                                })),
                        ),
                );
            }
            Some(ChatEventLogFetch::Loaded(page)) => {
                if page.events.is_empty() {
                    section = section.child(
                        div()
                            .text_sm()
                            .text_color(cx.theme().muted_foreground)
                            .child("No recent actions."),
                    );
                } else {
                    // Slice G2: per-admin filter chips (client-side).
                    let admins = page.admin_user_ids();
                    if admins.len() > 1 {
                        section = section.child(self.event_log_admin_chips(&admins, cx));
                    }
                    let admin_filter = self.event_log_admin_filter;
                    let visible = page.events.iter().filter(|event| match admin_filter {
                        None => true,
                        Some(user_id) => {
                            matches!(event.member_id, MessageSender::User { user_id: id } if id == user_id)
                        }
                    });
                    for event in visible {
                        section = section.child(self.event_log_row(event, cx));
                    }
                    if page.has_more {
                        section = section.child(
                            Button::new("event-log-load-more")
                                .label("Load more")
                                .ghost()
                                .on_click(cx.listener(move |this, _, _, cx| {
                                    this.load_more_event_log(chat_id, cx);
                                })),
                        );
                    }
                }
            }
        }
        section.into_any_element()
    }

    /// Slice G2: per-admin filter chips for the event log. `None`
    /// (the "All admins" chip) shows every row; picking one admin filters
    /// the loaded page client-side.
    fn event_log_admin_chips(&self, admins: &[i64], cx: &mut Context<Self>) -> AnyElement {
        let current = self.event_log_admin_filter;
        let mut chips = div()
            .id("event-log-admin-filters")
            .flex()
            .flex_wrap()
            .w_full()
            .gap_1();
        let all_label = if current.is_none() {
            "✓ All admins".to_string()
        } else {
            "All admins".to_string()
        };
        chips = chips.child(
            Button::new("event-log-admin-all")
                .label(all_label)
                .ghost()
                .on_click(cx.listener(|this, _, _, cx| {
                    this.event_log_admin_filter = None;
                    cx.notify();
                })),
        );
        for user_id in admins.iter().copied() {
            let selected = current == Some(user_id);
            let name = self.group_call_participant_name(&MessageSender::User { user_id });
            let label = if selected {
                format!("✓ {name}")
            } else {
                name
            };
            chips = chips.child(
                Button::new(format!("event-log-admin-{user_id}"))
                    .label(label)
                    .ghost()
                    .on_click(cx.listener(move |this, _, _, cx| {
                        this.event_log_admin_filter = Some(user_id);
                        cx.notify();
                    })),
            );
        }
        chips.into_any_element()
    }

    /// Slice G2: one toggle chip per `chatEventLogFilters` category
    /// (schema 1.8.67, line 7956). Active chips show a check mark; the
    /// "Clear" chip appears when any category is active (an empty
    /// selection means "all types" — the driver passes `null`).
    fn event_log_filter_chips(
        &self,
        chat_id: ChatId,
        active: ChatEventLogFilterSet,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let categories: Vec<(&str, &str, bool, fn(&mut ChatEventLogFilterSet))> = vec![
            ("message-edits", "Edits", active.message_edits, |f| {
                f.message_edits = !f.message_edits
            }),
            (
                "message-deletions",
                "Deletions",
                active.message_deletions,
                |f| f.message_deletions = !f.message_deletions,
            ),
            ("message-pins", "Pins", active.message_pins, |f| {
                f.message_pins = !f.message_pins
            }),
            ("member-joins", "Joins", active.member_joins, |f| {
                f.member_joins = !f.member_joins
            }),
            ("member-leaves", "Leaves", active.member_leaves, |f| {
                f.member_leaves = !f.member_leaves
            }),
            ("member-invites", "Invites", active.member_invites, |f| {
                f.member_invites = !f.member_invites
            }),
            (
                "member-promotions",
                "Promotions",
                active.member_promotions,
                |f| f.member_promotions = !f.member_promotions,
            ),
            (
                "member-restrictions",
                "Restrictions",
                active.member_restrictions,
                |f| f.member_restrictions = !f.member_restrictions,
            ),
            (
                "member-tag-changes",
                "Tags",
                active.member_tag_changes,
                |f| f.member_tag_changes = !f.member_tag_changes,
            ),
            ("info-changes", "Info", active.info_changes, |f| {
                f.info_changes = !f.info_changes
            }),
            ("setting-changes", "Settings", active.setting_changes, |f| {
                f.setting_changes = !f.setting_changes
            }),
            (
                "invite-link-changes",
                "Invite links",
                active.invite_link_changes,
                |f| f.invite_link_changes = !f.invite_link_changes,
            ),
            (
                "video-chat-changes",
                "Video chats",
                active.video_chat_changes,
                |f| f.video_chat_changes = !f.video_chat_changes,
            ),
            ("forum-changes", "Forum", active.forum_changes, |f| {
                f.forum_changes = !f.forum_changes
            }),
            (
                "subscription-extensions",
                "Stars",
                active.subscription_extensions,
                |f| f.subscription_extensions = !f.subscription_extensions,
            ),
        ];
        let mut chips = div()
            .id("event-log-filters")
            .flex()
            .flex_wrap()
            .w_full()
            .gap_1();
        for (id, label, enabled, toggle) in categories {
            let label = if enabled {
                format!("✓ {label}")
            } else {
                label.to_string()
            };
            chips = chips.child(
                Button::new(format!("event-log-filter-{id}"))
                    .label(label)
                    .ghost()
                    .on_click(cx.listener(move |this, _, _, cx| {
                        this.toggle_event_log_filter(chat_id, toggle, cx);
                    })),
            );
        }
        if active.any_enabled() {
            chips = chips.child(
                Button::new("event-log-filter-clear")
                    .label("Clear")
                    .ghost()
                    .on_click(cx.listener(move |this, _, _, cx| {
                        this.clear_event_log_filters(chat_id, cx);
                    })),
            );
        }
        chips.into_any_element()
    }

    /// Slice G2: clear every event-log filter category for the chat and
    /// refetch (empty selection = all types).
    fn clear_event_log_filters(&mut self, chat_id: ChatId, cx: &mut Context<Self>) {
        if let Some(live) = self.live.as_mut() {
            live.driver.session.event_log_filters.remove(&chat_id.0);
            if live.driver.refresh_chat_event_log(chat_id).is_err() {
                self.status_note = "could not clear filters".into();
            }
        }
        cx.notify();
    }

    /// Phase D3c: one admin-log row — actor name, action description, and
    /// relative timestamp.
    fn event_log_row(&self, event: &ParsedChatEvent, cx: &mut Context<Self>) -> AnyElement {
        let actor = self.group_call_participant_name(&event.member_id);
        let description = self.event_log_action_description(event);
        div()
            .id(("event-log-row", event.id as u64))
            .flex()
            .w_full()
            .gap_2()
            .child(
                div()
                    .flex()
                    .flex_col()
                    .flex_1()
                    .gap_1()
                    .child(div().text_sm().child(actor))
                    .child(
                        div()
                            .text_xs()
                            .text_color(cx.theme().muted_foreground)
                            .child(description),
                    ),
            )
            .child(
                div()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child(event_log_relative_time(event.date)),
            )
            .into_any_element()
    }

    /// Phase D3c: human description of an admin-log action. Every string
    /// is built only from parsed fields; unhandled constructors render
    /// the honest generic "performed an action".
    fn event_log_action_description(&self, event: &ParsedChatEvent) -> String {
        let user_name = |user_id: i64| {
            self.session()
                .and_then(|session| session.user(user_id))
                .map(|user| user.display_name())
                .unwrap_or_else(|| format!("User {user_id}"))
        };
        let sender_name = |sender: &MessageSender| match sender {
            MessageSender::User { user_id } => user_name(*user_id),
            MessageSender::Chat { chat_id } => self
                .session()
                .and_then(|session| session.chats.get(chat_id))
                .map(|chat| chat.title.clone())
                .unwrap_or_else(|| format!("Chat {chat_id}")),
        };
        // Short quoted excerpt; long titles/descriptions are cut rather
        // than wrapping the row.
        let quote = |text: &str| {
            let mut short: String = text.chars().take(60).collect();
            if text.chars().count() > 60 {
                short.push('…');
            }
            format!("\"{short}\"")
        };
        let with_text = |verb: &str, text: &str| {
            if text.is_empty() {
                verb.to_owned()
            } else {
                format!("{verb} {}", quote(text))
            }
        };
        match &event.action {
            ChatEventAction::MessageEdited { text, .. } => with_text("edited a message", text),
            ChatEventAction::MessageDeleted { text, .. } => with_text("deleted a message", text),
            ChatEventAction::MessagePinned { text, .. } => with_text("pinned a message", text),
            ChatEventAction::MessageUnpinned { text, .. } => with_text("unpinned a message", text),
            ChatEventAction::MemberJoined => "joined the chat".to_owned(),
            ChatEventAction::MemberJoinedByInviteLink {
                invite_link_name, ..
            } => {
                if invite_link_name.is_empty() {
                    "joined via an invite link".to_owned()
                } else {
                    format!("joined via invite link {}", quote(invite_link_name))
                }
            }
            ChatEventAction::MemberJoinedByRequest {
                approver_user_id, ..
            } => {
                if *approver_user_id == 0 {
                    "joined via an approved join request".to_owned()
                } else {
                    format!("join request approved by {}", user_name(*approver_user_id))
                }
            }
            ChatEventAction::MemberInvited { user_id, .. } => {
                format!("invited {}", user_name(*user_id))
            }
            ChatEventAction::MemberPromoted {
                user_id,
                old_status,
                new_status,
            } => {
                let name = user_name(*user_id);
                match (old_status, new_status) {
                    (_, ChannelMemberStatus::Creator) => {
                        format!("transferred ownership to {name}")
                    }
                    (_, ChannelMemberStatus::Administrator) => {
                        format!("promoted {name} to administrator")
                    }
                    (ChannelMemberStatus::Administrator, ChannelMemberStatus::Member) => {
                        format!("removed {name} as administrator")
                    }
                    _ => format!("changed {name}'s role"),
                }
            }
            ChatEventAction::MemberRestricted {
                member_id,
                old_status,
                new_status,
            } => {
                let name = sender_name(member_id);
                match (old_status, new_status) {
                    (_, ChannelMemberStatus::Banned) => format!("banned {name}"),
                    (_, ChannelMemberStatus::Restricted) => format!("restricted {name}"),
                    (ChannelMemberStatus::Banned, _) => format!("unbanned {name}"),
                    (ChannelMemberStatus::Restricted, _) => {
                        format!("lifted restrictions on {name}")
                    }
                    _ => format!("changed {name}'s restrictions"),
                }
            }
            ChatEventAction::DescriptionChanged {
                new_description, ..
            } => {
                if new_description.is_empty() {
                    "cleared the description".to_owned()
                } else {
                    format!("changed the description to {}", quote(new_description))
                }
            }
            ChatEventAction::PhotoChanged => "changed the chat photo".to_owned(),
            ChatEventAction::TitleChanged { new_title, .. } => {
                format!("changed the title to {}", quote(new_title))
            }
            ChatEventAction::InviteLinkEdited {
                old_name, new_name, ..
            } => {
                let name = if new_name.is_empty() {
                    old_name
                } else {
                    new_name
                };
                if name.is_empty() {
                    "edited an invite link".to_owned()
                } else {
                    format!("edited invite link {}", quote(name))
                }
            }
            ChatEventAction::InviteLinkRevoked { name, .. } => {
                if name.is_empty() {
                    "revoked an invite link".to_owned()
                } else {
                    format!("revoked invite link {}", quote(name))
                }
            }
            ChatEventAction::InviteLinkDeleted { name, .. } => {
                if name.is_empty() {
                    "deleted an invite link".to_owned()
                } else {
                    format!("deleted invite link {}", quote(name))
                }
            }
            ChatEventAction::Unsupported { .. } => "performed an action".to_owned(),
        }
    }

    /// Phase D2: the channel/group statistics view (`getChatStatistics`,
    /// schema 1.8.67 line 15760), opened from the info panel when
    /// `supergroupFullInfo.can_get_statistics` is true. Honest about
    /// absent data: loading / error / still-processing states render as
    /// text, and graphs without a usable series are omitted — no
    /// placeholder numbers anywhere.
    fn chat_statistics_panel(&self, chat_id: i64, cx: &mut Context<Self>) -> AnyElement {
        let session = self.session();
        let (title, is_channel) = session
            .and_then(|s| s.chats.get(&chat_id))
            .map(|chat| {
                let is_channel = matches!(
                    chat.kind,
                    ChatKind::Supergroup {
                        is_channel: true,
                        ..
                    }
                );
                (chat.title.clone(), is_channel)
            })
            .unwrap_or_else(|| (format!("Chat {chat_id}"), false));
        let mut body = div()
            .flex()
            .flex_col()
            .gap_3()
            .p_4()
            .child(div().text_lg().font_semibold().child(title))
            .child(
                div()
                    .text_sm()
                    .text_color(cx.theme().muted_foreground)
                    .child(if is_channel {
                        "Channel statistics"
                    } else {
                        "Group statistics"
                    }),
            );
        match session.and_then(|s| s.chat_statistics.get(&chat_id).cloned()) {
            None | Some(ChatStatisticsFetch::Loading) => {
                body = body.child(
                    div()
                        .text_sm()
                        .text_color(cx.theme().muted_foreground)
                        .child("Loading statistics…"),
                );
            }
            Some(ChatStatisticsFetch::Failed(message)) => {
                let retry_chat = chat_id;
                body = body.child(div().text_sm().child(message)).child(
                    Button::new("statistics-retry")
                        .label("Retry")
                        .on_click(cx.listener(move |this, _, _, cx| {
                            this.refresh_statistics(retry_chat, cx);
                        })),
                );
            }
            Some(ChatStatisticsFetch::Loaded(statistics)) => {
                body = self.statistics_body(chat_id, &statistics, is_channel, cx);
            }
        }
        body.into_any_element()
    }

    /// Phase D2: the loaded-statistics body, shared by the channel and
    /// supergroup variants.
    fn statistics_body(
        &self,
        chat_id: i64,
        statistics: &ChatStatistics,
        is_channel: bool,
        cx: &mut Context<Self>,
    ) -> Div {
        let session = self.session();
        let display_name = |user_id: i64| -> String {
            session
                .and_then(|s| s.user(user_id))
                .map(|u| u.display_name())
                .filter(|name| !name.is_empty())
                .unwrap_or_else(|| format!("User {user_id}"))
        };
        let noun = if is_channel { "Subscribers" } else { "Members" };
        let mut body = div();
        let (period_start, period_end, values, graphs, footer) = match statistics {
            ChatStatistics::Channel(stats) => {
                let values = vec![
                    (noun, stats.member_count),
                    ("Mean views", stats.mean_message_view_count),
                    ("Mean shares", stats.mean_message_share_count),
                    ("Mean reactions", stats.mean_message_reaction_count),
                    ("Mean story views", stats.mean_story_view_count),
                    ("Mean story shares", stats.mean_story_share_count),
                    ("Mean story reactions", stats.mean_story_reaction_count),
                ];
                let graphs: Vec<(&str, &StatisticalGraph)> = vec![
                    ("Members", &stats.member_count_graph),
                    ("Joins", &stats.join_graph),
                    ("Views by hour", &stats.view_count_by_hour_graph),
                    ("Message interactions", &stats.message_interaction_graph),
                ];
                let mut footer: Vec<String> = stats
                    .recent_interactions
                    .iter()
                    .map(|info| {
                        let kind = match info.object {
                            quill::telegram::envelope::ChatStatisticsObject::Message {
                                message_id,
                            } => format!("Post {message_id}"),
                            quill::telegram::envelope::ChatStatisticsObject::Story { story_id } => {
                                format!("Story {story_id}")
                            }
                        };
                        format!(
                            "{kind} — {} views · {} forwards · {} reactions",
                            format_stat_count(info.view_count as f64),
                            format_stat_count(info.forward_count as f64),
                            format_stat_count(info.reaction_count as f64),
                        )
                    })
                    .collect();
                if footer.is_empty() {
                    footer.push("No recent interactions yet.".to_string());
                }
                (
                    stats.period_start,
                    stats.period_end,
                    values,
                    graphs,
                    ("Recent interactions".to_string(), footer),
                )
            }
            ChatStatistics::Supergroup(stats) => {
                let values = vec![
                    (noun, stats.member_count),
                    ("Messages", stats.message_count),
                    ("Viewers", stats.viewer_count),
                    ("Senders", stats.sender_count),
                ];
                let graphs: Vec<(&str, &StatisticalGraph)> = vec![
                    ("Members", &stats.member_count_graph),
                    ("Joins", &stats.join_graph),
                    ("Messages by day", &stats.day_graph),
                    ("Messages by week", &stats.week_graph),
                ];
                let mut footer: Vec<String> = Vec::new();
                for sender in &stats.top_senders {
                    footer.push(format!(
                        "{} — {} messages",
                        display_name(sender.user_id),
                        format_stat_count(sender.sent_message_count as f64),
                    ));
                }
                for admin in &stats.top_administrators {
                    footer.push(format!(
                        "{} — {} deleted · {} banned · {} restricted",
                        display_name(admin.user_id),
                        admin.deleted_message_count,
                        admin.banned_user_count,
                        admin.restricted_user_count,
                    ));
                }
                for inviter in &stats.top_inviters {
                    footer.push(format!(
                        "{} — {} added",
                        display_name(inviter.user_id),
                        inviter.added_member_count,
                    ));
                }
                if footer.is_empty() {
                    footer.push("No top contributors yet.".to_string());
                }
                (
                    stats.period_start,
                    stats.period_end,
                    values,
                    graphs,
                    (
                        "Top senders · administrators · inviters".to_string(),
                        footer,
                    ),
                )
            }
        };
        body = body.child(
            div()
                .text_xs()
                .text_color(cx.theme().muted_foreground)
                .child(format!(
                    "{} – {}",
                    format_statistics_day(period_start),
                    format_statistics_day(period_end)
                )),
        );
        for (label, value) in values {
            body = body.child(stats_value_row(label, &value));
        }
        body = body.child(
            div()
                .text_xs()
                .font_semibold()
                .text_color(cx.theme().muted_foreground)
                .child("Notifications enabled")
                .child(div().text_sm().child(match statistics {
                    ChatStatistics::Channel(stats) => {
                        format!("{:.1}%", stats.enabled_notifications_percentage)
                    }
                    ChatStatistics::Supergroup(_) => "—".to_string(),
                })),
        );
        for (label, graph) in graphs {
            if let Some(row) = stats_graph_row(label, graph, cx) {
                body = body.child(row);
            }
        }
        let (footer_title, footer_lines) = footer;
        let mut footer_div = div().flex().flex_col().gap_1().child(
            div()
                .text_xs()
                .font_semibold()
                .text_color(cx.theme().muted_foreground)
                .child(footer_title),
        );
        for line in footer_lines {
            footer_div = footer_div.child(div().text_sm().child(line));
        }
        body = body.child(footer_div);
        let refresh_chat = chat_id;
        body.child(
            Button::new("statistics-refresh")
                .label("Refresh")
                .ghost()
                .on_click(cx.listener(move |this, _, _, cx| {
                    this.refresh_statistics(refresh_chat, cx);
                })),
        )
    }

    /// Phase D2: explicit statistics refresh — clears the cached result
    /// and re-sends `getChatStatistics`.
    fn refresh_statistics(&mut self, chat_id: i64, cx: &mut Context<Self>) {
        if let Some(live) = self.live.as_mut() {
            if let Err(err) = live.driver.refresh_chat_statistics(ChatId(chat_id), false) {
                self.status_note = format!("statistics refresh failed: {err:?}");
            }
        }
        cx.notify();
    }

    fn open_add_contact_dialog(
        &mut self,
        user_id: i64,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let (phone, first, last) = self
            .session()
            .and_then(|s| s.user(user_id))
            .map(|u| {
                (
                    u.phone_number.clone(),
                    u.first_name.clone(),
                    u.last_name.clone(),
                )
            })
            .unwrap_or_default();
        self.add_contact_dialog = Some(AddContactDialog::new(
            window, cx, user_id, &phone, &first, &last,
        ));
        if let Some(dialog) = &self.add_contact_dialog {
            dialog
                .phone_input
                .update(cx, |input, cx| input.focus(window, cx));
        }
        cx.notify();
    }

    fn close_add_contact_dialog(&mut self, cx: &mut Context<Self>) {
        self.add_contact_dialog = None;
        cx.notify();
    }

    /// Submit the add-contact dialog. The phone field is required —
    /// `addContact` needs an `importedContact`, and Quill does not offer
    /// adding by bare user id.
    fn submit_add_contact_dialog(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let draft = self
            .add_contact_dialog
            .as_ref()
            .and_then(|dialog| dialog.draft(cx));
        let Some((user_id, phone, first, last)) = draft else {
            self.status_note = "Enter a phone number to add the contact.".into();
            cx.notify();
            return;
        };
        if let Some(live) = self.live.as_mut() {
            match live.driver.add_contact(user_id, &phone, &first, &last) {
                Ok(_) => {
                    self.add_contact_dialog = None;
                    self.status_note = "Contact add requested.".into();
                }
                Err(err) => {
                    self.status_note = format!("add contact failed: {err:?}");
                }
            }
        } else {
            // Demo: no driver — just close.
            self.add_contact_dialog = None;
            self.status_note = "Contact add requested.".into();
        }
        let _ = window;
        cx.notify();
    }

    /// Add-contact dialog overlay (phone + first/last name), centered over
    /// the shell like the media viewer.
    fn add_contact_dialog_overlay(&self, cx: &mut Context<Self>) -> Option<AnyElement> {
        let dialog = self.add_contact_dialog.as_ref()?;
        let name = self
            .session()
            .and_then(|s| s.user(dialog.user_id))
            .map(|u| u.display_name())
            .unwrap_or_else(|| format!("User {}", dialog.user_id));
        Some(
            div()
                .id("add-contact-overlay")
                .absolute()
                .top_0()
                .left_0()
                .right_0()
                .bottom_0()
                .flex()
                .items_center()
                .justify_center()
                .child(
                    div()
                        .id("add-contact-backdrop")
                        .absolute()
                        .top_0()
                        .left_0()
                        .right_0()
                        .bottom_0()
                        .bg(rgba(0x000000e6))
                        .on_click(cx.listener(|this, _, _, cx| {
                            this.close_add_contact_dialog(cx);
                        })),
                )
                .child(
                    div()
                        .id("add-contact-panel")
                        .flex()
                        .flex_col()
                        .gap_2()
                        .p_4()
                        .w(px(360.))
                        .rounded_md()
                        .border_1()
                        .border_color(cx.theme().border)
                        .bg(cx.theme().sidebar)
                        .child(
                            div()
                                .text_sm()
                                .font_semibold()
                                .child(format!("Add {name} to contacts")),
                        )
                        .child(
                            div()
                                .flex()
                                .flex_col()
                                .gap_1()
                                .child(
                                    div()
                                        .text_xs()
                                        .text_color(cx.theme().muted_foreground)
                                        .child("Phone number"),
                                )
                                .child(Textarea::new(&dialog.phone_input).h(px(40.))),
                        )
                        .child(
                            div()
                                .flex()
                                .flex_col()
                                .gap_1()
                                .child(
                                    div()
                                        .text_xs()
                                        .text_color(cx.theme().muted_foreground)
                                        .child("First name"),
                                )
                                .child(Textarea::new(&dialog.first_name_input).h(px(40.))),
                        )
                        .child(
                            div()
                                .flex()
                                .flex_col()
                                .gap_1()
                                .child(
                                    div()
                                        .text_xs()
                                        .text_color(cx.theme().muted_foreground)
                                        .child("Last name"),
                                )
                                .child(Textarea::new(&dialog.last_name_input).h(px(40.))),
                        )
                        .child(
                            div()
                                .flex()
                                .gap_2()
                                .child(
                                    Button::new("add-contact-submit")
                                        .label("Add contact")
                                        .on_click(cx.listener(|this, _, window, cx| {
                                            this.submit_add_contact_dialog(window, cx);
                                        })),
                                )
                                .child(
                                    Button::new("add-contact-cancel")
                                        .label("Cancel")
                                        .ghost()
                                        .on_click(cx.listener(|this, _, _, cx| {
                                            this.close_add_contact_dialog(cx);
                                        })),
                                ),
                        ),
                )
                .into_any_element(),
        )
    }

    /// Phase C1: call overlay — incoming / outgoing / active / ended
    /// call UI above everything else. **Signaling only**: when a call
    /// would need media, the card says so honestly (audio transport is
    /// the C2 libtgvoip spike, not faked here).
    fn call_overlay(&mut self, cx: &mut Context<Self>) -> Option<AnyElement> {
        let session = self.session()?;
        if session.active_call.is_none()
            && session.call_summary.is_none()
            && session.call_error.is_none()
        {
            return None;
        }
        Some(self.call_card(cx).into_any_element())
    }

    /// Phase C1: format a call clock as `m:ss`.
    fn call_clock(secs: u64) -> String {
        format!("{}:{:02}", secs / 60, secs % 60)
    }

    fn call_peer_name(&self, user_id: i64) -> String {
        self.session()
            .and_then(|s| s.user(user_id))
            .map(|u| u.display_name())
            .unwrap_or_else(|| format!("User {user_id}"))
    }

    fn call_card(&mut self, cx: &mut Context<Self>) -> impl IntoElement {
        let session = self.session();
        let active = session.and_then(|s| s.active_call.clone());
        let summary = session.and_then(|s| s.call_summary.clone());
        let error = session.and_then(|s| s.call_error.clone());

        let mut card = div()
            .id("call-card")
            .flex()
            .flex_col()
            .items_center()
            .gap_3()
            .p_6()
            .w(px(360.))
            .rounded_lg()
            .border_1()
            .border_color(cx.theme().border)
            .bg(cx.theme().sidebar);

        if let Some(call) = active {
            card = self.call_active_card(card, &call, error.as_deref(), cx);
        } else if let Some(summary) = summary {
            card = self.call_summary_card(card, &summary, cx);
        } else if let Some(error) = error {
            card =
                card.child(div().text_sm().font_semibold().child("Call failed"))
                    .child(
                        div()
                            .text_xs()
                            .text_color(cx.theme().muted_foreground)
                            .child(error),
                    )
                    .child(Button::new("call-error-dismiss").label("Dismiss").on_click(
                        cx.listener(|this, _, _, cx| {
                            this.dismiss_call_error(cx);
                        }),
                    ));
        }

        div()
            .id("call-overlay")
            .absolute()
            .top_0()
            .left_0()
            .right_0()
            .bottom_0()
            .flex()
            .items_center()
            .justify_center()
            .child(
                div()
                    .id("call-backdrop")
                    .absolute()
                    .top_0()
                    .left_0()
                    .right_0()
                    .bottom_0()
                    .bg(rgba(0x000000e6)),
            )
            .child(card)
    }

    /// Phase C2e: the video stage for a connected video call — the peer's
    /// camera as the main tile, the local preview as a 160x120 PiP
    /// anchored bottom-right. Frames come from the driver (live) or the
    /// demo fixture (screenshot mode); both tiles degrade to honest
    /// status text when a feed is missing, and decoded tiles are cached
    /// by frame seq so re-renders don't re-decode.
    fn call_video_stage(&mut self, call: &ActiveCall, name: &str) -> Div {
        let (remote_frame, local_frame): (
            Option<quill::calls::engine::VideoFrame>,
            Option<quill::calls::engine::VideoFrame>,
        ) = if let Some(live) = self.live.as_ref() {
            (
                live.driver.latest_video_frame(call.id, false),
                live.driver.latest_video_frame(call.id, true),
            )
        } else {
            (
                self.demo_remote_frame.clone(),
                self.demo_local_frame.clone(),
            )
        };

        let status_text = |text: &str| {
            div()
                .flex()
                .flex_col()
                .items_center()
                .justify_center()
                .gap_1()
                .child(div().text_2xl().child("📹"))
                .child(
                    div()
                        .text_xs()
                        .text_color(rgb(0x9a9a9a))
                        .child(text.to_string()),
                )
        };
        let video_img = |image: Arc<RenderImage>| {
            img(ImageSource::from(image))
                .w_full()
                .h_full()
                .object_fit(ObjectFit::Contain)
        };

        let remote: AnyElement = match (call.remote_video, remote_frame.as_ref()) {
            (quill::calls::engine::RemoteVideoState::Active, Some(frame)) => {
                match self.cached_video_image(false, frame) {
                    Some(image) => video_img(image).into_any_element(),
                    None => status_text("Couldn't decode the peer's video").into_any_element(),
                }
            }
            (quill::calls::engine::RemoteVideoState::Active, None) => {
                status_text("Connecting video…").into_any_element()
            }
            (quill::calls::engine::RemoteVideoState::Paused, _) => {
                status_text("Video paused by peer").into_any_element()
            }
            (quill::calls::engine::RemoteVideoState::Inactive, _) => div()
                .flex()
                .flex_col()
                .items_center()
                .justify_center()
                .gap_1()
                .child(initials_avatar(name, 48.))
                .child(
                    div()
                        .text_xs()
                        .font_semibold()
                        .text_color(rgb(0xffffff))
                        .child(name.to_string()),
                )
                .child(
                    div()
                        .text_xs()
                        .text_color(rgb(0x9a9a9a))
                        .child("Peer's camera is off"),
                )
                .into_any_element(),
        };

        let camera_on = self.call_camera_effective(call);
        let local: AnyElement = match (camera_on, local_frame.as_ref()) {
            (true, Some(frame)) => match self.cached_video_image(true, frame) {
                Some(image) => video_img(image).into_any_element(),
                None => status_text("Couldn't decode the camera preview").into_any_element(),
            },
            (true, None) => status_text("Starting camera…").into_any_element(),
            (false, _) => status_text("Camera off").into_any_element(),
        };

        div()
            .w_full()
            .relative()
            .child(
                div()
                    .w_full()
                    .h(px(240.))
                    .rounded_md()
                    .bg(rgb(0x161616))
                    .overflow_hidden()
                    .flex()
                    .items_center()
                    .justify_center()
                    .child(remote),
            )
            .child(
                div()
                    .absolute()
                    .bottom_2()
                    .right_2()
                    .w(px(160.))
                    .h(px(120.))
                    .rounded_md()
                    .bg(rgb(0x161616))
                    .overflow_hidden()
                    .border_1()
                    .border_color(rgb(0x333333))
                    .child(local),
            )
    }

    fn call_active_card(
        &mut self,
        card: Stateful<Div>,
        call: &ActiveCall,
        error: Option<&str>,
        cx: &mut Context<Self>,
    ) -> Stateful<Div> {
        let name = self.call_peer_name(call.user_id);
        let kind_line = if call.is_video {
            "📹 Video call"
        } else {
            "Voice call"
        };
        let (status, clock): (String, Option<String>) = match &call.state {
            CallState::Pending { .. } => {
                let elapsed = call.started_at.elapsed().as_secs();
                if call.is_outgoing {
                    ("Calling…".to_string(), Some(Self::call_clock(elapsed)))
                } else {
                    ("Incoming call".to_string(), Some(Self::call_clock(elapsed)))
                }
            }
            CallState::ExchangingKeys => ("Connecting…".to_string(), None),
            CallState::Ready => {
                use quill::calls::engine::TransportState;
                let status = match call.transport {
                    Some(TransportState::Connected) if call.muted => {
                        "Muted - microphone off".to_string()
                    }
                    Some(TransportState::Connected) => "Connected".to_string(),
                    Some(TransportState::Reconnecting) => "Reconnecting audio…".to_string(),
                    Some(TransportState::Failed) => format!(
                        "Couldn't start audio: {}. The call is up but carries no sound.",
                        call.transport_error.as_deref().unwrap_or("unknown error")
                    ),
                    Some(TransportState::Closed) => "Audio disconnected.".to_string(),
                    None | Some(TransportState::Connecting) => "Connecting audio...".to_string(),
                };
                (
                    status,
                    Some(Self::call_clock(call.connected_secs().max(0) as u64)),
                )
            }
            CallState::HangingUp => ("Hanging up…".to_string(), None),
            // A future state the pinned schema doesn't know: label it
            // honestly instead of pretending it means something else.
            CallState::Unknown(type_name) => (format!("Call state: {type_name}"), None),
            // Terminal states end the call in the reducer, so this arm
            // is unreachable — but never crash the overlay on it.
            CallState::Discarded { .. } | CallState::Error { .. } => ("Ending…".to_string(), None),
        };
        let mut card = card;
        // Phase C2e: a connected video call shows the video stage
        // (peer's camera as the main tile, local preview as a PiP);
        // every other state keeps the avatar.
        if call.is_video && matches!(call.state, CallState::Ready) {
            card = card.child(self.call_video_stage(call, &name));
        } else {
            card = card.child(initials_avatar(&name, 72.));
        }
        card = card
            .child(div().text_lg().font_semibold().child(name))
            .child(
                div()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child(kind_line),
            )
            .child(div().text_sm().child(status));
        if let Some(clock) = clock {
            card = card.child(div().text_2xl().font_semibold().child(clock));
        }
        // E2E verification emojis, straight from `callStateReady`
        // (:7068) — same rendering as the group-call card. Hidden
        // until TDLib sends the 4-emoji fingerprint.
        if let Some(ready) = &call.ready
            && !ready.emojis.is_empty()
        {
            card = card.child(
                div()
                    .flex()
                    .items_center()
                    .gap_2()
                    .child(
                        div()
                            .text_xs()
                            .text_color(cx.theme().muted_foreground)
                            .child("End-to-end verification:"),
                    )
                    .child(div().text_2xl().child(ready.emojis.join(" "))),
            );
        }
        // Honest no-transport note: the call can be "Connected" at the
        // signaling level while carrying no audio or video. Never fake
        // a live call. Every pre-connected card carries it — incoming
        // ringing, outgoing "Calling…", connecting — and the end screen
        // repeats the note below; accepting/placing starts no media in
        // this build.
        let no_transport_note = matches!(
            call.state,
            CallState::Ready | CallState::ExchangingKeys | CallState::Pending { .. }
        );
        if no_transport_note {
            // Phase C2e: video is real once the driver is ready (engine
            // + camera); otherwise say exactly what's missing instead of
            // the old "ships in a later slice" note.
            let video_ready = self
                .live
                .as_ref()
                .is_some_and(|live| live.driver.call_video_ready())
                || self.live.is_none();
            let note = if call.is_video {
                if video_ready {
                    "Video connecting — tiles fill in as cameras stream."
                } else {
                    "Video unavailable — no camera found."
                }
            } else if call.transport == Some(quill::calls::engine::TransportState::Connected) {
                "Audio connected"
            } else {
                "Waiting for audio transport"
            };
            card = card.child(
                div()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child(note),
            );
        }
        // Phase C1b: local-only mute state. Tracked on the call but a
        // no-op without media transport — labeled honestly.
        let show_mute_note =
            call.muted && matches!(call.state, CallState::Ready | CallState::Unknown(_));
        if show_mute_note {
            card = card.child(
                div()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child("Microphone muted"),
            );
        }
        if let Some(error) = error {
            card = card.child(
                div()
                    .text_xs()
                    .text_color(rgb(0xe17076))
                    .child(error.to_string()),
            );
        }
        if let Some(error) = &call.transport_error {
            card = card.child(
                div()
                    .text_xs()
                    .text_color(rgb(0xe17076))
                    .child(error.clone()),
            );
        }
        if matches!(call.state, CallState::Ready) {
            // Phase C2c: microphone/speaker pickers. Live state comes
            // from the driver; the screenshot demo injects demo devices
            // only (no live Telegram, no real hardware). Empty means the
            // engine reported none — never fabricated.
            let no_engine = self
                .live
                .as_ref()
                .is_some_and(|live| !live.driver.has_call_engine());
            let (devices, selected): (
                Vec<quill::calls::engine::MediaDevice>,
                (Option<String>, Option<String>),
            ) = if let Some(live) = self.live.as_ref() {
                let (microphone, speaker) = live.driver.selected_call_devices();
                (
                    live.driver.call_devices().to_vec(),
                    (microphone.map(str::to_owned), speaker.map(str::to_owned)),
                )
            } else {
                (
                    self.demo_call_devices.clone().unwrap_or_default(),
                    self.demo_selected_devices.clone(),
                )
            };
            if no_engine {
                card = card.child(
                    div()
                        .text_xs()
                        .text_color(cx.theme().muted_foreground)
                        .child("No audio - call engine unavailable."),
                );
            } else if devices.is_empty() {
                card = card.child(
                    div()
                        .text_xs()
                        .text_color(cx.theme().muted_foreground)
                        .child("No audio devices found - the engine reported none."),
                );
            } else {
                let mut pickers = div().w_full().flex().flex_col().gap_1();
                for (kind, label, selected) in [
                    (
                        quill::calls::engine::MediaDeviceKind::Microphone,
                        "Microphone",
                        selected.0.as_deref(),
                    ),
                    (
                        quill::calls::engine::MediaDeviceKind::Speaker,
                        "Speaker",
                        selected.1.as_deref(),
                    ),
                ] {
                    pickers =
                        pickers.child(div().text_xs().font_semibold().child(label.to_string()));
                    for device in devices.iter().filter(|device| device.kind == kind) {
                        let device_id = device.id.clone();
                        let chosen = Some(device.id.as_str()) == selected;
                        pickers = pickers.child(
                            Button::new(format!("call-device-{}-{}", label, device.id))
                                .label(format!(
                                    "{} {}",
                                    if chosen { "●" } else { "○" },
                                    device.name
                                ))
                                .ghost()
                                .on_click(cx.listener(move |this, _, _, cx| {
                                    this.select_call_device(kind, &device_id, cx);
                                })),
                        );
                    }
                }
                // Phase C2e: camera picker, video calls only. When the
                // engine reported other devices but no camera, the row
                // says so honestly instead of vanishing.
                if call.is_video {
                    let camera_selected: Option<&str> = if let Some(live) = self.live.as_ref() {
                        live.driver.selected_call_camera()
                    } else {
                        self.demo_selected_camera.as_deref()
                    };
                    pickers =
                        pickers.child(div().text_xs().font_semibold().child("Camera".to_string()));
                    let mut any_camera = false;
                    for device in devices.iter().filter(|device| {
                        device.kind == quill::calls::engine::MediaDeviceKind::Camera
                    }) {
                        any_camera = true;
                        let device_id = device.id.clone();
                        let chosen = Some(device.id.as_str()) == camera_selected;
                        pickers = pickers.child(
                            Button::new(format!("call-device-Camera-{}", device.id))
                                .label(format!(
                                    "{} {}",
                                    if chosen { "●" } else { "○" },
                                    device.name
                                ))
                                .ghost()
                                .on_click(cx.listener(move |this, _, _, cx| {
                                    this.select_call_device(
                                        quill::calls::engine::MediaDeviceKind::Camera,
                                        &device_id,
                                        cx,
                                    );
                                })),
                        );
                    }
                    if !any_camera {
                        pickers = pickers.child(
                            div()
                                .text_xs()
                                .text_color(cx.theme().muted_foreground)
                                .child("No camera found."),
                        );
                    }
                }
                card = card.child(pickers);
            }
        }
        let mut buttons = div().flex().gap_2();
        match &call.state {
            CallState::Pending { .. } if !call.is_outgoing => {
                buttons = buttons
                    .child(
                        Button::new("call-accept")
                            .label("Accept")
                            .success()
                            .on_click(cx.listener(|this, _, _, cx| {
                                this.accept_incoming_call(cx);
                            })),
                    )
                    .child(
                        Button::new("call-decline")
                            .label("Decline")
                            .danger()
                            .on_click(cx.listener(|this, _, _, cx| {
                                this.hang_up_call(cx);
                            })),
                    );
            }
            CallState::Pending { .. } | CallState::ExchangingKeys => {
                buttons =
                    buttons.child(Button::new("call-cancel").label("Cancel").ghost().on_click(
                        cx.listener(|this, _, _, cx| {
                            this.hang_up_call(cx);
                        }),
                    ));
            }
            CallState::Ready | CallState::Unknown(_) => {
                // Phase C1b: mute toggle — local-only state, no-op
                // without media transport (the card says so above).
                buttons = buttons.child(
                    Button::new("call-mute")
                        .label(if call.muted { "Unmute" } else { "Mute" })
                        .ghost()
                        .on_click(cx.listener(|this, _, _, cx| {
                            this.toggle_call_mute(cx);
                        })),
                );
                // Phase C2e: camera toggle for video calls — shown only
                // when video can actually run (live: driver ready; demo:
                // fixtures). Otherwise an honest "No camera available".
                if call.is_video {
                    let video_ready = self
                        .live
                        .as_ref()
                        .is_some_and(|live| live.driver.call_video_ready())
                        || self.live.is_none();
                    if video_ready {
                        buttons = buttons.child(
                            Button::new("call-camera")
                                .label(if call.camera_on {
                                    "Camera off"
                                } else {
                                    "Camera on"
                                })
                                .ghost()
                                .on_click(cx.listener(|this, _, _, cx| {
                                    this.toggle_call_camera(cx);
                                })),
                        );
                    } else {
                        buttons = buttons.child(
                            div()
                                .text_xs()
                                .text_color(cx.theme().muted_foreground)
                                .child("No camera available"),
                        );
                    }
                }
                buttons = buttons.child(
                    Button::new("call-hangup")
                        .label("Hang up")
                        .danger()
                        .on_click(cx.listener(|this, _, _, cx| {
                            this.hang_up_call(cx);
                        })),
                );
            }
            CallState::HangingUp | CallState::Discarded { .. } | CallState::Error { .. } => {}
        }
        card.child(buttons)
    }

    /// Phase C1: the call-end screen — reason line, duration, and the
    /// optional 1–5 rating card (`callStateDiscarded.need_rating`,
    /// schema 1.8.67, line 7078). Phase C1 shows the
    /// `need_debug_information` upload; phase C2i adds the `need_log`
    /// (`sendCallLog`) upload and the rating-detail editor (problems +
    /// comment).
    fn call_summary_card(
        &self,
        card: Stateful<Div>,
        summary: &CallSummary,
        cx: &mut Context<Self>,
    ) -> Stateful<Div> {
        let name = self.call_peer_name(summary.user_id);
        let mut card = card
            .child(initials_avatar(&name, 72.))
            .child(div().text_lg().font_semibold().child(name))
            .child(div().text_sm().child(summary.end_line.clone()));
        if summary.duration_secs > 0 {
            card = card.child(
                div()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child(format!(
                        "Connected for {}",
                        Self::call_clock(summary.duration_secs.max(0) as u64)
                    )),
            );
        }
        card = card.child(
            div()
                .text_xs()
                .text_color(cx.theme().muted_foreground)
                .child(if summary.had_audio {
                    "Audio was connected for this call."
                } else {
                    "No audio was carried."
                }),
        );
        if summary.need_debug_information && !summary.debug_information_sent {
            card = card.child(
                Button::new("call-upload-diagnostics")
                    .label("Upload diagnostics")
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.upload_call_diagnostics(cx);
                    })),
            );
        }
        if summary.debug_information_sent {
            card = card.child(
                div()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child("Diagnostics sent."),
            );
        }
        if let Some(error) = &summary.debug_information_error {
            card = card.child(
                div()
                    .text_xs()
                    .text_color(rgb(0xe17076))
                    .child(error.clone()),
            );
        }
        if summary.need_log && !summary.log_sent {
            card = card.child(
                Button::new("call-upload-log")
                    .label("Upload call log")
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.upload_call_log(cx);
                    })),
            );
        }
        if summary.log_sent {
            card = card.child(
                div()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child("Call log sent."),
            );
        }
        if let Some(error) = &summary.log_error {
            card = card.child(
                div()
                    .text_xs()
                    .text_color(rgb(0xe17076))
                    .child(error.clone()),
            );
        }
        if summary.need_rating && !summary.rating_sent {
            card = card.child(div().text_sm().child("How was the call quality?"));
            match &self.rating_detail {
                // Phase C2i: star tap opens the detail editor (problems
                // + comment) — nothing is sent until Submit.
                None => {
                    let mut stars = div().flex().gap_2();
                    for star in 1..=5 {
                        stars = stars.child(
                            Button::new(format!("call-rate-{star}"))
                                .label(format!("{star} ★"))
                                .on_click(cx.listener(move |this, _, window, cx| {
                                    this.open_rating_detail(star, window, cx);
                                })),
                        );
                    }
                    card = card.child(stars).child(
                        Button::new("call-rate-skip")
                            .label("Skip")
                            .ghost()
                            .on_click(cx.listener(|this, _, _, cx| {
                                this.dismiss_call_summary(cx);
                            })),
                    );
                }
                Some(detail) => {
                    card = card.child(self.rating_detail_editor(detail, cx));
                }
            }
        } else {
            if summary.rating_sent {
                card = card.child(
                    div()
                        .text_xs()
                        .text_color(cx.theme().muted_foreground)
                        .child("Thanks for your feedback"),
                );
            }
            card = card.child(Button::new("call-summary-close").label("Close").on_click(
                cx.listener(|this, _, _, cx| {
                    this.dismiss_call_summary(cx);
                }),
            ));
        }
        // Phase C2i: call again from the call-end card (honours the
        // confirm-before-calling pref).
        {
            let user_id = summary.user_id;
            let was_video = summary.is_video;
            card = card.child(
                Button::new("call-summary-again")
                    .label("Call again")
                    .on_click(cx.listener(move |this, _, _, cx| {
                        this.dismiss_call_summary(cx);
                        this.call_again(user_id, was_video, cx);
                    })),
            );
        }
        card
    }

    /// Phase C2i: the rating-detail editor — re-pickable stars, the
    /// nine `CallProblem` chips (schema 1.8.67 `:7253`-`:7277`), and
    /// an optional comment. Nothing leaves the machine until Submit.
    fn rating_detail_editor(&self, detail: &RatingDetail, cx: &mut Context<Self>) -> AnyElement {
        let mut stars = div().flex().gap_2();
        for star in 1..=5 {
            stars = stars.child(
                Button::new(format!("call-rate-pick-{star}"))
                    .label(format!("{star} ★"))
                    .on_click(cx.listener(move |this, _, _, cx| {
                        if let Some(detail) = this.rating_detail.as_mut() {
                            detail.stars = star;
                        }
                        cx.notify();
                    })),
            );
        }
        let mut chips = div().flex().flex_wrap().gap_1();
        for (index, (_, description)) in CALL_PROBLEMS.iter().enumerate() {
            let selected = detail.problems[index];
            chips = chips.child(
                Button::new(format!("call-problem-{index}"))
                    .label(format!(
                        "{} {}",
                        if selected { "☑" } else { "☐" },
                        description
                    ))
                    .ghost()
                    .on_click(cx.listener(move |this, _, _, cx| {
                        this.toggle_rating_problem(index, cx);
                    })),
            );
        }
        div()
            .flex()
            .flex_col()
            .gap_2()
            .child(stars)
            .child(
                div()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child("What went wrong? (optional)"),
            )
            .child(chips)
            .child(self.rating_comment_input.clone())
            .child(
                div()
                    .flex()
                    .gap_2()
                    .child(
                        Button::new("call-rate-submit")
                            .label("Submit rating")
                            .on_click(cx.listener(|this, _, _, cx| {
                                this.submit_call_rating(cx);
                            })),
                    )
                    .child(
                        Button::new("call-rate-skip")
                            .label("Skip")
                            .ghost()
                            .on_click(cx.listener(|this, _, _, cx| {
                                this.dismiss_call_summary(cx);
                            })),
                    ),
            )
            .into_any_element()
    }

    // ── Phase C3a: group-call (voice chat) signaling UI ──

    /// Phase C3a: group-call overlay — the voice-chat card above
    /// everything else. **Signaling only**: no audio/video transport
    /// exists yet (Phase C2), so the card always carries the honest
    /// no-transport note.
    fn group_call_overlay(&mut self, cx: &mut Context<Self>) -> Option<AnyElement> {
        let call = self.session()?.active_group_call.clone()?;
        Some(self.group_call_card(&call, cx).into_any_element())
    }

    /// Phase C2h: the `createVideoChat` start/schedule dialog —
    /// title plus relative schedule presets.
    fn group_call_start_overlay(&self, cx: &mut Context<Self>) -> Option<AnyElement> {
        let dialog = self.group_call_start_dialog.as_ref()?;
        let selected = dialog.schedule_offset;
        let mut presets = div().flex().flex_wrap().gap_2();
        for (offset, label) in GROUP_CALL_SCHEDULE_PRESETS {
            let active = offset == selected;
            presets = presets.child(
                Button::new(format!("group-call-start-preset-{offset}"))
                    .label(label)
                    .when(!active, |b| b.ghost())
                    .on_click(cx.listener(move |this, _, _, cx| {
                        this.set_group_call_start_schedule(offset, cx);
                    })),
            );
        }
        Some(
            div()
                .id("group-call-start-dialog")
                .absolute()
                .inset_0()
                .flex()
                .items_center()
                .justify_center()
                .child(
                    div()
                        .w(px(420.))
                        .flex()
                        .flex_col()
                        .gap_3()
                        .p_4()
                        .rounded_lg()
                        .border_1()
                        .border_color(cx.theme().border)
                        .bg(cx.theme().sidebar)
                        .child(div().text_sm().font_semibold().child("Start voice chat"))
                        .child(Textarea::new(&dialog.title_input).h(px(40.)))
                        .child(
                            div()
                                .text_xs()
                                .text_color(cx.theme().muted_foreground)
                                .child("When should it start?"),
                        )
                        .child(presets)
                        .child(
                            div()
                                .flex()
                                .gap_2()
                                .child(
                                    Button::new("group-call-start-confirm")
                                        .label(if selected == 0 {
                                            "Start now"
                                        } else {
                                            "Schedule"
                                        })
                                        .on_click(cx.listener(|this, _, _, cx| {
                                            this.confirm_group_call_start(cx);
                                        })),
                                )
                                .child(
                                    Button::new("group-call-start-cancel")
                                        .label("Cancel")
                                        .ghost()
                                        .on_click(cx.listener(|this, _, _, cx| {
                                            this.close_group_call_start_dialog(cx);
                                        })),
                                ),
                        ),
                )
                .into_any_element(),
        )
    }

    fn group_call_participant_name(&self, sender: &MessageSender) -> String {
        match sender {
            MessageSender::User { user_id } => self
                .session()
                .and_then(|s| s.user(*user_id))
                .map(|u| u.display_name())
                .unwrap_or_else(|| format!("User {user_id}")),
            MessageSender::Chat { chat_id } => self
                .session()
                .and_then(|s| s.chats.get(chat_id))
                .map(|c| c.title.clone())
                .unwrap_or_else(|| format!("Chat {chat_id}")),
        }
    }

    fn group_call_participant_tile(
        &mut self,
        call: &ActiveGroupCall,
        participant: &ParsedGroupCallParticipant,
        cx: &mut Context<Self>,
    ) -> impl IntoElement {
        let name = self.group_call_participant_name(&participant.participant_id);
        let mut badges: Vec<String> = Vec::new();
        if participant.is_speaking {
            badges.push("🔊 speaking".to_string());
        }
        if participant.is_muted_for_all_users || participant.is_muted_for_current_user {
            badges.push("🔇 muted".to_string());
        }
        if participant.is_hand_raised {
            badges.push("✋ hand raised".to_string());
        }
        if participant.video_enabled {
            badges.push("📹 video".to_string());
        }
        // `groupCallParticipantVideoInfo.is_paused` (schema 1.8.67,
        // :7163): TDLib clears the flag when new frames arrive, so the
        // badge only needs to read it.
        if participant
            .video_info
            .as_ref()
            .is_some_and(|info| info.is_paused)
        {
            badges.push("⏸ paused".to_string());
        }
        if participant.screen_sharing_enabled {
            badges.push("🖥 sharing".to_string());
        }
        // Phase C2g: live video tile when a frame is retained for this
        // participant (camera, or screen share preferred when sharing);
        // the avatar placeholder stays for everyone else.
        let video_or_avatar: AnyElement = match self.group_participant_frame(call.id, participant) {
            Some((user_id, screen, frame)) => {
                match self.cached_group_video_image(call.id, user_id, screen, &frame) {
                    Some(image) => img(ImageSource::from(image))
                        .w_full()
                        .h(px(90.))
                        .object_fit(ObjectFit::Contain)
                        .into_any_element(),
                    None => div().child(initials_avatar(&name, 56.)).into_any_element(),
                }
            }
            None => div().child(initials_avatar(&name, 56.)).into_any_element(),
        };
        let mut tile = div()
            .w(px(124.))
            .flex()
            .flex_col()
            .items_center()
            .gap_1()
            .p_2()
            .rounded_md()
            .border_1()
            .border_color(cx.theme().border)
            .bg(cx.theme().background)
            .child(
                div()
                    .w_full()
                    .flex()
                    .items_center()
                    .justify_center()
                    .rounded_md()
                    .bg(rgb(0x161616))
                    .child(video_or_avatar),
            )
            .child(
                div()
                    .text_xs()
                    .font_semibold()
                    .child(if participant.is_current_user {
                        format!("{name} (you)")
                    } else {
                        name
                    }),
            );
        if !badges.is_empty() {
            tile = tile.child(
                div()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child(badges.join(" · ")),
            );
        }
        // Phase C3a: admin participant controls, gated on the actual
        // TDLib flags — mute for all, lower a raised hand. One wrapped
        // row keeps tiles short (the grid scrolls past 320px).
        let sender = participant.participant_id.clone();
        if call.can_be_managed && !participant.is_current_user {
            let mut admin_row = div().flex().flex_wrap().justify_center().gap_1();
            let mut admin_count = 0;
            if participant.is_hand_raised {
                let sender2 = sender.clone();
                admin_row = admin_row.child(
                    Button::new(format!("gc-lower-hand-{sender2:?}"))
                        .label("Lower hand")
                        .ghost()
                        .on_click(cx.listener(move |this, _, _, cx| {
                            this.toggle_group_call_participant_hand(sender2.clone(), false, cx);
                        })),
                );
                admin_count += 1;
            }
            if participant.can_be_muted_for_all_users || participant.can_be_unmuted_for_all_users {
                let mute = !participant.is_muted_for_all_users;
                let sender2 = sender.clone();
                admin_row = admin_row.child(
                    Button::new(format!("gc-mute-participant-{sender2:?}"))
                        .label(if mute { "Mute" } else { "Unmute" })
                        .ghost()
                        .on_click(cx.listener(move |this, _, _, cx| {
                            this.toggle_group_call_participant_muted(sender2.clone(), mute, cx);
                        })),
                );
                admin_count += 1;
            }
            if admin_count > 0 {
                tile = tile.child(admin_row);
            }
        }
        // Phase C2f: ban (`banGroupCallParticipants` takes user ids
        // only — `messageSenderChat` participants have no button).
        // Owner-gated: schema requires `groupCall.is_owned`
        // (`can_be_managed` is "for video chats and live stories
        // only"), so this is its own block, not part of the admin row.
        if call.is_owned && !participant.is_current_user {
            if let MessageSender::User { user_id } = participant.participant_id {
                tile = tile.child(
                    div().flex().flex_wrap().justify_center().gap_1().child(
                        Button::new(format!("gc-ban-participant-{user_id}"))
                            .label("Ban")
                            .ghost()
                            .on_click(cx.listener(move |this, _, _, cx| {
                                this.ban_group_call_participant(user_id, cx);
                            })),
                    ),
                );
            }
        }
        // Phase C2f: per-participant volume stepper
        // (`setGroupCallParticipantVolumeLevel`; 1-20000 in hundreds
        // of percents, stepped ±10%). Local playback volume — no
        // admin right needed; self has no button.
        if !participant.is_current_user {
            let sender_down = sender;
            let sender_up = sender;
            tile = tile.child(
                div()
                    .flex()
                    .items_center()
                    .gap_1()
                    .child(
                        Button::new(format!("gc-vol-down-{sender_down:?}"))
                            .label("−")
                            .ghost()
                            .on_click(cx.listener(move |this, _, _, cx| {
                                this.adjust_group_call_participant_volume(sender_down, -1000, cx);
                            })),
                    )
                    .child(
                        div()
                            .text_xs()
                            .text_color(cx.theme().muted_foreground)
                            .child(format!("🔊 {}%", participant.volume_level / 100)),
                    )
                    .child(
                        Button::new(format!("gc-vol-up-{sender_up:?}"))
                            .label("+")
                            .ghost()
                            .on_click(cx.listener(move |this, _, _, cx| {
                                this.adjust_group_call_participant_volume(sender_up, 1000, cx);
                            })),
                    ),
            );
        }
        tile
    }

    fn group_call_card(
        &mut self,
        call: &ActiveGroupCall,
        cx: &mut Context<Self>,
    ) -> impl IntoElement {
        let mut card = div()
            .id("group-call-card")
            .flex()
            .flex_col()
            .items_center()
            .gap_3()
            .p_6()
            .w(px(600.))
            .max_h(px(720.))
            .overflow_y_scroll()
            .rounded_lg()
            .border_1()
            .border_color(cx.theme().border)
            .bg(cx.theme().sidebar);

        // Title + kind line.
        card = card
            .child(
                div()
                    .text_lg()
                    .font_semibold()
                    .child(if call.title.is_empty() {
                        "Voice chat".to_string()
                    } else {
                        call.title.clone()
                    }),
            )
            .child(
                div()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child(format!(
                        "{} participant{}",
                        call.participant_count,
                        if call.participant_count == 1 { "" } else { "s" }
                    )),
            );

        // Phase C2f: group-call request failures (`group_call_error`)
        // were write-only before — surface them on the overlay with a
        // dismiss, so invite/ban/volume/rejoin failures are honest.
        if let Some(error) = self.session().and_then(|s| s.group_call_error.clone()) {
            card = card.child(
                div()
                    .w_full()
                    .flex()
                    .items_center()
                    .justify_between()
                    .gap_2()
                    .p_2()
                    .rounded_md()
                    .bg(rgb(0x3a1414))
                    .child(div().text_sm().text_color(rgb(0xff8a8a)).child(error))
                    .child(
                        Button::new("group-call-error-dismiss")
                            .label("Dismiss")
                            .ghost()
                            .on_click(cx.listener(|this, _, _, cx| {
                                this.dismiss_group_call_error(cx);
                            })),
                    ),
            );
        }

        if call.scheduled_start_date > 0 && !call.is_joined {
            // Phase C2h: scheduled (not yet started) video chat —
            // admins (`can_be_managed`) get a Start-now button
            // (`startScheduledVideoChat`, schema 1.8.67 :14277); Join
            // appears once TDLib activates the call.
            card = card.child(
                div()
                    .flex()
                    .flex_col()
                    .items_center()
                    .gap_2()
                    .p_4()
                    .rounded_md()
                    .border_1()
                    .border_color(cx.theme().border)
                    .child(
                        div()
                            .text_sm()
                            .font_semibold()
                            .child("Scheduled voice chat"),
                    )
                    .child(
                        div()
                            .text_xs()
                            .text_color(cx.theme().muted_foreground)
                            .child(format!(
                                "Starts {}",
                                format_starts_in(call.scheduled_start_date as i64)
                            )),
                    )
                    .when(call.can_be_managed, |this| {
                        this.child(
                            Button::new("group-call-start-now")
                                .label("Start now")
                                .on_click(cx.listener(|this, _, _, cx| {
                                    this.start_scheduled_video_chat(cx);
                                })),
                        )
                    })
                    // "Notify me when it starts":
                    // `toggleVideoChatEnabledStartNotification` (schema
                    // 1.8.67, :14282). Any viewer can set it — no admin
                    // right required. The driver sends the flipped flag;
                    // the new value arrives back as `updateGroupCall`.
                    .child(
                        Button::new("group-call-start-notify-toggle")
                            .label(if call.enabled_start_notification {
                                "🔔 Notifying — tap to turn off"
                            } else {
                                "🔕 Notify me when it starts"
                            })
                            .ghost()
                            .on_click(cx.listener(|this, _, _, cx| {
                                this.toggle_video_chat_start_notification(cx);
                            })),
                    ),
            );
        } else if !call.is_joined {
            card = card.child(self.group_call_join_prompt(call, cx));
        } else {
            card = self.group_call_joined_card(card, call, cx);
        }

        // Backdrop, like the 1:1 call overlay.
        div()
            .id("group-call-overlay")
            .absolute()
            .top_0()
            .left_0()
            .right_0()
            .bottom_0()
            .flex()
            .items_center()
            .justify_center()
            .child(
                div()
                    .id("group-call-backdrop")
                    .absolute()
                    .top_0()
                    .left_0()
                    .right_0()
                    .bottom_0()
                    .bg(rgba(0x000000e6)),
            )
            .child(card)
    }

    /// Phase C3a: the joined voice-chat card body — reconnect banner,
    /// verification emojis, participant grid, self/admin controls.
    fn group_call_joined_card(
        &mut self,
        mut card: Stateful<Div>,
        call: &ActiveGroupCall,
        cx: &mut Context<Self>,
    ) -> Stateful<Div> {
        // Reconnect banner (`need_rejoin`): the call dropped and must be
        // rejoined. Live driver re-issues `joinVideoChat`.
        if call.reconnecting {
            card = card
                .child(
                    div().w_full().p_2().rounded_md().bg(rgb(0x3a2a10)).child(
                        div()
                            .text_sm()
                            .font_semibold()
                            .text_color(rgb(0xffc861))
                            .child("Connection lost — the voice chat needs to be rejoined."),
                    ),
                )
                .child(
                    Button::new("group-call-rejoin")
                        .label("Rejoin")
                        .on_click(cx.listener(|this, _, _, cx| {
                            this.rejoin_active_group_call(cx);
                        })),
                );
        }

        // E2E verification emojis, straight from the update.
        if let Some(verification) = &call.verification {
            card = card.child(
                div()
                    .flex()
                    .items_center()
                    .gap_2()
                    .child(
                        div()
                            .text_xs()
                            .text_color(cx.theme().muted_foreground)
                            .child("End-to-end verification:"),
                    )
                    .child(div().text_2xl().child(verification.emojis.join(" "))),
            );
        }

        // Participant grid. Scrolls internally so the self/admin
        // controls below never clip when the roster is tall.
        // `flex_shrink_0`: inside the scrolling card the grid must keep
        // its own height instead of collapsing.
        let mut grid = div()
            .id("group-call-participants")
            .w_full()
            .flex()
            .flex_wrap()
            .justify_center()
            .gap_2()
            .max_h(px(320.))
            .flex_shrink_0()
            .overflow_y_scroll();
        for participant in &call.participants {
            grid = grid.child(self.group_call_participant_tile(call, participant, cx));
        }
        card = card.child(grid);
        if !call.loaded_all_participants && call.participants.len() >= 100 {
            card = card.child(
                Button::new("group-call-load-more")
                    .label("Load more participants")
                    .ghost()
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.load_more_group_call_participants(cx);
                    })),
            );
        }

        // The always-visible transport state note — honest about the
        // native group transport (Phase C2g connects it on the
        // `joinVideoChat` answer). The slice carries no audio
        // (microphone/speaker sources are null), so the copy says
        // video, not voice.
        let transport_note = if call.transport_ready {
            "Video connected."
        } else if call.transport_error.is_some() {
            "Video failed to connect."
        } else if self
            .live
            .as_ref()
            .is_some_and(|live| live.driver.group_call_engine_available())
        {
            "Connecting…"
        } else {
            "Video unavailable — call engine unavailable."
        };
        card = card.child(
            div()
                .text_xs()
                .text_color(cx.theme().muted_foreground)
                .child(transport_note),
        );

        // Self controls. Self mute is local-only: TDLib group calls
        // have no "mute self" outside the join parameters, so the flag
        // rides on the next join — the label says so.
        let self_muted = call.is_muted_self;
        let self_video = call.is_my_video_enabled;
        let self_hand = call
            .participants
            .iter()
            .any(|p| p.is_current_user && p.is_hand_raised);
        let mut controls = div().flex().gap_2().flex_wrap().justify_center();
        controls = controls.child(
            Button::new("group-call-mute")
                .label(if self_muted { "Unmute" } else { "Mute" })
                .on_click(cx.listener(|this, _, _, cx| {
                    this.toggle_group_call_self_mute(cx);
                })),
        );
        controls = controls.child(
            Button::new("group-call-hand")
                .label(if self_hand {
                    "Lower hand"
                } else {
                    "Raise hand"
                })
                .on_click(cx.listener({
                    let raise = !self_hand;
                    move |this, _, _, cx| {
                        this.toggle_group_call_self_hand(raise, cx);
                    }
                })),
        );
        if call.can_enable_video {
            controls = controls.child(
                Button::new("group-call-video")
                    .label(if self_video {
                        "Stop video"
                    } else {
                        "Start video"
                    })
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.toggle_group_call_video(cx);
                    })),
            );
        }
        // Phase C2g: screen sharing toggle, gated on an enumerated
        // screen-capture source — without one the honest note shows
        // instead of a dead button.
        let screen_source = self
            .live
            .as_ref()
            .is_some_and(|live| live.driver.group_call_screen_source_available());
        let sharing = call.screen_sharing || call.screen_share_pending;
        if screen_source {
            controls = controls.child(
                Button::new("group-call-share-screen")
                    .label(if sharing {
                        "Stop sharing"
                    } else {
                        "Share screen"
                    })
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.toggle_group_call_screen_share(cx);
                    })),
            );
        } else {
            controls = controls.child(
                div()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child("No screen source available."),
            );
        }
        controls = controls.child(Button::new("group-call-leave").label("Leave").on_click(
            cx.listener(|this, _, _, cx| {
                this.leave_active_group_call(cx);
            }),
        ));
        // Phase C2f: invite participants (`inviteGroupCallParticipant`).
        controls = controls.child(
            Button::new("group-call-invite-participant")
                .label("Invite")
                .on_click(cx.listener(|this, _, _, cx| {
                    this.open_group_call_invite(cx);
                })),
        );
        card = card.child(controls);
        card = card.child(
            div()
                .text_xs()
                .text_color(cx.theme().muted_foreground)
                .child("Mute is local-only: it applies on your next join."),
        );

        // Admin controls, gated on the actual TDLib flags.
        if call.can_be_managed || call.can_toggle_mute_new_participants {
            let mut admin = div().flex().gap_2().flex_wrap().justify_center();
            if call.can_be_managed {
                admin = admin.child(
                    Button::new("group-call-invite")
                        .label("Get invite link")
                        .ghost()
                        .on_click(cx.listener(|this, _, _, cx| {
                            this.fetch_group_call_invite_link(cx);
                        })),
                );
                admin = admin.child(
                    Button::new("group-call-rename")
                        .label("Rename")
                        .ghost()
                        .on_click(cx.listener(move |this, _, window, cx| {
                            this.open_group_call_title_dialog(window, cx);
                        })),
                );
                // Phase C2h: recording toggle (`startGroupCallRecording`
                // / `endGroupCallRecording`) — video chats only.
                if call.is_video_chat {
                    let recording = call.record_duration > 0;
                    admin = admin.child(
                        Button::new("group-call-record")
                            .label(if recording {
                                "■ Stop recording"
                            } else {
                                "● Record"
                            })
                            .ghost()
                            .on_click(cx.listener(|this, _, _, cx| {
                                this.toggle_group_call_recording(cx);
                            })),
                    );
                }
                // Phase C2h: RTMP stream key (`getVideoChatRtmpUrl`).
                admin = admin.child(
                    Button::new("group-call-rtmp")
                        .label("Stream key")
                        .ghost()
                        .on_click(cx.listener(|this, _, _, cx| {
                            this.fetch_video_chat_rtmp_url(cx);
                        })),
                );
                admin = admin.child(
                    Button::new("group-call-end")
                        .label("End voice chat")
                        .ghost()
                        .on_click(cx.listener(|this, _, _, cx| {
                            this.end_active_group_call(cx);
                        })),
                );
            }
            // Phase C2h: in-call chat on/off
            // (`toggleGroupCallAreMessagesAllowed`).
            if call.can_toggle_are_messages_allowed {
                let label = if call.are_messages_allowed {
                    "Chat: on"
                } else {
                    "Chat: off"
                };
                admin = admin.child(
                    Button::new("group-call-chat-toggle")
                        .label(label)
                        .ghost()
                        .on_click(cx.listener(|this, _, _, cx| {
                            this.toggle_group_call_chat(cx);
                        })),
                );
            }
            if call.can_toggle_mute_new_participants {
                let label = if call.mute_new_participants {
                    "Mute new: on"
                } else {
                    "Mute new: off"
                };
                admin = admin.child(
                    Button::new("group-call-mute-new")
                        .label(label)
                        .ghost()
                        .on_click(cx.listener(|this, _, _, cx| {
                            this.toggle_video_chat_mute_new(cx);
                        })),
                );
            }
            card = card.child(admin);
        }

        // Phase C2h: recording indicator — `record_duration` from
        // `updateGroupCall` (0 = not recording).
        if call.record_duration > 0 {
            let label = if call.is_video_recorded {
                "video"
            } else {
                "audio"
            };
            card = card.child(
                div()
                    .text_sm()
                    .font_semibold()
                    .text_color(rgb(0xff6b6b))
                    .child(format!(
                        "● Recording ({}) {}",
                        label,
                        format_record_duration(call.record_duration)
                    )),
            );
        }

        // Invite link once fetched — show, copy, revoke.
        if let Some(link) = &call.invite_link {
            let link = link.clone();
            card = card.child(
                div()
                    .w_full()
                    .flex()
                    .items_center()
                    .gap_2()
                    .child(
                        div()
                            .flex_1()
                            .text_xs()
                            .text_color(cx.theme().muted_foreground)
                            .child(format!("Invite link: {link}")),
                    )
                    .child(
                        Button::new("group-call-invite-copy")
                            .label("Copy")
                            .ghost()
                            .on_click(cx.listener(move |this, _, _, cx| {
                                this.copy_video_chat_invite_link(&link, cx);
                            })),
                    )
                    .when(call.can_be_managed, |this| {
                        this.child(
                            Button::new("group-call-invite-revoke")
                                .label("Revoke")
                                .ghost()
                                .on_click(cx.listener(|this, _, _, cx| {
                                    this.revoke_group_call_invite_link(cx);
                                })),
                        )
                    }),
            );
        }

        // Phase C2h: RTMP URL + stream key once fetched
        // (`getVideoChatRtmpUrl` / `replaceVideoChatRtmpUrl`).
        if let (Some(url), Some(key)) = (&call.rtmp_url, &call.rtmp_stream_key) {
            let url = url.clone();
            let key = key.clone();
            let is_owned = call.is_owned;
            card = card.child(
                div()
                    .w_full()
                    .flex()
                    .flex_col()
                    .gap_1()
                    .p_2()
                    .rounded_md()
                    .border_1()
                    .border_color(cx.theme().border)
                    .child(
                        div()
                            .text_xs()
                            .font_semibold()
                            .child("RTMP stream (admins only)"),
                    )
                    .child(
                        div()
                            .flex()
                            .items_center()
                            .gap_2()
                            .child(
                                div()
                                    .flex_1()
                                    .text_xs()
                                    .text_color(cx.theme().muted_foreground)
                                    .child(format!("URL: {url}")),
                            )
                            .child(
                                Button::new("group-call-rtmp-copy-url")
                                    .label("Copy")
                                    .ghost()
                                    .on_click(cx.listener(move |this, _, _, cx| {
                                        this.copy_rtmp_value("Stream URL", &url, cx);
                                    })),
                            ),
                    )
                    .child(
                        div()
                            .flex()
                            .items_center()
                            .gap_2()
                            .child(
                                div()
                                    .flex_1()
                                    .text_xs()
                                    .text_color(cx.theme().muted_foreground)
                                    .child(format!("Key: {key}")),
                            )
                            .child(
                                Button::new("group-call-rtmp-copy-key")
                                    .label("Copy")
                                    .ghost()
                                    .on_click(cx.listener(move |this, _, _, cx| {
                                        this.copy_rtmp_value("Stream key", &key, cx);
                                    })),
                            ),
                    )
                    .when(is_owned, |this| {
                        this.child(
                            Button::new("group-call-rtmp-regenerate")
                                .label("Regenerate key")
                                .ghost()
                                .on_click(cx.listener(|this, _, _, cx| {
                                    this.replace_video_chat_rtmp_url(cx);
                                })),
                        )
                    }),
            );
        }

        // Title rename dialog.
        if let Some(dialog) = &self.group_call_title_dialog {
            card = card.child(
                div()
                    .w_full()
                    .flex()
                    .flex_col()
                    .gap_2()
                    .p_3()
                    .rounded_md()
                    .border_1()
                    .border_color(cx.theme().border)
                    .child(div().text_sm().font_semibold().child("Rename voice chat"))
                    .child(Textarea::new(&dialog.title_input).h(px(40.)))
                    .child(
                        div()
                            .flex()
                            .gap_2()
                            .child(Button::new("group-call-title-save").label("Save").on_click(
                                cx.listener(|this, _, _, cx| {
                                    this.save_group_call_title(cx);
                                }),
                            ))
                            .child(
                                Button::new("group-call-title-cancel")
                                    .label("Cancel")
                                    .ghost()
                                    .on_click(cx.listener(|this, _, _, cx| {
                                        this.close_group_call_title_dialog(cx);
                                    })),
                            ),
                    ),
            );
        }

        // Phase C2f: invite picker — contacts not already in the call.
        if self.group_call_invite_open {
            card = card.child(self.group_call_invite_panel(call, cx));
        }

        // Phase C2h: in-call chat (`sendGroupCallMessage`) — a simple
        // message list + composer; TDLib has no history getter, so this
        // is the live feed only.
        card = self.group_call_messages_section(card, call, cx);

        card
    }

    /// Phase C2h: in-call group-chat section for the joined call card.
    fn group_call_messages_section(
        &self,
        card: Stateful<Div>,
        call: &ActiveGroupCall,
        cx: &mut Context<Self>,
    ) -> Stateful<Div> {
        if !call.are_messages_allowed
            && call.messages.is_empty()
            && !call.can_toggle_are_messages_allowed
        {
            return card;
        }
        let mut section = div()
            .w_full()
            .flex()
            .flex_col()
            .gap_1()
            .p_2()
            .rounded_md()
            .border_1()
            .border_color(cx.theme().border)
            .child(div().text_xs().font_semibold().child("Chat"));
        if !call.are_messages_allowed {
            section = section.child(
                div()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child("Chat is turned off in this voice chat."),
            );
        }
        if !call.messages.is_empty() {
            let mut list = div()
                .id("group-call-messages")
                .w_full()
                .flex()
                .flex_col()
                .gap_1()
                .max_h(px(180.))
                .overflow_y_scroll();
            for message in call.messages.iter().rev().take(50).rev() {
                let sender = self.group_call_participant_name(&message.sender_id);
                list = list.child(div().text_xs().child(format!("{sender}: {}", message.text)));
            }
            section = section.child(list);
        }
        if call.are_messages_allowed && call.can_send_messages {
            section = section
                .child(Textarea::new(&self.group_call_composer).h(px(40.)))
                .child(
                    Button::new("group-call-message-send")
                        .label("Send")
                        .on_click(cx.listener(|this, _, window, cx| {
                            this.send_group_call_message(window, cx);
                        })),
                );
        } else if call.are_messages_allowed {
            section = section.child(
                div()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child("You can't send messages in this voice chat."),
            );
        }
        card.child(section)
    }

    /// Phase C2f: the invite picker panel — contact rows with Invite
    /// buttons (`inviteGroupCallParticipant`); contacts already in the
    /// call are excluded.
    fn group_call_invite_panel(
        &self,
        call: &ActiveGroupCall,
        cx: &mut Context<Self>,
    ) -> impl IntoElement {
        let in_call: std::collections::HashSet<i64> = call
            .participants
            .iter()
            .filter_map(|p| match p.participant_id {
                MessageSender::User { user_id } => Some(user_id),
                _ => None,
            })
            .collect();
        let mut panel = div()
            .id("group-call-invite-panel")
            .w_full()
            .flex()
            .flex_col()
            .gap_2()
            .p_3()
            .rounded_md()
            .border_1()
            .border_color(cx.theme().border)
            .child(
                div()
                    .flex()
                    .items_center()
                    .justify_between()
                    .child(
                        div()
                            .text_sm()
                            .font_semibold()
                            .child("Invite to voice chat"),
                    )
                    .child(
                        Button::new("group-call-invite-close")
                            .label("Close")
                            .ghost()
                            .on_click(cx.listener(|this, _, _, cx| {
                                this.group_call_invite_open = false;
                                cx.notify();
                            })),
                    ),
            );
        let contacts = self
            .session()
            .and_then(|s| s.contacts.clone())
            .unwrap_or_default();
        let mut rows = div()
            .id("group-call-invite-rows")
            .flex()
            .flex_col()
            .gap_1()
            .max_h(px(200.))
            .overflow_y_scroll();
        let mut shown = 0;
        for user_id in contacts.iter().filter(|id| !in_call.contains(id)).take(30) {
            let name = self
                .session()
                .and_then(|s| s.user(*user_id))
                .map(|u| u.display_name())
                .unwrap_or_else(|| format!("User {user_id}"));
            let uid = *user_id;
            rows = rows.child(
                div()
                    .flex()
                    .items_center()
                    .justify_between()
                    .child(div().text_sm().child(name))
                    .child(
                        Button::new(format!("gc-invite-{uid}"))
                            .label("Invite")
                            .ghost()
                            .on_click(cx.listener(move |this, _, _, cx| {
                                this.invite_group_call_participant(uid, cx);
                            })),
                    ),
            );
            shown += 1;
        }
        if shown == 0 {
            panel = panel.child(
                div()
                    .text_sm()
                    .text_color(cx.theme().muted_foreground)
                    .child("No contacts to invite."),
            );
        } else {
            panel = panel.child(rows);
        }
        panel
    }

    /// Phase C2f: `messageGroupCall` invitation service row (schema
    /// 1.8.67, line 5288). Incoming and pending: Accept / Decline.
    /// Anything else (own sent, missed, active) is a neutral service
    /// notice — TDLib updates refresh the row when the call starts or
    /// ends. Free function: `session_history_row` is not a method.
    fn group_call_invitation_row(
        message: &HistoryMessage,
        is_active: bool,
        was_missed: bool,
        is_video: bool,
        cx: &mut Context<QuillApp>,
    ) -> impl IntoElement {
        let kind = if is_video { "video chat" } else { "voice chat" };
        let mut inner = div().flex().flex_col().items_center().gap_2();
        if !message.is_outgoing && !is_active && !was_missed {
            let chat_id = message.chat_id;
            let message_id = message.id;
            inner = inner
                .child(
                    div()
                        .text_sm()
                        .font_semibold()
                        .child(format!("📞 Incoming {kind} invitation")),
                )
                .child(
                    div()
                        .flex()
                        .gap_2()
                        .child(
                            Button::new(format!("gc-invite-accept-{}", message_id.0))
                                .label("Accept")
                                .on_click(cx.listener(move |this, _, _, cx| {
                                    this.accept_group_call_invitation(chat_id, message_id, cx);
                                })),
                        )
                        .child(
                            Button::new(format!("gc-invite-decline-{}", message_id.0))
                                .label("Decline")
                                .ghost()
                                .on_click(cx.listener(move |this, _, _, cx| {
                                    this.decline_group_call_invitation(chat_id, message_id, cx);
                                })),
                        ),
                );
        } else {
            let state = if was_missed {
                " · missed"
            } else if is_active {
                " · in progress"
            } else {
                ""
            };
            inner = inner.child(
                div()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child(format!("📞 {kind} invitation{state}")),
            );
        }
        div()
            .id(("gc-invitation-row", message.id.0 as u64))
            .flex()
            .justify_center()
            .py_1()
            .child(inner)
    }

    // ── Phase C3a: group-call action handlers ──

    /// Phase C3a: header voice-chat affordance — join a live voice chat,
    /// or start one for a group/channel with none.
    fn start_or_join_video_chat(
        &mut self,
        chat_id: ChatId,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let group_call_id = self
            .session()
            .and_then(|s| s.chats.get(&chat_id.0))
            .and_then(|c| c.video_chat.clone())
            .map(|vc| vc.group_call_id);
        if let Some(group_call_id) = group_call_id {
            if let Some(live) = self.live.as_mut() {
                self.status_note = match live.driver.fetch_group_call(group_call_id) {
                    Ok(_) => "Joining voice chat…".into(),
                    Err(_) => "Couldn't reach the voice chat.".into(),
                };
            } else if let Some(session) = self.demo_session.as_mut() {
                // Screenshot demo: no live TDLib — the fixture already
                // tracks the call; just surface the overlay.
                let _ = session;
                self.status_note = "screenshot demo — voice chat (no audio yet)".into();
            }
        } else if self.live.is_some() {
            // Phase C2h: starting goes through the title/schedule
            // dialog (`createVideoChat` with `start_date`).
            self.open_group_call_start_dialog(chat_id, window, cx);
        } else {
            self.status_note = "Voice chats need a live connection.".into();
        }
        cx.notify();
    }

    /// Phase C3a: join the tracked voice chat.
    fn join_active_group_call(&mut self, cx: &mut Context<Self>) {
        let id = self
            .session()
            .and_then(|s| s.active_group_call.as_ref())
            .map(|c| c.id);
        let Some(id) = id else {
            self.status_note = "No voice chat to join.".into();
            cx.notify();
            return;
        };
        if let Some(live) = self.live.as_mut() {
            self.status_note = match live.driver.join_video_chat(id) {
                Ok(_) => "Joining voice chat…".into(),
                Err(_) => "Couldn't join the voice chat.".into(),
            };
        } else if let Some(session) = self.demo_session.as_mut() {
            if let Some(call) = session.active_group_call.as_mut() {
                call.is_joined = true;
            }
            self.status_note = "screenshot demo — voice chat (no audio yet)".into();
        }
        cx.notify();
    }

    /// Phase C3a: leave the tracked voice chat.
    fn leave_active_group_call(&mut self, cx: &mut Context<Self>) {
        if let Some(live) = self.live.as_mut() {
            let result = live.driver.leave_group_call();
            live.driver.session.leave_group_call_local();
            self.status_note = match result {
                Ok(_) => "Left the voice chat.".into(),
                Err(_) => "Left the voice chat (local).".into(),
            };
        } else if let Some(session) = self.demo_session.as_mut() {
            session.leave_group_call_local();
            self.status_note = "screenshot demo — left the voice chat".into();
        }
        cx.notify();
    }

    /// Phase C3a: rejoin after `need_rejoin`.
    fn rejoin_active_group_call(&mut self, cx: &mut Context<Self>) {
        if let Some(live) = self.live.as_mut() {
            self.status_note = match live.driver.rejoin_group_call(true) {
                Ok(_) => "Rejoining voice chat…".into(),
                Err(_) => "Couldn't rejoin the voice chat.".into(),
            };
        } else if let Some(session) = self.demo_session.as_mut() {
            session.clear_group_call_reconnecting();
            self.status_note = "screenshot demo — rejoined".into();
        }
        cx.notify();
    }

    /// Phase C3a: local-only self mute — no TDLib request (group calls
    /// have no "mute self" outside the join parameters, and no audio
    /// path exists yet). The state rides on the next (re)join.
    fn toggle_group_call_self_mute(&mut self, cx: &mut Context<Self>) {
        if let Some(live) = self.live.as_mut() {
            live.driver.toggle_group_call_self_mute();
            self.status_note = "Muted (local — no audio path yet).".into();
        } else if let Some(session) = self.demo_session.as_mut() {
            let muted = !session
                .active_group_call
                .as_ref()
                .is_some_and(|c| c.is_muted_self);
            session.set_group_call_self_muted(muted);
        }
        cx.notify();
    }

    /// Phase C3a: raise/lower the self hand (live) or flip the demo
    /// fixture's participant flag.
    fn toggle_group_call_self_hand(&mut self, raise: bool, cx: &mut Context<Self>) {
        let me = self
            .session()
            .and_then(|s| s.active_group_call.as_ref())
            .and_then(|c| {
                c.participants
                    .iter()
                    .find(|p| p.is_current_user)
                    .map(|p| p.participant_id.clone())
            });
        let Some(me) = me else {
            cx.notify();
            return;
        };
        if let Some(live) = self.live.as_mut() {
            self.status_note = match live.driver.toggle_group_call_participant_hand(me, raise) {
                Ok(_) => if raise {
                    "Hand raised."
                } else {
                    "Hand lowered."
                }
                .into(),
                Err(_) => "Couldn't change the hand state.".into(),
            };
        } else if let Some(session) = self.demo_session.as_mut() {
            if let Some(call) = session.active_group_call.as_mut() {
                if let Some(p) = call
                    .participants
                    .iter_mut()
                    .find(|p| p.participant_id == me)
                {
                    p.is_hand_raised = raise;
                }
            }
        }
        cx.notify();
    }

