    /// Phase 4.5: fullscreen media viewer overlay. The backdrop is a
    /// separate sibling painted behind the panel (not an ancestor), so a
    /// click on the panel never bubbles into the backdrop's close handler —
    /// "click outside" works regardless of click-bubbling semantics. Esc
    /// closes through `cancel_search`; the header close button is the third
    /// path. Videos show their thumbnail (no in-viewer playback — the
    /// history row's Play path is unchanged); secret/spoiler media never
    /// reach the viewer (filtered in `collect_media_items`).
    /// MED1: fullscreen photo/video viewer overlay. Takes `&mut self` +
    /// `window` so the viewer seek/volume sliders can sync to the clocks
    /// during render.
    fn media_viewer_overlay(
        &mut self,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> impl IntoElement {
        // MED1: keep the viewer seek/volume thumbs on the clocks (the
        // tick has no `&mut Window`, which `SliderState::set_value`
        // needs).
        self.sync_viewer_seek_slider(window, cx);
        self.sync_viewer_volume_slider(window, cx);
        let item = self
            .media_viewer
            .current()
            .cloned()
            .unwrap_or_else(|| MediaViewerItem {
                chat_id: ChatId(0),
                message_id: MessageId(0),
                kind: MediaViewerKind::Photo,
                display_file_ids: Vec::new(),
                download_file_id: FileId(0),
                play_file_id: None,
                duration_secs: None,
                mime_type: None,
                start_timestamp: None,
                caption: String::new(),
                caption_entities: Vec::new(),
                duration_label: None,
            });
        let (position, total) = self.media_viewer.position().unwrap_or((0, 0));
        let files: HashMap<i32, ParsedFile> =
            self.session().map(|s| s.files.clone()).unwrap_or_default();
        let downloading: HashSet<i32> = self
            .session()
            .map(|s| s.downloading.clone())
            .unwrap_or_default();
        let roots = self.media_display_roots();
        let thumb_path = viewer_display_path(&item, &files, &roots);
        // Parity slice 5: when the clip's frames are extracted and decoded,
        // the viewer shows the pre-loaded frame matching the playback clock
        // — real in-viewer video (`ImageSource::Render` resolves
        // synchronously, so the 125 ms tick animates without a per-frame
        // async load). Otherwise it falls back to the thumbnail (or the
        // loading status).
        let frame: Option<Arc<RenderImage>> =
            if item.kind == MediaViewerKind::Video && !self.viewer_video_frames.is_empty() {
                let elapsed = self
                    .viewer_clock
                    .as_ref()
                    .map(|clock| clock.elapsed_secs())
                    .unwrap_or(0.0);
                // Clamp, don't wrap: frames cover (duration − start_timestamp),
                // so the tail of the clock holds the last frame instead of
                // replaying early frames.
                let idx = ((elapsed * self.viewer_video_fps) as usize)
                    .min(self.viewer_video_frames.len() - 1);
                self.viewer_video_frames.get(idx).cloned()
            } else {
                None
            };
        let row_id = item.message_id.0 as u64;
        let downloading_now = item
            .display_file_ids
            .iter()
            .chain(std::iter::once(&item.download_file_id))
            .any(|id| file_is_downloading(*id, &files, &downloading));
        let kind_label = item.kind.label();
        let header_label = if total > 1 {
            format!("{kind_label} {position} of {total}")
        } else {
            kind_label.to_string()
        };
        // MED1: album pin action for the header — only when the item is in
        // an album and the user may pin in this chat (rights-gated, TGX
        // `MessagePinAlbum` semantics: unpins when any member is pinned).
        let album_pin_label: Option<String> =
            self.viewer_album_id(item.message_id).and_then(|album_id| {
                let can_pin = self
                    .session()
                    .and_then(|s| s.chats.get(&item.chat_id.0))
                    .is_some_and(|chat| chat.can_pin_messages());
                if !can_pin {
                    return None;
                }
                let history: Vec<HistoryMessage> = self
                    .session()
                    .and_then(|s| s.histories.get(&item.chat_id.0))
                    .map(|h| h.ordered().into_iter().cloned().collect())
                    .unwrap_or_default();
                let ids = quill::album::album_message_ids(&history, album_id);
                if ids.is_empty() {
                    return None;
                }
                let any_pinned = ids
                    .iter()
                    .any(|id| history.iter().any(|m| m.id == *id && m.is_pinned));
                Some(if any_pinned {
                    "Unpin album".to_string()
                } else {
                    "Pin album".to_string()
                })
            });
        // Parity slice 5: the visual lives in a fixed 720×480 frame; scroll
        // zooms (1×–8×, frame-center kept) and drag pans when zoomed.
        let zoom = self.viewer_zoom;
        let (frame_w, frame_h) = Self::VIEWER_FRAME;
        let (zoom_w, zoom_h) = (frame_w * zoom.zoom, frame_h * zoom.zoom);
        let (pan_x, pan_y) = zoom.pan;
        let content: AnyElement = {
            // Pre-decoded video frame and thumbnail both render through
            // `img`; the frame is an `ImageSource::Render` (synchronous),
            // the thumbnail a path (async-loaded once, then cached). MED1:
            // a rotated photo renders from the eagerly-decoded
            // `viewer_rotated` cache (90°/180°/270° clockwise).
            let rotated: Option<ImageSource> = (item.kind == MediaViewerKind::Photo)
                .then(|| self.viewer_rotated.as_ref())
                .flatten()
                .filter(|(path, turns, _)| {
                    *turns == self.viewer_rotation && Some(path.as_path()) == thumb_path.as_deref()
                })
                .map(|(_, _, image)| ImageSource::from(image.clone()));
            let source: Option<ImageSource> = frame
                .map(ImageSource::from)
                .or(rotated)
                .or_else(|| thumb_path.clone().map(ImageSource::from));
            if let Some(source) = source {
                img(source)
                    .id(("media-viewer-img", row_id))
                    .w(px(zoom_w))
                    .h(px(zoom_h))
                    .object_fit(ObjectFit::Contain)
                    .bg(rgb(0x0d1117))
                    .with_fallback(move || {
                        div()
                            .w(px(zoom_w))
                            .h(px(zoom_h))
                            .bg(rgb(0x0d1117))
                            .flex()
                            .items_center()
                            .justify_center()
                            .text_color(rgb(0xffffff))
                            .child(format!("{kind_label} — could not render"))
                            .into_any_element()
                    })
                    .into_any_element()
            } else {
                // MED3: show the real download percent when known
                // (`updateFile` → `downloaded_size`).
                let progress_pct: Option<i32> = item
                    .display_file_ids
                    .iter()
                    .chain(std::iter::once(&item.download_file_id))
                    .filter_map(|id| files.get(&id.0))
                    .filter_map(|f| f.download_progress())
                    .map(|p| (p * 100.0).round() as i32)
                    .next();
                let downloading_label = match progress_pct {
                    Some(pct) => format!("downloading… {pct}%"),
                    None => "downloading…".to_string(),
                };
                let status = match (&item.duration_label, downloading_now) {
                    (Some(duration), true) => format!("Video · {duration} — {downloading_label}"),
                    (Some(duration), false) => format!("Video · {duration} — not downloaded"),
                    (None, true) => format!("{kind_label} — {downloading_label}"),
                    (None, false) => format!("{kind_label} — not downloaded"),
                };
                div()
                    .id(("media-viewer-loading", row_id))
                    .w(px(zoom_w))
                    .h(px(zoom_h))
                    .bg(rgb(0x0d1117))
                    .flex()
                    .items_center()
                    .justify_center()
                    .child(div().text_sm().text_color(rgb(0xffffff)).child(status))
                    .into_any_element()
            }
        };
        let visual = {
            let view = cx.entity().downgrade();
            let scroll_view = view.clone();
            let down_view = view.clone();
            let move_view = view.clone();
            let up_view = view;
            div()
                .id(("media-viewer-visual", row_id))
                .relative()
                .w(px(frame_w))
                .h(px(frame_h))
                .overflow_hidden()
                .rounded_md()
                .bg(rgb(0x0d1117))
                .child(
                    div()
                        .absolute()
                        .left(px(pan_x))
                        .top(px(pan_y))
                        .w(px(zoom_w))
                        .h(px(zoom_h))
                        .child(content),
                )
                .on_scroll_wheel(move |event, _window, cx| {
                    let dy = match event.delta {
                        ScrollDelta::Pixels(p) => f32::from(p.y),
                        ScrollDelta::Lines(l) => l.y,
                    };
                    if let Some(view) = scroll_view.upgrade() {
                        view.update(cx, |this, cx| this.viewer_zoom_scroll(dy, cx));
                    }
                })
                .on_mouse_down(MouseButton::Left, move |event, _window, cx| {
                    let pos = (f32::from(event.position.x), f32::from(event.position.y));
                    if let Some(view) = down_view.upgrade() {
                        view.update(cx, |this, cx| {
                            this.viewer_drag = Some(pos);
                            cx.notify();
                        });
                    }
                })
                .on_mouse_move(move |event, _window, cx| {
                    let pos = (f32::from(event.position.x), f32::from(event.position.y));
                    if let Some(view) = move_view.upgrade() {
                        view.update(cx, |this, cx| {
                            if let Some((lx, ly)) = this.viewer_drag {
                                this.viewer_pan_drag(pos.0 - lx, pos.1 - ly, cx);
                                this.viewer_drag = Some(pos);
                            }
                        });
                    }
                })
                .on_mouse_up(MouseButton::Left, move |_event, _window, cx| {
                    if let Some(view) = up_view.upgrade() {
                        view.update(cx, |this, cx| {
                            this.viewer_drag = None;
                            cx.notify();
                        });
                    }
                })
                // Double-click resets zoom/pan to fit.
                .on_click(cx.listener(|this, event: &ClickEvent, _, cx| {
                    if event.click_count() >= 2 {
                        this.viewer_reset_zoom(cx);
                    }
                }))
        };
        // Parity slice 5: video transport under the visual. ffplay runs
        // `-nodisp` for audio only (no GPUI video element in this stack);
        // the decoded video frames render in-viewer above. The overlay
        // shows Play/Pause plus elapsed/total, or a download CTA while the
        // clip is not local.
        let video_controls: Option<AnyElement> =
            (item.kind == MediaViewerKind::Video).then(|| {
                let clip_path = self.viewer_clip_path(&item);
                if let Some(_clip) = clip_path {
                    let playing = self
                        .viewer_clock
                        .as_ref()
                        .is_some_and(|clock| clock.is_playing())
                        && self.viewer_video == Some(item.message_id);
                    // MED1: while scrubbing, the label previews the drag
                    // position (the history-row seek pattern).
                    let elapsed = self
                        .viewer_seek_preview_secs
                        .or_else(|| self.viewer_clock.as_ref().map(|clock| clock.elapsed_secs()))
                        .unwrap_or(0.0);
                    let total = item.duration_secs.unwrap_or(0) as f64;
                    let label = format!(
                        "{} / {}",
                        format_voice_duration(elapsed as i32),
                        format_voice_duration(total as i32)
                    );
                    // While ffmpeg extracts frames the thumbnail stays up;
                    // the Play button appears once frames are ready.
                    let extracting = self.viewer_extracting;
                    let speed_label = Self::speed_label(self.playback_speed);
                    let muted = self.playback_volume < 0.01;
                    let volume_pct = (self.playback_volume * 100.0).round() as i32;
                    div()
                        .flex()
                        .items_center()
                        .gap_2()
                        .child(if extracting {
                            div()
                                .text_sm()
                                .text_color(rgb(0xffffff))
                                .child("Loading video…")
                                .into_any_element()
                        } else {
                            Button::new(("media-viewer-play", row_id))
                                .label(if playing { "❚❚ Pause" } else { "▶ Play" })
                                .ghost()
                                .text_color(rgb(0xffffff))
                                .on_click(cx.listener(|this, _, _, cx| {
                                    this.toggle_viewer_video(cx);
                                }))
                                .into_any_element()
                        })
                        .child(div().text_sm().text_color(rgb(0xffffff)).child(label))
                        // MED1: seek slider (created in `begin_viewer_video`).
                        .when_some(self.viewer_seek_slider.clone(), |this, slider| {
                            this.child(
                                div().w(px(180.)).child(
                                    Slider::new(&slider)
                                        .bg(rgb(0x58a6ff))
                                        .text_color(rgb(0xffffff)),
                                ),
                            )
                        })
                        // MED1: playback speed (TGX 0.5x–2x).
                        .child(
                            Button::new(("media-viewer-speed", row_id))
                                .label(speed_label)
                                .ghost()
                                .text_color(rgb(0xffffff))
                                .on_click(cx.listener(|this, _, _, cx| {
                                    this.cycle_playback_speed(cx);
                                })),
                        )
                        // MED1: volume slider + mute toggle.
                        .when_some(self.viewer_volume_slider.clone(), |this, slider| {
                            this.child(
                                div()
                                    .flex()
                                    .items_center()
                                    .gap_1()
                                    .child(
                                        div().w(px(80.)).child(
                                            Slider::new(&slider)
                                                .bg(rgb(0x58a6ff))
                                                .text_color(rgb(0xffffff)),
                                        ),
                                    )
                                    .child(
                                        div()
                                            .text_xs()
                                            .text_color(rgb(0xffffff))
                                            .child(format!("{volume_pct}%")),
                                    ),
                            )
                        })
                        .child(
                            Button::new(("media-viewer-mute", row_id))
                                .label(if muted { "Unmute" } else { "Mute" })
                                .ghost()
                                .text_color(rgb(0xffffff))
                                .on_click(cx.listener(|this, _, _, cx| {
                                    this.toggle_playback_mute(cx);
                                })),
                        )
                        .into_any_element()
                } else {
                    let clip_downloading = item
                        .play_file_id
                        .is_some_and(|id| file_is_downloading(id, &files, &downloading));
                    let play_id = item.play_file_id;
                    div()
                        .flex()
                        .items_center()
                        .gap_2()
                        .child(div().text_sm().text_color(rgb(0xffffff)).child(
                            if clip_downloading {
                                "Video — downloading clip…"
                            } else {
                                "Video — clip not downloaded"
                            },
                        ))
                        .when_some(play_id.filter(|_| !clip_downloading), |this, id| {
                            this.child(
                                Button::new(("media-viewer-download", row_id))
                                    .label("Download")
                                    .ghost()
                                    .text_color(rgb(0xffffff))
                                    .on_click(cx.listener(move |this, _, _, cx| {
                                        this.viewer_pending_play = Some((item.message_id, id));
                                        this.request_media_download(id, None, cx);
                                    })),
                            )
                        })
                        .into_any_element()
                }
            });
        // Parity slice 5: zoom controls share a row with the video
        // transport — − / % / + / Reset, then Play/Pause + elapsed/total.
        let zoom_pct = format!("{}%", (zoom.zoom * 100.0).round() as i32);
        let mut transport = div()
            .flex()
            .items_center()
            .gap_2()
            .child(
                Button::new(("media-viewer-zoom-out", row_id))
                    .label("−")
                    .ghost()
                    .text_color(rgb(0xffffff))
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.viewer_zoom_step(false, cx);
                    })),
            )
            .child(div().text_sm().text_color(rgb(0xffffff)).child(zoom_pct))
            .child(
                Button::new(("media-viewer-zoom-in", row_id))
                    .label("+")
                    .ghost()
                    .text_color(rgb(0xffffff))
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.viewer_zoom_step(true, cx);
                    })),
            )
            .child(
                Button::new(("media-viewer-zoom-reset", row_id))
                    .label("Reset")
                    .ghost()
                    .text_color(rgb(0xffffff))
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.viewer_reset_zoom(cx);
                    })),
            );
        if let Some(controls) = video_controls {
            transport = transport.child(controls);
        }
        let transport = transport.into_any_element();
        let caption: Option<AnyElement> = (!item.caption.is_empty()).then(|| {
            rich_text_line(
                &item.caption,
                &item.caption_entities,
                (item.chat_id.0, row_id),
                true,
                &self.spoiler_revealed,
                cx,
            )
        });
        div()
            .id("media-viewer-overlay")
            .absolute()
            .top_0()
            .left_0()
            .right_0()
            .bottom_0()
            .flex()
            .items_center()
            .justify_center()
            .child(
                div()
                    .id("media-viewer-backdrop")
                    .absolute()
                    .top_0()
                    .left_0()
                    .right_0()
                    .bottom_0()
                    .bg(rgba(0x000000e6))
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.close_media_viewer(cx);
                    })),
            )
            .child(
                div()
                    .id("media-viewer-panel")
                    .flex()
                    .flex_col()
                    .items_center()
                    .gap_2()
                    .p_4()
                    .max_w(px(800.))
                    .max_h_full()
                    .child(
                        div()
                            .flex()
                            .w(px(720.))
                            .items_center()
                            .justify_between()
                            .child(
                                div()
                                    .font_semibold()
                                    .text_color(rgb(0xffffff))
                                    .child(header_label),
                            )
                            .child(
                                div()
                                    .flex()
                                    .items_center()
                                    .gap_1()
                                    // MED1: photo rotation (90° clockwise per tap).
                                    .when(item.kind == MediaViewerKind::Photo, |this| {
                                        this.child(
                                            Button::new(("media-viewer-rotate", row_id))
                                                .label("Rotate")
                                                .ghost()
                                                .text_color(rgb(0xffffff))
                                                .on_click(cx.listener(|this, _, _, cx| {
                                                    this.rotate_viewer_photo(cx);
                                                })),
                                        )
                                    })
                                    // MED1: share via the forward picker.
                                    .child(
                                        Button::new(("media-viewer-share", row_id))
                                            .label("Share")
                                            .ghost()
                                            .text_color(rgb(0xffffff))
                                            .on_click(cx.listener(|this, _, window, cx| {
                                                this.share_viewer_media(window, cx);
                                            })),
                                    )
                                    // MED1: save to the downloads folder.
                                    .child(
                                        Button::new(("media-viewer-save", row_id))
                                            .label("Save")
                                            .ghost()
                                            .text_color(rgb(0xffffff))
                                            .on_click(cx.listener(|this, _, _, cx| {
                                                this.save_viewer_media(cx);
                                            })),
                                    )
                                    // MED1: close and jump to the source message.
                                    .child(
                                        Button::new(("media-viewer-show-in-chat", row_id))
                                            .label("Show in chat")
                                            .ghost()
                                            .text_color(rgb(0xffffff))
                                            .on_click(cx.listener(|this, _, _, cx| {
                                                this.show_viewer_in_chat(cx);
                                            })),
                                    )
                                    // MED1: pin/unpin the album (rights-gated).
                                    .when_some(album_pin_label, |this, label| {
                                        this.child(
                                            Button::new(("media-viewer-pin-album", row_id))
                                                .label(label)
                                                .ghost()
                                                .text_color(rgb(0xffffff))
                                                .on_click(cx.listener(|this, _, _, cx| {
                                                    this.toggle_viewer_album_pin(cx);
                                                })),
                                        )
                                    })
                                    .child(
                                        div()
                                            .id("media-viewer-close")
                                            .cursor_pointer()
                                            .px_2()
                                            .py_1()
                                            .rounded_md()
                                            .text_color(rgb(0xffffff))
                                            .child("Close")
                                            .on_click(cx.listener(|this, _, _, cx| {
                                                this.close_media_viewer(cx);
                                            })),
                                    ),
                            ),
                    )
                    .child(visual)
                    .child(transport)
                    // MED1: honest playback error (unsupported format /
                    // player failure) instead of a silent stall.
                    .when_some(self.playback_error.clone(), |this, err| {
                        this.child(div().text_sm().text_color(rgb(0xff7b72)).child(err))
                    })
                    .when_some(caption, |this, caption| {
                        this.child(div().text_color(rgb(0xffffff)).child(caption))
                    })
                    .child(
                        div()
                            .flex()
                            .gap_2()
                            .child(
                                Button::new("media-viewer-prev")
                                    .label("‹ Prev")
                                    .ghost()
                                    .text_color(rgb(0xffffff))
                                    .disabled(position <= 1)
                                    .on_click(cx.listener(|this, _, _, cx| {
                                        this.step_media_viewer(-1, cx);
                                    })),
                            )
                            .child(
                                Button::new("media-viewer-next")
                                    .label("Next ›")
                                    .ghost()
                                    .text_color(rgb(0xffffff))
                                    .disabled(position >= total)
                                    .on_click(cx.listener(|this, _, _, cx| {
                                        this.step_media_viewer(1, cx);
                                    })),
                            ),
                    ),
            )
    }

    /// Phase 9.2: the viewer's own-story interaction counters
    /// (`storyInteractionInfo`, `schema/td_api.tl:6712`) — only rendered
    /// when TDLib populated them (`story.can_get_interactions`) and at
    /// least one counter is nonzero.
    fn story_viewer_counts(&self) -> Option<String> {
        let story = self.current_story()?;
        if !story.can_get_interactions {
            return None;
        }
        let info = story.interaction_info.filter(|info| info.any_nonzero())?;
        let mut parts = Vec::new();
        if info.view_count > 0 {
            parts.push(format!("👁 {}", info.view_count));
        }
        if info.reaction_count > 0 {
            parts.push(format!("❤️ {}", info.reaction_count));
        }
        if info.forward_count > 0 {
            parts.push(format!("↩ {}", info.forward_count));
        }
        Some(parts.join(" · "))
    }

    /// Phase 9.2: the emoji picker popover fed by `getStoryAvailableReactions`
    /// (`availableReactions`, `schema/td_api.tl:13802`). One tap sets the
    /// reaction via `setStoryReaction` (`schema/td_api.tl:13809`).
    fn story_reaction_picker(&self, cx: &mut Context<Self>) -> AnyElement {
        let reactions = self
            .session()
            .and_then(|session| session.story_available_reactions.clone())
            .unwrap_or_default();
        let mut picker = div()
            .id("story-reaction-picker")
            .flex()
            .flex_row()
            .flex_wrap()
            .justify_center()
            .gap_1()
            .max_w(px(360.))
            .p_2()
            .rounded_md()
            .bg(rgb(0x161b22))
            .border_1()
            .border_color(rgb(0x30363d));
        if reactions.is_empty() {
            picker = picker.child(
                div()
                    .text_sm()
                    .text_color(rgb(0x8b949e))
                    .child("Loading reactions…"),
            );
        }
        for (index, reaction) in reactions.iter().enumerate() {
            let emoji = reaction.emoji.clone();
            picker = picker.child(
                div()
                    .id(("story-reaction-option", index))
                    .cursor_pointer()
                    .text_2xl()
                    .p_1()
                    .child(emoji.clone())
                    .on_click(cx.listener(move |this, _, _, cx| {
                        this.pick_story_reaction(&emoji, cx);
                    })),
            );
        }
        picker.into_any_element()
    }

    /// Phase 9.2: reaction / reply / delete affordances under the viewer
    /// visual, plus the reaction picker popover and the reply input row.
    /// The quick-react toggles ❤; Reply is gated on
    /// `story.can_be_replied`; Delete on `story.can_be_deleted`.
    fn story_action_row(&self, cx: &mut Context<Self>) -> AnyElement {
        let story = self.current_story();
        let chosen = story
            .as_ref()
            .and_then(|story| story.chosen_reaction_emoji.clone());
        let can_reply = story.as_ref().is_some_and(|story| story.can_be_replied);
        let can_delete = story.as_ref().is_some_and(|story| story.can_be_deleted);
        let quick_label = if chosen.as_deref() == Some("❤") {
            "❤️ ✓"
        } else {
            "❤️"
        };
        let mut row = div().flex().gap_2().items_center().justify_center();
        row = row.child(
            Button::new("story-quick-react")
                .label(quick_label)
                .ghost()
                .text_color(rgb(0xffffff))
                .on_click(cx.listener(|this, _, _, cx| {
                    this.quick_react_story(cx);
                })),
        );
        row = row.child(
            Button::new("story-react-picker")
                .label("React…")
                .ghost()
                .text_color(rgb(0xffffff))
                .on_click(cx.listener(|this, _, _, cx| {
                    this.toggle_story_reaction_picker(cx);
                })),
        );
        if can_reply {
            row = row.child(
                Button::new("story-reply")
                    .label("Reply")
                    .ghost()
                    .text_color(rgb(0xffffff))
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.toggle_story_reply(cx);
                    })),
            );
        }
        if can_delete {
            row = row.child(
                Button::new("story-delete")
                    .label("Delete")
                    .ghost()
                    .text_color(rgb(0xffffff))
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.delete_story_viewer(cx);
                    })),
            );
        }
        let mut column = div().flex().flex_col().gap_2().items_center().child(row);
        if self.story_reaction_picker_open {
            column = column.child(self.story_reaction_picker(cx));
        }
        if self.story_reply_open {
            column =
                column.child(
                    div()
                        .flex()
                        .gap_2()
                        .items_center()
                        .w(px(360.))
                        .child(
                            div()
                                .flex_1()
                                .child(Textarea::new(&self.story_reply_input).h(px(40.))),
                        )
                        .child(Button::new("story-reply-send").label("Send").on_click(
                            cx.listener(|this, _, window, cx| {
                                this.send_story_reply(window, cx);
                            }),
                        )),
                );
        }
        column.into_any_element()
    }

    /// Phase 9.1: fullscreen story overlay, modeled on
    /// `media_viewer_overlay`: poster name + "Story N of M" header, the
    /// photo (video shows its thumbnail; live/unsupported show a
    /// placeholder), the caption, and Prev / Next / Close controls. The
    /// backdrop click and Escape (see `cancel_search`) close it.
    fn story_viewer_overlay(&self, cx: &mut Context<Self>) -> impl IntoElement {
        let item = self
            .story_viewer
            .current()
            .cloned()
            .unwrap_or_else(|| StoryViewerItem {
                chat_id: ChatId(0),
                story_id: 0,
                kind: StoryViewerKind::Unsupported,
                display_file_ids: Vec::new(),
                download_file_id: FileId(0),
                caption: String::new(),
                caption_entities: Vec::new(),
                duration_label: None,
                is_live: false,
            });
        let (position, total) = self.story_viewer.position().unwrap_or((0, 0));
        let poster = self
            .session()
            .and_then(|s| s.chats.get(&item.chat_id.0))
            .map(|chat| chat.title.clone())
            .unwrap_or_else(|| format!("Chat {}", item.chat_id.0));
        let files: HashMap<i32, ParsedFile> =
            self.session().map(|s| s.files.clone()).unwrap_or_default();
        let downloading: HashSet<i32> = self
            .session()
            .map(|s| s.downloading.clone())
            .unwrap_or_default();
        let roots = self.media_display_roots();
        let path = story_viewer_display_path(&item, &files, &roots);
        let downloading_now = item
            .display_file_ids
            .iter()
            .chain(std::iter::once(&item.download_file_id))
            .any(|id| file_is_downloading(*id, &files, &downloading));
        let kind_label = item.kind.label();
        let header_label = if total > 1 {
            format!("{poster} · {kind_label} {position} of {total}")
        } else {
            format!("{poster} · {kind_label}")
        };
        let visual: AnyElement = if let Some(path) = path {
            img(path)
                .id(("story-viewer-img", item.story_id as u64))
                .w(px(360.))
                .h(px(640.))
                .rounded_md()
                .object_fit(ObjectFit::Contain)
                .bg(rgb(0x0d1117))
                .with_fallback(move || {
                    div()
                        .w(px(360.))
                        .h(px(640.))
                        .rounded_md()
                        .bg(rgb(0x0d1117))
                        .flex()
                        .items_center()
                        .justify_center()
                        .text_color(rgb(0xffffff))
                        .child(format!("{kind_label} — could not render"))
                        .into_any_element()
                })
                .into_any_element()
        } else {
            let status = if downloading_now {
                format!("{kind_label} — downloading…")
            } else {
                format!("{kind_label} — not downloaded")
            };
            let status = match (&item.duration_label, downloading_now) {
                (Some(duration), _) => format!("Video · {duration} — {status}"),
                _ => status,
            };
            let status = if matches!(
                item.kind,
                StoryViewerKind::Live | StoryViewerKind::Unsupported
            ) {
                format!("{kind_label} — not supported in this slice")
            } else {
                status
            };
            div()
                .id(("story-viewer-loading", item.story_id as u64))
                .w(px(360.))
                .h(px(640.))
                .rounded_md()
                .bg(rgb(0x0d1117))
                .flex()
                .items_center()
                .justify_center()
                .child(div().text_sm().text_color(rgb(0xffffff)).child(status))
                .into_any_element()
        };
        let caption: Option<AnyElement> = (!item.caption.is_empty()).then(|| {
            rich_text_line(
                &item.caption,
                &item.caption_entities,
                (item.chat_id.0, item.story_id as u64),
                true,
                &self.spoiler_revealed,
                cx,
            )
        });
        // Phase 9.2: own-story interaction counters under the caption.
        let counts: Option<String> = self.story_viewer_counts();
        div()
            .id("story-viewer-overlay")
            .absolute()
            .top_0()
            .left_0()
            .right_0()
            .bottom_0()
            .flex()
            .items_center()
            .justify_center()
            .child(
                div()
                    .id("story-viewer-backdrop")
                    .absolute()
                    .top_0()
                    .left_0()
                    .right_0()
                    .bottom_0()
                    .bg(rgba(0x000000e6))
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.close_story_viewer(cx);
                    })),
            )
            .child(
                div()
                    .id("story-viewer-panel")
                    .flex()
                    .flex_col()
                    .items_center()
                    .gap_2()
                    .p_4()
                    .max_w(px(480.))
                    .max_h_full()
                    .child(
                        div()
                            .flex()
                            .w(px(360.))
                            .items_center()
                            .justify_between()
                            .child(
                                div()
                                    .font_semibold()
                                    .text_color(rgb(0xffffff))
                                    .child(header_label),
                            )
                            .child(
                                div()
                                    .id("story-viewer-close")
                                    .cursor_pointer()
                                    .px_2()
                                    .py_1()
                                    .rounded_md()
                                    .text_color(rgb(0xffffff))
                                    .child("Close")
                                    .on_click(cx.listener(|this, _, _, cx| {
                                        this.close_story_viewer(cx);
                                    })),
                            ),
                    )
                    .child(visual)
                    .when_some(caption, |this, caption| {
                        this.child(div().text_color(rgb(0xffffff)).child(caption))
                    })
                    .when_some(counts, |this, counts| {
                        this.child(div().text_xs().text_color(rgb(0x8b949e)).child(counts))
                    })
                    .child(self.story_action_row(cx))
                    .child(
                        div()
                            .flex()
                            .gap_2()
                            .child(
                                Button::new("story-viewer-prev")
                                    .label("‹ Prev")
                                    .ghost()
                                    .text_color(rgb(0xffffff))
                                    .disabled(position <= 1)
                                    .on_click(cx.listener(|this, _, _, cx| {
                                        this.step_story_viewer(-1, cx);
                                    })),
                            )
                            .child(
                                Button::new("story-viewer-next")
                                    .label("Next ›")
                                    .ghost()
                                    .text_color(rgb(0xffffff))
                                    .disabled(position >= total)
                                    .on_click(cx.listener(|this, _, _, cx| {
                                        this.step_story_viewer(1, cx);
                                    })),
                            ),
                    ),
            )
    }

    /// Phase 9.3: the story composer overlay — path entry (no native file
    /// picker yet), photo preview, caption, the 4-way privacy selector
    /// with a contact picker for "Selected users", and the Post button.
    /// `canPostStory` is checked on every Post press; the status line
    /// shows the honest pending / succeeded / failed states.
    fn story_composer_overlay(&self, cx: &mut Context<Self>) -> impl IntoElement {
        let path = self.story_composer_path.read(cx).value().trim().to_string();
        let kind = StoryMediaKind::detect(&path);
        let file_exists = !path.is_empty() && std::path::Path::new(&path).is_file();

        let preview: AnyElement = match (kind, file_exists) {
            (StoryMediaKind::Photo, true) => img(std::path::Path::new(&path))
                .id("story-composer-preview")
                .w(px(180.))
                .h(px(240.))
                .rounded_md()
                .object_fit(ObjectFit::Contain)
                .bg(rgb(0x0d1117))
                .with_fallback(|| {
                    div()
                        .w(px(180.))
                        .h(px(240.))
                        .rounded_md()
                        .bg(rgb(0x0d1117))
                        .flex()
                        .items_center()
                        .justify_center()
                        .text_color(rgb(0xffffff))
                        .child("could not render")
                        .into_any_element()
                })
                .into_any_element(),
            (StoryMediaKind::Video, true) => div()
                .id("story-composer-preview")
                .w(px(180.))
                .h(px(240.))
                .rounded_md()
                .bg(rgb(0x0d1117))
                .flex()
                .items_center()
                .justify_center()
                .text_sm()
                .text_color(rgb(0xffffff))
                .child("Video — uploads the full file")
                .into_any_element(),
            _ => div()
                .id("story-composer-preview")
                .w(px(180.))
                .h(px(240.))
                .rounded_md()
                .bg(rgb(0x0d1117))
                .flex()
                .items_center()
                .justify_center()
                .text_sm()
                .text_color(rgb(0x8b949e))
                .child("Photo/video preview")
                .into_any_element(),
        };

        let mut privacy = div().flex().flex_col().gap_1();
        for option in StoryPrivacy::ALL {
            let selected = self.story_composer.privacy == option;
            let label = option.label();
            privacy = privacy.child(
                Button::new(format!("story-composer-privacy-{label}"))
                    .label(if selected {
                        format!("☑ {label}")
                    } else {
                        format!("☐ {label}")
                    })
                    .ghost()
                    .text_color(rgb(0xffffff))
                    .on_click(cx.listener(move |this, _, _, cx| {
                        this.story_composer.privacy = option;
                        this.story_composer.local_error = None;
                        cx.notify();
                    })),
            );
        }

        let users_picker: Option<AnyElement> =
            (self.story_composer.privacy == StoryPrivacy::SelectedUsers).then(|| {
                let query = self.story_composer_user_search.read(cx).value();
                let rows = self.g1_contact_rows(&query, cx);
                let selected = self.story_composer.selected_user_ids.clone();
                let mut list = div()
                    .id("story-composer-users")
                    .flex()
                    .flex_col()
                    .gap_1()
                    .max_h(px(160.))
                    .overflow_y_scroll();
                if rows.is_empty() {
                    list = list.child(
                        div()
                            .text_sm()
                            .text_color(rgb(0x8b949e))
                            .child("No contacts found"),
                    );
                }
                for row in rows.iter().take(50) {
                    list = list.child(self.g1_contact_checkbox(
                        "story-composer".to_string(),
                        row,
                        selected.contains(&row.user_id),
                        row.user_id,
                        cx,
                    ));
                }
                div()
                    .flex()
                    .flex_col()
                    .gap_1()
                    .child(Textarea::new(&self.story_composer_user_search).h(px(32.)))
                    .child(list)
                    .into_any_element()
            });

        let mut expiry = div().flex().flex_col().gap_1();
        for option in StoryExpiry::ALL {
            let selected = self.story_composer.expiry == option;
            let label = option.label();
            expiry = expiry.child(
                Button::new(format!("story-composer-expiry-{label}"))
                    .label(if selected {
                        format!("☑ {label}")
                    } else {
                        format!("☐ {label}")
                    })
                    .ghost()
                    .text_color(rgb(0xffffff))
                    .on_click(cx.listener(move |this, _, _, cx| {
                        this.story_composer.expiry = option;
                        this.story_composer.local_error = None;
                        cx.notify();
                    })),
            );
        }

        let toggles = div()
            .flex()
            .flex_col()
            .gap_1()
            .child(
                Button::new("story-composer-post-to-chat-page")
                    .label(if self.story_composer.post_to_chat_page {
                        "☑ Post to chat page (keep accessible after expiry)"
                    } else {
                        "☐ Post to chat page (keep accessible after expiry)"
                    })
                    .ghost()
                    .text_color(rgb(0xffffff))
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.story_composer.post_to_chat_page =
                            !this.story_composer.post_to_chat_page;
                        this.story_composer.local_error = None;
                        cx.notify();
                    })),
            )
            .child(
                Button::new("story-composer-protect-content")
                    .label(if self.story_composer.protect_content {
                        "☑ Protect content (no forwarding)"
                    } else {
                        "☐ Protect content (no forwarding)"
                    })
                    .ghost()
                    .text_color(rgb(0xffffff))
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.story_composer.protect_content = !this.story_composer.protect_content;
                        this.story_composer.local_error = None;
                        cx.notify();
                    })),
            );

        let status = self.story_composer_status();
        let busy = self.story_composer.check_sent
            || self.story_composer.post_sent
            || self.session().is_some_and(|session| {
                matches!(session.story_post.outcome, StoryPostOutcome::Posting { .. })
            });

        div()
            .id("story-composer-overlay")
            .absolute()
            .top_0()
            .left_0()
            .right_0()
            .bottom_0()
            .flex()
            .items_center()
            .justify_center()
            .child(
                div()
                    .id("story-composer-backdrop")
                    .absolute()
                    .top_0()
                    .left_0()
                    .right_0()
                    .bottom_0()
                    .bg(rgba(0x000000e6))
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.close_story_composer(cx);
                    })),
            )
            .child(
                div()
                    .id("story-composer-panel")
                    .flex()
                    .flex_col()
                    .gap_2()
                    .p_4()
                    .max_w(px(480.))
                    .max_h_full()
                    // Phase 9.4: the options section outgrew the window —
                    // scroll instead of clipping the Post button.
                    .overflow_y_scroll()
                    .rounded_lg()
                    .bg(rgb(0x161b22))
                    .child(
                        div()
                            .flex()
                            .items_center()
                            .justify_between()
                            .child(
                                div()
                                    .font_semibold()
                                    .text_color(rgb(0xffffff))
                                    .child("New story"),
                            )
                            .child(
                                div()
                                    .id("story-composer-close")
                                    .cursor_pointer()
                                    .px_2()
                                    .py_1()
                                    .rounded_md()
                                    .text_color(rgb(0xffffff))
                                    .child("Close")
                                    .on_click(cx.listener(|this, _, _, cx| {
                                        this.close_story_composer(cx);
                                    })),
                            ),
                    )
                    .child(
                        div()
                            .flex()
                            .flex_col()
                            .items_center()
                            .gap_2()
                            .child(preview)
                            .child(
                                div()
                                    .w_full()
                                    .flex()
                                    .flex_col()
                                    .gap_1()
                                    .child(
                                        div()
                                            .text_xs()
                                            .text_color(rgb(0x8b949e))
                                            .child(format!("{} file", kind.label())),
                                    )
                                    .child(Textarea::new(&self.story_composer_path).h(px(40.)))
                                    .child(
                                        div().text_xs().text_color(rgb(0x8b949e)).child("Caption"),
                                    )
                                    .child(Textarea::new(&self.story_composer_caption).h(px(64.))),
                            ),
                    )
                    .child(
                        div()
                            .text_xs()
                            .text_color(rgb(0x8b949e))
                            .child("Who can see it"),
                    )
                    .child(privacy)
                    .when_some(users_picker, |this, picker| this.child(picker))
                    // Phase 9.4: expiry, areas (link + suggested-reaction
                    // stickers), and the post-to-chat-page /
                    // protect-content toggles.
                    .child(
                        div()
                            .text_xs()
                            .text_color(rgb(0x8b949e))
                            .child("Expires after"),
                    )
                    .child(expiry)
                    .child(
                        div()
                            .text_xs()
                            .text_color(rgb(0x8b949e))
                            .child("Story stickers"),
                    )
                    .child(
                        div()
                            .text_xs()
                            .text_color(rgb(0x8b949e))
                            .child("Link sticker URL"),
                    )
                    .child(Textarea::new(&self.story_composer_link).h(px(32.)))
                    .child(
                        div()
                            .text_xs()
                            .text_color(rgb(0x8b949e))
                            .child("Reaction stickers (emoji, space-separated)"),
                    )
                    .child(Textarea::new(&self.story_composer_reaction).h(px(32.)))
                    .child(div().text_xs().text_color(rgb(0x8b949e)).child("Options"))
                    .child(toggles)
                    .when_some(status, |this, status| {
                        this.child(div().text_sm().text_color(rgb(0xffffff)).child(status))
                    })
                    .child(
                        Button::new("story-composer-post")
                            .label(if busy { "Working…" } else { "Post story" })
                            .disabled(busy)
                            .on_click(cx.listener(|this, _, _, cx| {
                                this.story_composer_post(cx);
                            })),
                    ),
            )
    }

    fn forward_picker_panel(&self, cx: &mut Context<Self>) -> impl IntoElement {
        let query = self.forward_search_input.read(cx).value().to_string();
        let draft = self.pending_forward.clone();
        let count = draft.as_ref().map(|d| d.count()).unwrap_or(0);
        let from_title = draft
            .as_ref()
            .and_then(|d| {
                self.session()
                    .and_then(|s| s.chats.get(&d.from_chat_id.0).map(|c| c.title.clone()))
            })
            .unwrap_or_else(|| "this chat".into());
        let dests: Vec<(ChatId, String)> = self
            .session()
            .map(|session| {
                session
                    .forward_destinations(&query)
                    .into_iter()
                    .map(|chat| (chat.id, chat.title.clone()))
                    .collect()
            })
            .unwrap_or_default();
        let heading = if count == 1 {
            format!("Forward 1 message from {from_title}")
        } else {
            format!("Forward {count} messages from {from_title}")
        };
        let mut list = div()
            .id("forward-dest-list")
            .flex()
            .flex_col()
            .gap_1()
            .max_h(px(220.));
        if dests.is_empty() {
            list = list.child(
                div()
                    .text_sm()
                    .text_color(cx.theme().muted_foreground)
                    .child("No matching loaded chats."),
            );
        } else {
            for (id, title) in dests {
                list = list.child(forward_dest_row(id, title, cx));
            }
        }
        div()
            .id("forward-picker")
            .flex()
            .flex_col()
            .gap_2()
            .px_3()
            .py_2()
            .rounded_md()
            .border_1()
            .border_color(rgb(0x58a6ff))
            .bg(rgb(0x161b22))
            .child(
                div()
                    .flex()
                    .items_center()
                    .justify_between()
                    .child(
                        div()
                            .text_sm()
                            .font_semibold()
                            .text_color(rgb(0x58a6ff))
                            .child("Forward to…"),
                    )
                    .child(
                        Button::new("cancel-forward-picker")
                            .label("Cancel")
                            .ghost()
                            .on_click(cx.listener(|this, _, window, cx| {
                                this.close_forward_picker(window, cx);
                            })),
                    ),
            )
            .child(div().text_xs().text_color(rgb(0xc9d1d9)).child(heading))
            .child(Textarea::new(&self.forward_search_input).h(px(36.)))
            // M1: `forwardMessages.send_copy` ("Hide sender name", TGX)
            // and `forwardMessages.remove_caption` (only applies to
            // send_copy copies — the checkbox disables itself otherwise).
            .child(
                div()
                    .flex()
                    .items_center()
                    .gap_2()
                    .child(
                        Button::new("forward-send-copy")
                            .label(if draft.as_ref().is_some_and(|d| d.send_copy) {
                                "☑ Hide sender name"
                            } else {
                                "☐ Hide sender name"
                            })
                            .ghost()
                            .on_click(cx.listener(|this, _, _, cx| {
                                if let Some(draft) = this.pending_forward.as_mut() {
                                    draft.send_copy = !draft.send_copy;
                                    if !draft.send_copy {
                                        draft.remove_caption = false;
                                    }
                                }
                                cx.notify();
                            })),
                    )
                    .child(
                        Button::new("forward-remove-caption")
                            .label(if draft.as_ref().is_some_and(|d| d.remove_caption) {
                                "☑ Remove caption"
                            } else {
                                "☐ Remove caption"
                            })
                            .ghost()
                            .on_click(cx.listener(|this, _, _, cx| {
                                if let Some(draft) = this.pending_forward.as_mut()
                                    && draft.send_copy
                                {
                                    draft.remove_caption = !draft.remove_caption;
                                }
                                cx.notify();
                            })),
                    ),
            )
            .child(list)
    }

    fn jump_to_replied_message(&mut self, message_id: MessageId, cx: &mut Context<Self>) {
        if let Some(live) = self.live.as_mut() {
            self.status_note = match live.driver.jump_to_replied_message(message_id) {
                Ok(_) => chat_search_jump_note(&live.driver.session),
                Err(_) => "could not jump to message".into(),
            };
        } else if let Some(session) = self.demo_session.as_mut() {
            let _ = session.begin_chat_search_jump(message_id);
            self.status_note = chat_search_jump_note(session);
        }
        cx.notify();
    }

    fn open_chat_search_ui(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if self.pane_mode() != PaneMode::Ready {
            return;
        }
        let opened = if let Some(live) = self.live.as_mut() {
            match live.driver.open_chat_search() {
                Ok(true) => {
                    self.status_note = "search in chat".into();
                    true
                }
                Ok(false) => {
                    self.status_note = "select a chat to search in conversation".into();
                    false
                }
                Err(_) => {
                    self.status_note = "could not search in chat".into();
                    false
                }
            }
        } else if let Some(session) = self.demo_session.as_mut() {
            if session.open_chat_search() {
                self.status_note = "search in chat".into();
                true
            } else {
                self.status_note = "select a chat to search in conversation".into();
                false
            }
        } else {
            false
        };
        if opened {
            self.chat_search_input
                .update(cx, |input, cx| input.focus(window, cx));
        }
        cx.notify();
    }

    fn close_chat_search_ui(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if let Some(live) = self.live.as_mut() {
            live.driver.close_chat_search();
        } else if let Some(session) = self.demo_session.as_mut() {
            session.close_chat_search();
        }
        self.chat_search_input
            .update(cx, |input, cx| input.set_value("", window, cx));
        self.status_note = "in-chat search closed".into();
        cx.notify();
    }

    fn sync_chat_search_query(&mut self, query: &str, cx: &mut Context<Self>) {
        if self.pane_mode() != PaneMode::Ready || !self.chat_search_is_open() {
            return;
        }
        if let Some(live) = self.live.as_mut() {
            match live.driver.set_chat_search_query(query) {
                Ok(ChatSearchQueryOutcome::Sent(_)) => {
                    self.status_note = "searching in chat…".into()
                }
                Ok(ChatSearchQueryOutcome::Debounced { token }) => {
                    self.schedule_chat_search_commit(token, cx);
                }
                Ok(ChatSearchQueryOutcome::Unchanged) if query.trim().is_empty() => {
                    self.status_note = "search in chat".into();
                }
                Ok(ChatSearchQueryOutcome::Unchanged) => {}
                Err(_) => self.status_note = "could not search in chat".into(),
            }
        } else if let Some(session) = self.demo_session.as_mut() {
            let trimmed = query.trim();
            if session.chat_search.open
                && session.chat_search.query == trimmed
                && !matches!(session.chat_search.status, SearchStatus::Closed)
            {
                cx.notify();
                return;
            }
            session.apply_local_chat_search_filter(query);
        }
        cx.notify();
    }

    fn schedule_chat_search_commit(&mut self, token: u64, cx: &mut Context<Self>) {
        cx.spawn(async move |this, cx| {
            cx.background_executor().timer(SEARCH_DEBOUNCE).await;
            this.update(cx, |this, cx| {
                if let Some(live) = this.live.as_mut() {
                    match live.driver.commit_debounced_chat_search(token) {
                        Ok(Some(_)) => this.status_note = "searching in chat…".into(),
                        Ok(None) => {}
                        Err(_) => this.status_note = "could not search in chat".into(),
                    }
                }
                cx.notify();
            })
            .ok();
        })
        .detach();
    }

