/// `ReadyChannelsAdmin` fixture (Phase 2.3): like `apply_ready_channels`,
/// but the `getMe`/`getChatMember` pair leaves the viewer as an administrator
/// with `rights.can_post_messages: true` (full `chatAdministratorRights`
/// block per schema 1.8.67), so the composer is visible above the broadcast
/// posts. A later `updateMessageInteractionInfo` proves view counts update
/// live.
fn apply_ready_channels_admin(session: &mut Session, sink: &Arc<MemorySink>, seq: &AtomicU64) {
    let dyn_sink: Arc<dyn DiagnosticSink> = sink.clone();
    session.open_chat(ChatId(13));
    let me_extra = session.request(RequestPurpose::GetMe, None);
    let member_extra = session.request(RequestPurpose::GetChatMember, Some(ChatId(13)));
    let views = |count: i32| {
        format!(
            r#""interaction_info":{{"@type":"messageInteractionInfo","view_count":{count},"forward_count":7,"reply_info":null,"reactions":null}}"#
        )
    };
    let post = |id: i64, text: &str, view_count: i32| {
        // Phase D2: channel author signatures (`message.author_signature`,
        // schema 1.8.67 line 3165) render below the post.
        let signature = if id == 201 { "Demo Admin" } else { "News Desk" };
        format!(
            r#"{{"@type":"updateNewMessage","message":{{"id":{id},"chat_id":13,"sender_id":{{"@type":"messageSenderChat","chat_id":13}},"is_outgoing":false,"is_channel_post":true,"author_signature":"{signature}",{},"content":{{"@type":"messageText","text":{{"@type":"formattedText","text":"{text}","entities":[]}}}}}}}}"#,
            views(view_count),
        )
    };
    // `chatMemberStatusAdministrator can_be_edited:Bool
    // rights:chatAdministratorRights` — full rights block, `can_post_messages`
    // true (TDLib 1.8.67 `chatAdministratorRights` field order).
    let admin_status = r#"{"@type":"chatMemberStatusAdministrator","can_be_edited":true,"rights":{"@type":"chatAdministratorRights","can_manage_chat":true,"can_change_info":true,"can_post_messages":true,"can_edit_messages":true,"can_delete_messages":true,"can_invite_users":true,"can_restrict_members":true,"can_pin_messages":true,"can_manage_topics":true,"can_promote_members":true,"can_manage_video_chats":true,"can_post_stories":false,"can_edit_stories":false,"can_delete_stories":false,"can_manage_direct_messages":true,"can_manage_tags":false,"can_send_welcome_messages":false,"is_anonymous":false}}"#;
    let jsons = [
        format!(
            r#"{{"@type":"user","@extra":"{}","id":777,"first_name":"Demo","last_name":"Viewer","usernames":null,"phone_number":"","status":null,"profile_photo":null,"is_contact":false,"is_mutual_contact":false,"is_close_friend":false,"is_verified":false,"is_premium":false,"is_support":false,"restriction_reason":"","is_scam":false,"is_fake":false,"is_bot":false,"type":{{"@type":"userTypeRegular"}}}}"#,
            me_extra.0,
        ),
        format!(
            r#"{{"@type":"chatMember","@extra":"{}","member_id":{{"@type":"messageSenderUser","user_id":777}},"tag":"","inviter_user_id":0,"joined_chat_date":0,"status":{}}}"#,
            member_extra.0, admin_status,
        ),
        post(201, "Broadcast one — channel post from the channel itself.", 12345),
        post(202, "Broadcast two — a second post with fewer views.", 987),
        // Live view-count bump on the first post.
        r#"{"@type":"updateMessageInteractionInfo","chat_id":13,"message_id":201,"interaction_info":{"@type":"messageInteractionInfo","view_count":12402,"forward_count":7,"reply_info":null,"reactions":null}}"#
            .to_string(),
    ];
    for json in jsons {
        if let Some(owned) = copy_and_parse(&json, seq, &dyn_sink) {
            session.apply(owned);
        }
    }
}

/// `ReadyInviteLinks` fixture (Phase D3a): like `apply_ready_channels_admin`
/// (chat 13, viewer 777 has `can_invite_users`), plus a `chatInviteLinks`
/// response and a `chatJoinRequests` response through the real reducer
/// paths, so the info-panel sections render loaded data. Includes a
/// primary link, a named expiring limited link, and a join-request link
/// with two pending requests (with `updateUser` names).
fn apply_ready_invite_links(session: &mut Session, sink: &Arc<MemorySink>, seq: &AtomicU64) {
    apply_ready_channels_admin(session, sink, seq);
    let dyn_sink: Arc<dyn DiagnosticSink> = sink.clone();
    let links_extra = session.request(RequestPurpose::GetChatInviteLinks, Some(ChatId(13)));
    let requests_extra = session.request(RequestPurpose::GetChatJoinRequests, Some(ChatId(13)));
    let link = |invite_link: &str,
                name: &str,
                expiration_date: i64,
                member_limit: i32,
                member_count: i32,
                pending: i32,
                join_request: bool,
                primary: bool| {
        format!(
            r#"{{"@type":"chatInviteLink","invite_link":"{invite_link}","name":"{name}","creator_user_id":777,"date":1788000000,"edit_date":0,"expiration_date":{expiration_date},"subscription_pricing":null,"member_limit":{member_limit},"member_count":{member_count},"expired_member_count":0,"pending_join_request_count":{pending},"creates_join_request":{join_request},"is_primary":{primary},"is_revoked":false}}"#
        )
    };
    let jsons = [
        format!(
            r#"{{"@type":"chatInviteLinks","@extra":"{}","total_count":3,"invite_links":[{},{},{}]}}"#,
            links_extra.0,
            link("https://t.me/+primarylink", "", 0, 0, 1204, 0, false, true),
            link("https://t.me/+moderatorslink", "Moderators", 1_792_756_800, 25, 8, 0, false, false),
            link("https://t.me/+joinapprovallink", "Join approval", 0, 0, 0, 2, true, false),
        ),
        format!(
            r#"{{"@type":"chatJoinRequests","@extra":"{}","total_count":2,"requests":[{{"@type":"chatJoinRequest","user_id":7001,"date":1788500000,"bio":"Hi, I would like to join the channel."}},{{"@type":"chatJoinRequest","user_id":7002,"date":1788550000,"bio":"Long-time reader."}}]}}"#,
            requests_extra.0,
        ),
        r#"{"@type":"updateUser","user":{"@type":"user","id":7001,"first_name":"Dana","last_name":"Levi","usernames":null,"phone_number":"","status":null,"profile_photo":null,"is_contact":false,"is_mutual_contact":false,"is_close_friend":false,"is_verified":false,"is_premium":false,"is_support":false,"restriction_reason":"","is_scam":false,"is_fake":false,"is_bot":false,"type":{"@type":"userTypeRegular"}}}"#.to_string(),
        r#"{"@type":"updateUser","user":{"@type":"user","id":7002,"first_name":"Omar","last_name":"Haddad","usernames":null,"phone_number":"","status":null,"profile_photo":null,"is_contact":false,"is_mutual_contact":false,"is_close_friend":false,"is_verified":false,"is_premium":false,"is_support":false,"restriction_reason":"","is_scam":false,"is_fake":false,"is_bot":false,"type":{"@type":"userTypeRegular"}}}"#.to_string(),
    ];
    for json in jsons {
        if let Some(owned) = copy_and_parse(&json, seq, &dyn_sink) {
            session.apply(owned);
        }
    }
}

/// `ReadyAdminManagement` fixture (Phase D3b): like
/// `apply_ready_channels_admin` (chat 13, viewer 777 is an administrator
/// with `can_promote_members: true`), plus a `chatAdministrators`
/// response (owner with custom title + two editable admins) and a
/// `chatMembers` response for the promote picker, all through the real
/// reducer paths. `updateUser` rows give the admins/members display
/// names.
fn apply_ready_admin_management(session: &mut Session, sink: &Arc<MemorySink>, seq: &AtomicU64) {
    apply_ready_channels_admin(session, sink, seq);
    let dyn_sink: Arc<dyn DiagnosticSink> = sink.clone();
    let admins_extra = session.request(RequestPurpose::GetChatAdministrators, Some(ChatId(13)));
    let members_extra = session.request(
        RequestPurpose::GetSupergroupMembers {
            filter: MemberListFilter::Recent,
        },
        Some(ChatId(13)),
    );
    let user = |id: i64, first: &str, last: &str| {
        format!(
            r#"{{"@type":"updateUser","user":{{"@type":"user","id":{id},"first_name":"{first}","last_name":"{last}","usernames":null,"phone_number":"","status":null,"profile_photo":null,"is_contact":false,"is_mutual_contact":false,"is_close_friend":false,"is_verified":false,"is_premium":false,"is_support":false,"restriction_reason":"","is_scam":false,"is_fake":false,"is_bot":false,"type":{{"@type":"userTypeRegular"}}}}}}"#
        )
    };
    let jsons = [
        user(1, "Idan", "Founder"),
        user(2, "Dana", "Levi"),
        user(777, "Demo", "Admin"),
        user(5, "Omar", "Haddad"),
        user(6, "Maya", "Sharon"),
        format!(
            r#"{{"@type":"chatAdministrators","@extra":"{}","administrators":[{{"@type":"chatAdministrator","user_id":1,"custom_title":"Founder","is_owner":true,"can_be_edited":false}},{{"@type":"chatAdministrator","user_id":777,"custom_title":"","is_owner":false,"can_be_edited":true}},{{"@type":"chatAdministrator","user_id":2,"custom_title":"Mod","is_owner":false,"can_be_edited":true}}]}}"#,
            admins_extra.0
        ),
        format!(
            r#"{{"@type":"chatMembers","@extra":"{}","total_count":2,"members":[{{"@type":"chatMember","member_id":{{"@type":"messageSenderUser","user_id":5}},"tag":"","inviter_user_id":0,"joined_chat_date":0,"status":{{"@type":"chatMemberStatusMember"}}}},{{"@type":"chatMember","member_id":{{"@type":"messageSenderUser","user_id":6}},"tag":"","inviter_user_id":0,"joined_chat_date":0,"status":{{"@type":"chatMemberStatusMember"}}}}]}}"#,
            members_extra.0
        ),
    ];
    for json in jsons {
        if let Some(owned) = copy_and_parse(&json, seq, &dyn_sink) {
            session.apply(owned);
        }
    }
}

/// `ReadyAdminLog` fixture (Phase D3c): like `apply_ready_channels_admin`
/// (chat 13, viewer 777 is an administrator), plus `updateUser` rows for
/// the actors/targets and a `chatEvents` response through the real
/// reducer paths. Event timestamps are relative to capture time so the
/// rows show "just now" / "Nm ago". Covers the handled action types
/// plus one unhandled (`chatEventMemberLeft`) rendering as a generic row.
fn apply_ready_admin_log(session: &mut Session, sink: &Arc<MemorySink>, seq: &AtomicU64) {
    apply_ready_channels_admin(session, sink, seq);
    let dyn_sink: Arc<dyn DiagnosticSink> = sink.clone();
    let log_extra = session.request(
        RequestPurpose::GetChatEventLog { from_event_id: 0 },
        Some(ChatId(13)),
    );
    let user = |id: i64, first: &str, last: &str| {
        format!(
            r#"{{"@type":"updateUser","user":{{"@type":"user","id":{id},"first_name":"{first}","last_name":"{last}","usernames":null,"phone_number":"","status":null,"profile_photo":null,"is_contact":false,"is_mutual_contact":false,"is_close_friend":false,"is_verified":false,"is_premium":false,"is_support":false,"restriction_reason":"","is_scam":false,"is_fake":false,"is_bot":false,"type":{{"@type":"userTypeRegular"}}}}}}"#
        )
    };
    let now = unix_ms_now() / 1000;
    let date = |minutes_ago: u64| now - minutes_ago * 60;
    let sender = |id: i64| format!(r#"{{"@type":"messageSenderUser","user_id":{id}}}"#);
    let link = |url: &str, name: &str| {
        format!(
            r#"{{"@type":"chatInviteLink","invite_link":"{url}","name":"{name}","creator_user_id":777,"date":1700000000,"edit_date":0,"expiration_date":0,"member_limit":0,"member_count":0,"expired_member_count":0,"pending_join_request_count":0,"creates_join_request":false,"is_primary":false,"is_revoked":false}}"#
        )
    };
    let event = |id: i64, minutes_ago: u64, actor: i64, action: &str| {
        format!(
            r#"{{"@type":"chatEvent","id":{id},"date":{},"member_id":{},"action":{}}}"#,
            date(minutes_ago),
            sender(actor),
            action
        )
    };
    let member_status = r#"{"@type":"chatMemberStatusMember","member_until_date":0}"#;
    let admin_status = r#"{"@type":"chatMemberStatusAdministrator","can_be_edited":true}"#;
    let restricted_status = r#"{"@type":"chatMemberStatusRestricted"}"#;
    let events = [
        event(
            901,
            2,
            1,
            &format!(
                r#"{{"@type":"chatEventMemberPromoted","user_id":2,"old_status":{member_status},"new_status":{admin_status}}}"#
            ),
        ),
        event(
            902,
            9,
            777,
            r#"{"@type":"chatEventTitleChanged","old_title":"Demo channel","new_title":"Demo channel — news"}"#,
        ),
        event(
            903,
            21,
            1,
            &format!(
                r#"{{"@type":"chatEventMemberRestricted","member_id":{},"old_status":{member_status},"new_status":{restricted_status}}}"#,
                sender(6)
            ),
        ),
        event(
            904,
            35,
            5,
            &format!(
                r#"{{"@type":"chatEventMemberJoinedByInviteLink","invite_link":{},"via_chat_folder_invite_link":false}}"#,
                link("https://t.me/+mods", "Mods")
            ),
        ),
        event(
            905,
            58,
            777,
            r#"{"@type":"chatEventMessagePinned","message":{"id":201,"chat_id":13,"content":{"@type":"messageText","text":{"@type":"formattedText","text":"Broadcast one — channel post from the channel itself.","entities":[]}}}}"#,
        ),
        event(
            906,
            95,
            777,
            &format!(
                r#"{{"@type":"chatEventInviteLinkRevoked","invite_link":{}}}"#,
                link("https://t.me/+old", "Old campaign")
            ),
        ),
        event(
            907,
            130,
            1,
            r#"{"@type":"chatEventDescriptionChanged","old_description":"","new_description":"Daily news, no noise."}"#,
        ),
        event(
            908,
            180,
            777,
            &format!(
                r#"{{"@type":"chatEventMemberInvited","user_id":6,"status":{member_status}}}"#
            ),
        ),
        event(
            909,
            240,
            6,
            r#"{"@type":"chatEventMemberLeft"}"#,
        ),
        event(
            910,
            400,
            777,
            r#"{"@type":"chatEventPhotoChanged","old_photo":{"@type":"chatPhoto"},"new_photo":{"@type":"chatPhoto"}}"#,
        ),
    ]
    .join(",");
    let jsons = [
        user(777, "Demo", "Viewer"),
        user(1, "Idan", "Founder"),
        user(2, "Dana", "Levi"),
        user(5, "Omar", "Haddad"),
        user(6, "Maya", "Sharon"),
        format!(
            r#"{{"@type":"chatEvents","@extra":"{}","events":[{events}]}}"#,
            log_extra.0
        ),
    ];
    for json in jsons {
        if let Some(owned) = copy_and_parse(&json, seq, &dyn_sink) {
            session.apply(owned);
        }
    }
}

/// `ReadyGroups2` fixture (Slice G2): on top of `apply_ready_admin_log`
/// (channel 13, viewer 777 admin, loaded event log), flips the channel
/// signature flags on via `updateSupergroup`, grants
/// `can_send_welcome_messages` via `updateSupergroup` admin status, and
/// seeds boost status + a loaded one-message welcome pack directly.
fn apply_ready_groups2(session: &mut Session, sink: &Arc<MemorySink>, seq: &AtomicU64) {
    apply_ready_admin_log(session, sink, seq);
    let dyn_sink: Arc<dyn DiagnosticSink> = sink.clone();
    let jsons = [
        r#"{"@type":"updateSupergroup","supergroup":{"@type":"supergroup","id":13,"sign_messages":true,"show_message_sender":false,"status":{"@type":"chatMemberStatusAdministrator","can_be_edited":true}}}"#.to_string(),
    ];
    for json in jsons {
        if let Some(owned) = copy_and_parse(&json, seq, &dyn_sink) {
            session.apply(owned);
        }
    }
    session.supergroup_send_welcome_right.insert(13, true);
    session.chat_boost_status.insert(13, (4, 38));
    session
        .welcome_message_fetches
        .insert(13, WelcomeMessagesFetch::Loaded);
    session.welcome_messages.insert(
        13,
        vec![ParsedWelcomeMessage {
            id: 5,
            content: MessageContent::Text(quill::telegram::envelope::TextContent {
                text: "Welcome to Demo channel! Read the pinned post first.".to_string(),
                entities: Vec::new(),
                link_preview: None,
            }),
        }],
    );
    session.chat_has_welcome_messages.insert(13, true);
}

/// `ReadyGroupManage` fixture (Slice G1): a demo supergroup ("Demo
/// supergroup", chat id 61, not a channel) with the viewer (777) as an
/// administrator holding `can_restrict_members`, `can_invite_users`,
/// and `can_manage_tags`, plus a loaded `chatMembers` (Recent filter)
/// page: the viewer, an admin with a custom title, a restricted member,
/// and two plain members — all through the real reducer paths, no live
/// Telegram. The caller opens the member dialog on the All tab.
fn apply_ready_group_manage(session: &mut Session, sink: &Arc<MemorySink>, seq: &AtomicU64) {
    let dyn_sink: Arc<dyn DiagnosticSink> = sink.clone();
    let chat_id = 61i64;
    let me_extra = session.request(RequestPurpose::GetMe, None);
    let member_extra = session.request(RequestPurpose::GetChatMember, Some(ChatId(chat_id)));
    let members_extra = session.request(
        RequestPurpose::GetSupergroupMembers {
            filter: MemberListFilter::Recent,
        },
        Some(ChatId(chat_id)),
    );
    // TDLib 1.8.67 `chatAdministratorRights` field order.
    let admin_rights = |manage_tags: bool| {
        format!(
            r#"{{"@type":"chatAdministratorRights","can_manage_chat":true,"can_change_info":true,"can_post_messages":true,"can_edit_messages":true,"can_delete_messages":true,"can_invite_users":true,"can_restrict_members":true,"can_pin_messages":true,"can_manage_topics":false,"can_promote_members":false,"can_manage_video_chats":false,"can_post_stories":false,"can_edit_stories":false,"can_delete_stories":false,"can_manage_direct_messages":false,"can_manage_tags":{manage_tags},"can_send_welcome_messages":false,"is_anonymous":false}}"#
        )
    };
    let user = |id: i64, first: &str, last: &str| {
        format!(
            r#"{{"@type":"updateUser","user":{{"@type":"user","id":{id},"first_name":"{first}","last_name":"{last}","usernames":null,"phone_number":"","status":null,"profile_photo":null,"is_contact":false,"is_mutual_contact":false,"is_close_friend":false,"is_verified":false,"is_premium":false,"is_scam":false,"is_fake":false,"is_bot":false,"type":{{"@type":"userTypeRegular"}}}}}}"#
        )
    };
    let member = |id: i64, tag: &str, status: &str| {
        format!(
            r#"{{"@type":"chatMember","member_id":{{"@type":"messageSenderUser","user_id":{id}}},"tag":"{tag}","inviter_user_id":0,"joined_chat_date":0,"status":{status}}}"#
        )
    };
    let jsons = [
        format!(
            r#"{{"@type":"updateNewChat","chat":{{"id":{chat_id},"title":"Demo supergroup","type":{{"@type":"chatTypeSupergroup","supergroup_id":{chat_id},"is_channel":false}},"unread_count":0}}}}"#
        ),
        format!(
            r#"{{"@type":"updateChatPosition","chat_id":{chat_id},"position":{{"@type":"chatPosition","list":{{"@type":"chatListMain"}},"order":"80","is_pinned":false}}}}"#
        ),
        // The viewer's own status: administrator with the rights the
        // gates read (`updateSupergroup` derives rights from the status
        // admin block — the `supergroup` object carries no top-level
        // rights fields, schema 1.8.67 line 2746).
        format!(
            r#"{{"@type":"updateSupergroup","supergroup":{{"@type":"supergroup","id":{chat_id},"is_forum":false,"status":{{"@type":"chatMemberStatusAdministrator","can_be_edited":true,"rights":{}}}}}}}"#,
            admin_rights(true),
        ),
        user(777, "Demo", "Viewer"),
        format!(
            r#"{{"@type":"user","@extra":"{}","id":777,"first_name":"Demo","last_name":"Viewer","usernames":null,"phone_number":"","status":null,"profile_photo":null,"is_contact":false,"is_mutual_contact":false,"is_close_friend":false,"is_verified":false,"is_premium":false,"is_support":false,"restriction_reason":"","is_scam":false,"is_fake":false,"is_bot":false,"type":{{"@type":"userTypeRegular"}}}}"#,
            me_extra.0,
        ),
        format!(
            r#"{{"@type":"chatMember","@extra":"{}","member_id":{{"@type":"messageSenderUser","user_id":777}},"tag":"","inviter_user_id":0,"joined_chat_date":0,"status":{{"@type":"chatMemberStatusAdministrator","can_be_edited":true,"rights":{}}}}}"#,
            member_extra.0,
            admin_rights(true),
        ),
        user(1, "Idan", "Founder"),
        user(2, "Dana", "Levi"),
        user(5, "Omar", "Haddad"),
        user(6, "Maya", "Sharon"),
        format!(
            r#"{{"@type":"chatMembers","@extra":"{}","total_count":5,"members":[{},{},{},{},{}]}}"#,
            members_extra.0,
            member(
                777,
                "",
                &format!(
                    r#"{{"@type":"chatMemberStatusAdministrator","can_be_edited":true,"rights":{}}}"#,
                    admin_rights(true)
                ),
            ),
            member(
                1,
                "Founder",
                &format!(
                    r#"{{"@type":"chatMemberStatusAdministrator","can_be_edited":false,"rights":{}}}"#,
                    admin_rights(false)
                ),
            ),
            member(2, "", r#"{"@type":"chatMemberStatusRestricted"}"#),
            member(5, "", r#"{"@type":"chatMemberStatusMember"}"#),
            member(6, "", r#"{"@type":"chatMemberStatusMember"}"#),
        ),
    ];
    for json in jsons {
        if let Some(owned) = copy_and_parse(&json, seq, &dyn_sink) {
            session.apply(owned);
        }
    }
    session.open_chat(ChatId(chat_id));
}

fn chat_search_jump_note(session: &Session) -> String {
    match session.chat_search.jump {
        ChatSearchJump::None => String::new(),
        ChatSearchJump::Loading { .. } => "loading around message…".into(),
        ChatSearchJump::Ready { message_id } => format!("jumped to {}", message_id.0),
        ChatSearchJump::Missing { .. } => "message deleted or inaccessible".into(),
    }
}

fn apply_ready_search(session: &mut Session, sink: &Arc<MemorySink>, seq: &AtomicU64) {
    let dyn_sink: Arc<dyn DiagnosticSink> = sink.clone();
    session.open_search();
    let search_gen = session.search.begin_query("hello");
    let chats_extra = session.request_search(RequestPurpose::SearchChats, search_gen);
    let messages_extra = session.request_search(RequestPurpose::SearchMessages, search_gen);
    let jsons = [
        format!(
            r#"{{"@type":"chats","@extra":"{}","total_count":1,"chat_ids":[11]}}"#,
            chats_extra.0
        ),
        format!(
            r#"{{"@type":"foundMessages","@extra":"{}","total_count":1,"next_offset":"","messages":[{{"id":101,"chat_id":11,"is_outgoing":false,"content":{{"@type":"messageText","text":{{"@type":"formattedText","text":"Hello from injected JSON.","entities":[]}}}}}}]}}"#,
            messages_extra.0
        ),
    ];
    for json in jsons {
        if let Some(owned) = copy_and_parse(&json, seq, &dyn_sink) {
            session.apply(owned);
        }
    }
}

fn apply_ready_search_in_chat(session: &mut Session, sink: &Arc<MemorySink>, seq: &AtomicU64) {
    let dyn_sink: Arc<dyn DiagnosticSink> = sink.clone();
    assert!(session.open_chat_search());
    let search_gen = session.chat_search.begin_query("hello");
    let extra =
        session.request_chat_search(RequestPurpose::SearchChatMessages, ChatId(11), search_gen);
    let json = format!(
        r#"{{"@type":"foundChatMessages","@extra":"{}","total_count":2,"next_from_message_id":90,"messages":[{{"id":101,"chat_id":11,"is_outgoing":false,"content":{{"@type":"messageText","text":{{"@type":"formattedText","text":"Hello from injected JSON.","entities":[]}}}}}},{{"id":103,"chat_id":11,"is_outgoing":false,"content":{{"@type":"messageText","text":{{"@type":"formattedText","text":"Two more waiting.","entities":[]}}}}}}]}}"#,
        extra.0
    );
    if let Some(owned) = copy_and_parse(&json, seq, &dyn_sink) {
        session.apply(owned);
    }
    let _ = session.begin_chat_search_jump(MessageId(101));
}

