/// Phase 6: circular initials avatar (contact rows, info panels) shown
/// when no downloaded profile photo is available.
fn initials_avatar(name: &str, size: f32) -> impl IntoElement {
    let initials: String = name
        .split_whitespace()
        .filter_map(|word| word.chars().next())
        .take(2)
        .collect();
    let initials = if initials.is_empty() {
        "?".to_string()
    } else {
        initials
    };
    div()
        .w(px(size))
        .h(px(size))
        .rounded_full()
        .flex_shrink_0()
        .flex()
        .items_center()
        .justify_center()
        .bg(rgb(0x2f81f7))
        .text_color(rgb(0xffffff))
        .text_sm()
        .font_semibold()
        .child(initials)
}

/// Parity slice: deterministic fallback color for chat avatars, so every
/// chat type has a stable, recognizable circle before (or without) a
/// downloaded photo. Telegram's own palette, keyed on the chat id.
fn chat_avatar_color(chat_id: i64) -> Rgba {
    const PALETTE: [u32; 8] = [
        0xe17076, // red
        0xfaa774, // orange
        0xa695e7, // violet
        0x7bc862, // green
        0x6ec9cb, // teal
        0x65aadd, // blue
        0xcc6cbf, // pink
        0xee7aa2, // rose
    ];
    let index = (chat_id.unsigned_abs() % PALETTE.len() as u64) as usize;
    rgb(PALETTE[index])
}

/// Parity slice: circular chat avatar — the downloaded `chat.photo.small`
/// thumbnail when available, otherwise colored initials keyed on the chat
/// id. Used by chat-list rows, the conversation header, and info panels.
fn chat_avatar(
    name: &str,
    chat_id: i64,
    photo_path: Option<&std::path::Path>,
    size: f32,
) -> impl IntoElement {
    match photo_path {
        Some(path) => img(path)
            .id(("chat-avatar-photo", chat_id as u64))
            .w(px(size))
            .h(px(size))
            .rounded_full()
            .flex_shrink_0()
            .object_fit(ObjectFit::Cover)
            .into_any_element(),
        None => {
            let initials: String = name
                .split_whitespace()
                .filter_map(|word| word.chars().next())
                .take(2)
                .collect();
            let initials = if initials.is_empty() {
                "?".to_string()
            } else {
                initials
            };
            div()
                .id(("chat-avatar-initials", chat_id as u64))
                .w(px(size))
                .h(px(size))
                .rounded_full()
                .flex_shrink_0()
                .flex()
                .items_center()
                .justify_center()
                .bg(chat_avatar_color(chat_id))
                .text_color(rgb(0xffffff))
                .text_sm()
                .font_semibold()
                .child(initials)
                .into_any_element()
        }
    }
}

/// Parity slice: compact subscriber/member counts for the header
/// ("12.3K", "1.2M").
fn compact_count(count: i32) -> String {
    if count >= 1_000_000 {
        let value = count as f64 / 1_000_000.0;
        return format!(
            "{}{}",
            if value >= 100.0 {
                format!("{}", value as i64)
            } else {
                format!("{value:.1}")
            },
            "M"
        );
    }
    if count >= 1_000 {
        let value = count as f64 / 1_000.0;
        return format!(
            "{}{}",
            if value >= 100.0 {
                format!("{}", value as i64)
            } else {
                format!("{value:.1}")
            },
            "K"
        );
    }
    count.to_string()
}

/// Parity slice: one-line description snippet for the channel/supergroup
/// header.
fn description_snippet(description: &str, max_chars: usize) -> String {
    let one_line: String = description.split_whitespace().collect::<Vec<_>>().join(" ");
    if one_line.chars().count() <= max_chars {
        return one_line;
    }
    let truncated: String = one_line.chars().take(max_chars).collect();
    format!("{truncated}…")
}

fn session_chat_row(
    chat: &ChatSummary,
    selected: bool,
    // Parity slice: `(folder id, name)` for folder-tag chips.
    folders: &[(i32, String)],
    // Parity slice: show folder-tag chips (`are_folder_tags_enabled`).
    show_tags: bool,
    // Parity slice: sandboxed display path for the downloaded chat photo
    // (`chat.photo.small`), if any; the avatar falls back to colored
    // initials otherwise.
    photo_path: Option<&std::path::Path>,
    // Slice CL2: pinned rows are drag-reorderable, but only on the
    // unfiltered list with at least two pinned chats (TGX
    // `ChatsAdapter`); the caller computes this.
    draggable: bool,
    // Slice CL2: which pinned list the row is in (`setPinnedChats`
    // takes main or archive).
    archived: bool,
    // Slice CL3: multi-select mode — the row toggles selection instead
    // of opening the chat, and shows the check circle.
    selecting: bool,
    checked: bool,
    cx: &mut Context<QuillApp>,
) -> impl IntoElement {
    let id = chat.id;
    let title = chat.title.clone();
    // Slice CL2: cloned for the pin-drag ghost (the row itself moves
    // `title` below).
    let drag_title = title.clone();
    let preview = chat.sidebar_preview();
    // Slice CL1: a marked-as-unread chat shows the unread badge even
    // with zero unread messages (official clients show a dot); the count
    // wins when there are unread messages (TGX TGChat.java:396).
    // Slice CL3: with mentions and a single unread message the main
    // counter hides — the @ badge carries it (TGX `setCounter`:
    // `hasMentions && unreadCount == 1 ? 0 : unreadCount`).
    let has_mentions = chat.unread_mention_count > 0;
    let badge = if chat.unread_count == 0 && chat.is_marked_as_unread {
        Some("●".to_string())
    } else if has_mentions && chat.unread_count == 1 {
        None
    } else {
        unread_badge_text(chat.unread_count)
    };
    let has_reactions = chat.unread_reaction_count > 0;
    let tags: Vec<String> = if show_tags {
        folders
            .iter()
            .filter(|(folder_id, _)| chat.folder_positions.contains_key(folder_id))
            .map(|(_, name)| name.clone())
            .collect()
    } else {
        Vec::new()
    };
    div()
        .id(("chat-row", id.0 as u64))
        .px_2()
        .py_2()
        .rounded_md()
        .cursor_pointer()
        .bg(if selected {
            cx.theme().accent.opacity(0.15)
        } else {
            cx.theme().sidebar
        })
        .on_click(cx.listener(move |this, _, window, cx| {
            // Slice CL3: in multi-select mode a row click toggles the
            // check instead of opening the chat.
            if selecting {
                this.toggle_chat_selected(id, cx);
            } else {
                this.select_listed_chat(id, window, cx);
            }
        }))
        // Slice CL1: right-click opens the chat-row context menu at the
        // click position (window coordinates).
        .on_mouse_down(
            MouseButton::Right,
            cx.listener(move |this, event: &MouseDownEvent, _, cx| {
                this.chat_menu = Some(ChatMenuState {
                    chat_id: id,
                    position: event.position,
                });
                cx.notify();
            }),
        )
        .child(
            div()
                .flex()
                .items_center()
                .gap_2()
                // Parity slice: circular chat photo or colored initials for
                // every chat-list row / chat type.
                // Slice CL3: the select-mode check circle precedes the
                // avatar while multi-select is active.
                .when(selecting, |this| this.child(select_check(id, checked)))
                .child(chat_avatar(&title, id.0, photo_path, 40.))
                .child(
                    div()
                        .flex()
                        .flex_col()
                        .min_w_0()
                        .flex_1()
                        .child(
                            div()
                                .flex()
                                .items_center()
                                .justify_between()
                                .gap_2()
                                .child(
                                    div()
                                        .flex()
                                        .items_center()
                                        .gap_1()
                                        .min_w_0()
                                        .child(div().font_medium().min_w_0().child(title))
                                        .when(chat.is_muted(), |this| this.child(muted_badge(id)))
                                        .when(chat.is_forum_chat(), |this| {
                                            this.child(forum_badge(id))
                                        })
                                        // Phase B1: lock indicator for
                                        // secret chats (E2E).
                                        .when(
                                            matches!(chat.kind, ChatKind::Secret { .. }),
                                            |this| this.child(secret_badge(id)),
                                        ),
                                )
                                // Slice CL3: TGX draws counter, @ mention
                                // badge, and ♥ reaction badge
                                // right-to-left; the flex row renders
                                // them left-to-right in the same order.
                                .child(
                                    div()
                                        .flex()
                                        .items_center()
                                        .gap_1()
                                        .when(has_reactions, |this| {
                                            this.child(reaction_badge(id, chat.is_muted()))
                                        })
                                        .when(has_mentions, |this| this.child(mention_badge(id)))
                                        .when_some(badge, |this, label| {
                                            this.child(unread_badge(label, id))
                                        }),
                                ),
                        )
                        .child(
                            div()
                                .text_xs()
                                .text_color(cx.theme().muted_foreground)
                                .child(preview),
                        ),
                ),
        )
        .when(!tags.is_empty(), |this| {
            this.child(div().flex().flex_row().flex_wrap().gap_1().pt_1().children(
                tags.into_iter().map(|name| {
                    div()
                        .px_1()
                        .rounded_sm()
                        .bg(cx.theme().accent.opacity(0.12))
                        .text_xs()
                        .child(name)
                }),
            ))
        })
        // Slice CL2: pin-drag reorder — dropping a pinned chat onto
        // another pinned row moves it to that row's slot (TGX
        // `ChatsAdapter.movePinnedChat` sends the full reordered
        // pinned-id list via `setPinnedChats`).
        .when(draggable, |this| {
            let drag = PinnedChatDrag {
                chat_id: id,
                archived,
                title: drag_title.clone(),
            };
            let target = id;
            this.cursor_move()
                .on_drag(drag, |drag: &PinnedChatDrag, _, _, cx| {
                    cx.new(|_| drag.clone())
                })
                .on_drop(cx.listener(move |this, drag: &PinnedChatDrag, _, cx| {
                    this.drop_pinned_chat(drag.chat_id, drag.archived, target, cx);
                }))
        })
}

/// Slice CL2: drag payload for pinned-chat reorder. It renders itself
/// as the drag ghost (the chat title on a highlighted chip).
#[derive(Clone)]
struct PinnedChatDrag {
    chat_id: ChatId,
    archived: bool,
    title: String,
}

impl Render for PinnedChatDrag {
    fn render(&mut self, _window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        div()
            .px_3()
            .py_2()
            .rounded_md()
            .bg(cx.theme().accent.opacity(0.15))
            .border_1()
            .border_color(cx.theme().border)
            .text_sm()
            .font_medium()
            .child(self.title.clone())
    }
}

/// Slice CL2: the three `archiveChatListSettings` fields (schema
/// 1.8.67, line 3512) as (section title, toggle label, description),
/// in schema order. Labels mirror TGX
/// `SettingsArchiveChatListController`.
const ARCHIVE_SETTING_ROWS: [(&str, &str, &str); 3] = [
    (
        "Chats from unknown users",
        "Archive and Mute",
        "Automatically archive and mute new chats, groups and channels from non-contacts.",
    ),
    (
        "Unmuted chats",
        "Always keep archived",
        "Keep archived chats in the Archive even if they are unmuted and get a new message.",
    ),
    (
        "Chats from folders",
        "Always keep archived",
        "Keep archived chats from folders in the Archive even if they are unmuted and get a new message.",
    ),
];

/// Slice CL2: read one `archiveChatListSettings` field by schema-order
/// index.
fn archive_setting_get(settings: &ArchiveChatListSettings, index: usize) -> bool {
    match index {
        0 => settings.archive_and_mute_new_chats_from_unknown_users,
        1 => settings.keep_unmuted_chats_archived,
        2 => settings.keep_chats_from_folders_archived,
        _ => false,
    }
}

/// Slice CL2: write one `archiveChatListSettings` field by schema-order
/// index.
fn archive_setting_set(settings: &mut ArchiveChatListSettings, index: usize, value: bool) {
    match index {
        0 => settings.archive_and_mute_new_chats_from_unknown_users = value,
        1 => settings.keep_unmuted_chats_archived = value,
        2 => settings.keep_chats_from_folders_archived = value,
        _ => {}
    }
}

/// One `sponsoredMessage` row: Sponsored / Recommended label, title, content,
/// sponsor button, and a Report button when `can_be_reported` is set.
/// Media reuses the history attachment helpers, so thumbs download at
/// priority 1 and a tap fetches the full file at priority 32.
fn sponsored_message_row(
    chat_id: ChatId,
    message: &SponsoredMessage,
    files: &HashMap<i32, ParsedFile>,
    downloading: &std::collections::HashSet<i32>,
    failed: &std::collections::HashSet<i32>,
    media_roots: &[PathBuf],
    revealed: &std::collections::HashSet<(i64, u64, u64, bool)>,
    cx: &mut Context<QuillApp>,
) -> AnyElement {
    let row_id = message.message_id as u64;
    let header = div()
        .id(("sponsored-row-header", row_id))
        .flex()
        .items_center()
        .gap_2()
        .child(
            div()
                .id(("sponsored-row-label", row_id))
                .text_xs()
                .px_2()
                .py_1()
                .rounded_md()
                .bg(rgb(0x1f6feb))
                .text_color(rgb(0xffffff))
                .child(message.kind_label()),
        )
        .child(div().font_semibold().text_sm().child(message.title.clone()));
    let content: Option<AnyElement> = match &message.content {
        MessageContent::Text(text) => Some(message_text_block(
            (chat_id.0, row_id),
            text,
            files,
            downloading,
            media_roots,
            revealed,
            cx,
        )),
        MessageContent::Photo(photo) => Some(photo_attachment(
            row_id,
            photo,
            files,
            downloading,
            media_roots,
            Some((chat_id, message.message_id)),
            None,
            cx,
        )),
        MessageContent::Animation(animation) => Some(animation_attachment(
            MessageId(message.message_id),
            animation,
            files,
            downloading,
            media_roots,
            false,
            None,
            Some((chat_id, message.message_id)),
            cx,
        )),
        MessageContent::Video(video) => Some(video_attachment(
            MessageId(message.message_id),
            video,
            files,
            downloading,
            media_roots,
            false,
            None,
            Some((chat_id, message.message_id)),
            None,
            cx,
        )),
        MessageContent::Document(doc) => Some(document_chip(
            row_id,
            doc,
            files,
            downloading,
            failed,
            Some((chat_id, message.message_id)),
            cx,
        )),
        _ => None,
    };
    let mut row = div()
        .id(("sponsored-row", row_id))
        .flex()
        .flex_col()
        .gap_1()
        .px_3()
        .py_2()
        .rounded_lg()
        .border_1()
        .border_color(cx.theme().border)
        .bg(cx.theme().sidebar)
        .child(header);
    if let Some(content) = content {
        row = row.child(content);
    }
    if !message.sponsor.info.is_empty() {
        row = row.child(
            div()
                .text_xs()
                .text_color(cx.theme().muted_foreground)
                .child(message.sponsor.info.clone()),
        );
    }
    if !message.additional_info.is_empty() {
        row = row.child(
            div()
                .text_xs()
                .text_color(cx.theme().muted_foreground)
                .child(message.additional_info.clone()),
        );
    }
    let url = message.sponsor.url.clone();
    if !message.button_text.is_empty() && !url.is_empty() {
        let label = message.button_text.clone();
        let sponsored_id = message.message_id;
        row = row.child(
            Button::new(format!("sponsored-open-{row_id}"))
                .label(label)
                .on_click(cx.listener(move |this, _, _, cx| {
                    this.click_sponsored_message(chat_id, sponsored_id, false, cx);
                    this.open_message_url(&url, cx);
                })),
        );
    }
    if message.can_be_reported {
        let id = message.message_id;
        row = row.child(
            Button::new(format!("sponsored-report-{row_id}"))
                .label("Report")
                .ghost()
                .on_click(cx.listener(move |this, _, _, cx| {
                    this.report_sponsored_message_ui(chat_id, id, cx);
                })),
        );
    }
    row.into_any_element()
}

