fn album_history_row(
    album_id: i64,
    messages: &[&HistoryMessage],
    files: &HashMap<i32, ParsedFile>,
    downloading: &std::collections::HashSet<i32>,
    media_roots: &[PathBuf],
    chat: Option<&ChatSummary>,
    sender_name: &str,
    cx: &mut Context<QuillApp>,
) -> AnyElement {
    let Some(first) = messages.first() else {
        return div().into_any_element();
    };
    let sizes: Vec<(i32, i32)> = messages
        .iter()
        .map(|message| quill::album::album_pixel_size(&message.content))
        .collect();
    let layout = quill::album::layout_media_group(
        &sizes,
        quill::album::ALBUM_MAX_WIDTH,
        quill::album::ALBUM_MIN_WIDTH,
        quill::album::ALBUM_SPACING,
    );
    let (box_w, box_h) = quill::album::layout_bounds(&layout);
    let mut mosaic = div()
        .id(("album", album_id as u64))
        .relative()
        .w(px(box_w as f32))
        .h(px(box_h as f32))
        .overflow_hidden()
        .rounded_md();
    for (index, message) in messages.iter().enumerate() {
        let Some(part) = layout.get(index) else {
            continue;
        };
        let tile = album_tile(message, part, files, downloading, media_roots, cx);
        mosaic = mosaic.child(tile);
    }
    let caption = messages.iter().rev().find_map(|message| {
        let text = match &message.content {
            MessageContent::Photo(photo) => photo.caption.clone(),
            MessageContent::Video(video) => video.caption.clone(),
            _ => String::new(),
        };
        if text.is_empty() { None } else { Some(text) }
    });
    let label = if first.is_outgoing {
        let receipt = chat
            .map(|summary| summary.outbox_receipt(first))
            .unwrap_or(OutboxReceipt::Sent);
        outgoing_status_label(first.pending, receipt).to_string()
    } else {
        sender_name.to_string()
    };
    let reply_target = ComposerReplyTo::new(
        first.chat_id,
        first.id,
        caption.clone().unwrap_or_else(|| "Album".into()),
    );
    let reply_btn = Button::new(format!("reply-album-{}", album_id))
        .label("Reply")
        .ghost()
        .on_click(cx.listener(move |this, _, window, cx| {
            this.begin_reply_to(reply_target.clone(), window, cx);
        }));
    let extra = div()
        .id(("album-extra", album_id as u64))
        .flex()
        .flex_col()
        .gap_1()
        .child(mosaic)
        .when_some(caption, |this, text| {
            this.child(div().text_sm().child(text))
        })
        .child(reply_btn)
        .into_any_element();
    session_bubble_quoted(
        album_id as u64,
        label,
        String::new(),
        first.is_outgoing,
        Some(extra),
        None,
    )
}

fn album_tile(
    message: &HistoryMessage,
    part: &quill::album::AlbumRect,
    files: &HashMap<i32, ParsedFile>,
    downloading: &std::collections::HashSet<i32>,
    media_roots: &[PathBuf],
    cx: &mut Context<QuillApp>,
) -> AnyElement {
    let row_id = message.id.0 as u64;
    let chat_id = message.chat_id;
    let message_id = message.id;
    // Parity slice 5: tiles open the fullscreen media viewer. The Play
    // button inside video tiles keeps its history-row playback — the
    // component button stops propagation on mouse-down, so the tile click
    // never double-fires.
    let frame = div()
        .id(("album-tile", row_id))
        .absolute()
        .left(px(part.x as f32))
        .top(px(part.y as f32))
        .w(px(part.width as f32))
        .h(px(part.height as f32))
        .overflow_hidden()
        .cursor_pointer()
        .on_click(cx.listener(move |this, _, _, cx| {
            this.open_media_viewer(chat_id, message_id, cx);
        }));
    match &message.content {
        MessageContent::Photo(photo) => {
            if let Some(path) = photo_display_path(photo, files, media_roots) {
                frame
                    .child(
                        img(path)
                            .id(("album-photo", row_id))
                            .w(px(part.width as f32))
                            .h(px(part.height as f32))
                            .object_fit(ObjectFit::Cover)
                            .with_fallback(|| {
                                div()
                                    .size_full()
                                    .bg(rgb(0x444c56))
                                    .flex()
                                    .items_center()
                                    .justify_center()
                                    .child("Photo")
                                    .into_any_element()
                            }),
                    )
                    .into_any_element()
            } else {
                let open_id = photo.open_file_id().unwrap_or(FileId(0));
                let downloading_now = file_is_downloading(open_id, files, downloading);
                frame
                    .bg(rgb(0x444c56))
                    .flex()
                    .items_center()
                    .justify_center()
                    .child(
                        div()
                            .text_xs()
                            .text_color(rgb(0xffffff))
                            .child(if downloading_now {
                                "Photo — downloading…"
                            } else {
                                "Photo"
                            }),
                    )
                    .into_any_element()
            }
        }
        MessageContent::Video(video) => {
            let play_id = video.play_file_id().unwrap_or(FileId(0));
            let thumb_id = video.thumb_file_id().unwrap_or(FileId(0));
            let mime = video.mime_type.clone();
            let start_timestamp = video.start_timestamp;
            let message_id = message.id;
            let visual = [thumb_id, play_id].into_iter().find_map(|id| {
                if id.0 == 0 {
                    return None;
                }
                files
                    .get(&id.0)
                    .and_then(|file| file.usable_path())
                    .and_then(|path| sandboxed_display_path(path, media_roots))
            });
            let duration = format_voice_duration(video.duration);
            let picture = if let Some(path) = visual {
                img(path)
                    .id(("album-video", row_id))
                    .w(px(part.width as f32))
                    .h(px(part.height as f32))
                    .object_fit(ObjectFit::Cover)
                    .with_fallback(|| div().size_full().bg(rgb(0x238636)).into_any_element())
                    .into_any_element()
            } else {
                div()
                    .size_full()
                    .bg(rgb(0x238636))
                    .flex()
                    .items_center()
                    .justify_center()
                    .child(div().text_xs().text_color(rgb(0xffffff)).child("Video"))
                    .into_any_element()
            };
            frame
                .child(picture)
                .child(
                    div()
                        .absolute()
                        .bottom(px(4.))
                        .left(px(4.))
                        .px_1()
                        .rounded_sm()
                        .bg(rgb(0x010409))
                        .text_xs()
                        .text_color(rgb(0xffffff))
                        .child(format!("Video · {duration}")),
                )
                .child(
                    Button::new(format!("album-play-{row_id}"))
                        .label("Play")
                        .ghost()
                        .on_click(cx.listener(move |this, _, _, cx| {
                            this.toggle_video_playback(
                                message_id,
                                play_id,
                                mime.clone(),
                                start_timestamp,
                                None,
                                cx,
                            );
                        })),
                )
                .into_any_element()
        }
        _ => frame.into_any_element(),
    }
}

/// Compact view-count formatting for broadcast posts (`👁 1.2K`, `👁 3.4M`).
fn format_view_count(count: i32) -> String {
    if count >= 1_000_000 {
        format!("{:.1}M", count as f64 / 1_000_000.0)
    } else if count >= 1_000 {
        format!("{:.1}K", count as f64 / 1_000.0)
    } else {
        count.to_string()
    }
}

/// Phase D2: compact formatting for `statisticalValue` counts (f64).
fn format_stat_count(value: f64) -> String {
    if value >= 1_000_000.0 {
        format!("{:.1}M", value / 1_000_000.0)
    } else if value >= 1_000.0 {
        format!("{:.1}K", value / 1_000.0)
    } else if value.fract() == 0.0 {
        format!("{}", value as i64)
    } else if value >= 100.0 {
        format!("{:.0}", value)
    } else {
        format!("{:.1}", value)
    }
}

/// Phase D2: one statistics row — muted label, value with growth vs the
/// previous period, e.g. "12.4K (+5.6%)".
fn stats_value_row(label: &str, value: &StatisticalValue) -> Div {
    div()
        .flex()
        .flex_row()
        .justify_between()
        .gap_2()
        .child(
            div()
                .text_sm()
                .text_color(rgb(0x8b949e))
                .child(label.to_string()),
        )
        .child(div().text_sm().child(format!(
            "{} ({:+.1}%)",
            format_stat_count(value.value),
            value.growth_rate_percentage
        )))
}

/// Phase D2: "Sep 19" from a unix timestamp (TDLib `dateRange`), UTC.
fn format_statistics_day(unix: i32) -> String {
    const MONTHS: [&str; 12] = [
        "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
    ];
    // Howard Hinnant's civil_from_days, epoch-shifted to 1970-01-01.
    let days = (unix as i64).div_euclid(86400);
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    format!("{} {d}", MONTHS[(m - 1) as usize])
}

/// Phase D2: trend sparkline from a `statisticalGraphData` `json_data`
/// payload. TDLib graph JSON:
/// `{"columns":[["x",t1,...],["y0",v1,...],...],"types":{"x":"x","y0":"line"}}`.
/// Takes the first non-"x" numeric column. `None` when there is no usable
/// series — the graph row is then omitted, never a placeholder.
fn sparkline_from_graph_json(json_data: &str) -> Option<String> {
    const BLOCKS: [char; 8] = ['▁', '▂', '▃', '▄', '▅', '▆', '▇', '█'];
    let parsed: serde_json::Value = serde_json::from_str(json_data).ok()?;
    let columns = parsed.get("columns")?.as_array()?;
    let series = columns.iter().find_map(|column| {
        let column = column.as_array()?;
        let name = column.first()?.as_str()?;
        if name == "x" {
            return None;
        }
        let values: Vec<f64> = column[1..].iter().filter_map(|v| v.as_f64()).collect();
        (!values.is_empty()).then_some(values)
    })?;
    let min = series.iter().copied().fold(f64::INFINITY, f64::min);
    let max = series.iter().copied().fold(f64::NEG_INFINITY, f64::max);
    let span = (max - min).max(f64::EPSILON);
    Some(
        series
            .iter()
            .map(|value| {
                let level = ((value - min) / span * 7.0).round() as usize;
                BLOCKS[level.min(7)]
            })
            .collect(),
    )
}

/// Phase D2: one labeled graph row. `Data` with a usable series renders a
/// sparkline; `Async` is still processing server-side; `Error` shows the
/// server text; a `Data` payload without a usable series is omitted
/// (`None`).
fn stats_graph_row(
    label: &str,
    graph: &StatisticalGraph,
    cx: &mut Context<QuillApp>,
) -> Option<Div> {
    let status: Option<String> = match graph {
        StatisticalGraph::Data {
            json_data,
            zoom_token: _,
        } => {
            return sparkline_from_graph_json(json_data).map(|spark| {
                div()
                    .flex()
                    .flex_row()
                    .justify_between()
                    .gap_2()
                    .child(
                        div()
                            .text_sm()
                            .text_color(rgb(0x8b949e))
                            .child(label.to_string()),
                    )
                    .child(div().text_xs().child(spark))
            });
        }
        StatisticalGraph::Async { token: _ } => {
            Some("Still processing — check back later.".to_string())
        }
        StatisticalGraph::Error { error_message } => Some(format!("Graph error: {error_message}")),
    };
    status.map(|text| {
        div()
            .flex()
            .flex_row()
            .justify_between()
            .gap_2()
            .child(
                div()
                    .text_sm()
                    .text_color(rgb(0x8b949e))
                    .child(label.to_string()),
            )
            .child(
                div()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child(text),
            )
    })
}

/// Phase 3.2: render `replyMarkupInlineKeyboard` as a button grid under the
/// message it belongs to. Parsing is generic (bot chats, groups, channels
/// all inherit it). Buttons stretch to share each row's width, like Telegram
/// desktop; empty rows are skipped.
fn inline_keyboard(message: &HistoryMessage, cx: &mut Context<QuillApp>) -> Option<AnyElement> {
    // M2: an ephemeral payload carries its own `reply_markup`, shown
    // instead of the message's own (bot-built flows, anniversary post).
    let markup = message
        .ephemeral
        .as_ref()
        .and_then(|ephemeral| ephemeral.reply_markup.as_ref())
        .or(message.reply_markup.as_ref())?;
    // B1: only `replyMarkupInlineKeyboard` renders as an inline keyboard;
    // other markups (custom keyboards, force-reply) are handled separately.
    let ReplyMarkup::InlineKeyboard(keyboard) = markup else {
        return None;
    };
    // B1: game buttons need the game's short name from the message's
    // `messageGame` content (schema 1.8.67, line 7743).
    let game_short_name = if let MessageContent::Game { short_name } = &message.content {
        Some(short_name.as_str())
    } else {
        None
    };
    let message_id = message.id.0 as u64;
    let mut grid = div()
        .id(("inline-keyboard", message_id))
        .flex()
        .flex_col()
        .gap_1()
        .mt_2();
    let mut any = false;
    for (row_index, row) in keyboard.rows.iter().enumerate() {
        if row.is_empty() {
            continue;
        }
        any = true;
        let mut line = div()
            .id(format!("inline-keyboard-row-{message_id}-{row_index}"))
            .flex()
            .gap_1();
        for (button_index, button) in row.iter().enumerate() {
            line = line.child(
                inline_keyboard_button(
                    message.chat_id,
                    message.id,
                    row_index,
                    button_index,
                    button,
                    game_short_name,
                    cx,
                )
                .flex_1(),
            );
        }
        grid = grid.child(line);
    }
    any.then(|| grid.into_any_element())
}

/// Phase 3.2 (extended in B1): one inline keyboard button. `Url` opens in
/// the OS browser (same gate as URLs in message text); `LoginUrl` resolves
/// via `getLoginUrlInfo` (TDLib 1.8.67, schema:12985), degrading to the raw
/// URL on error; `WebApp` opens in the browser (honest fallback — no
/// in-app web view yet); `Callback` sends `getCallbackQueryAnswer`;
/// `CallbackWithPassword` prompts for the 2-step password and sends
/// `callbackQueryPayloadDataWithPassword` (schema:7740); `CallbackGame`
/// sends `callbackQueryPayloadGame` with the message's `messageGame`
/// short name (schema:7743); `User` opens the private chat with the user;
/// `SwitchInline` inserts the query into the current chat's composer;
/// `CopyText` copies to the clipboard. `Buy` stays disabled — payments are
/// a later slice; unknown types never crash.
fn inline_keyboard_button(
    chat_id: ChatId,
    message_id: MessageId,
    row_index: usize,
    button_index: usize,
    button: &InlineKeyboardButton,
    game_short_name: Option<&str>,
    cx: &mut Context<QuillApp>,
) -> Button {
    let label = if button.text.is_empty() {
        match &button.kind {
            InlineKeyboardButtonType::Unknown { type_name } if !type_name.is_empty() => {
                format!("({type_name})")
            }
            _ => "(button)".to_string(),
        }
    } else {
        button.text.clone()
    };
    let element = Button::new(format!(
        "inline-btn-{}-{row_index}-{button_index}",
        message_id.0
    ))
    .label(label)
    .tooltip(button_tooltip(button));
    let element = match button.style {
        InlineKeyboardButtonStyle::Primary => element.primary(),
        InlineKeyboardButtonStyle::Danger => element.danger(),
        InlineKeyboardButtonStyle::Success => element.success(),
        InlineKeyboardButtonStyle::Link => element.link(),
        InlineKeyboardButtonStyle::Default => element.ghost(),
    };
    match &button.kind {
        InlineKeyboardButtonType::Url { url } => {
            let url = url.clone();
            element.on_click(cx.listener(move |this, _, _, cx| {
                this.open_message_url(&url, cx);
            }))
        }
        InlineKeyboardButtonType::LoginUrl { url, id } => {
            let url = url.clone();
            let button_id = *id;
            element.on_click(cx.listener(move |this, _, _, cx| {
                this.press_login_url(chat_id, message_id, button_id, &url, cx);
            }))
        }
        InlineKeyboardButtonType::WebApp { url } => {
            let url = url.clone();
            element.on_click(cx.listener(move |this, _, _, cx| {
                this.open_message_url(&url, cx);
            }))
        }
        InlineKeyboardButtonType::Callback { data } => {
            let data = data.clone();
            element.on_click(cx.listener(move |this, _, _, cx| {
                this.press_inline_callback(chat_id, message_id, data.clone(), cx);
            }))
        }
        InlineKeyboardButtonType::CallbackWithPassword { data } => {
            let data = data.clone();
            element.on_click(cx.listener(move |this, _, window, cx| {
                this.open_callback_password_dialog(chat_id, message_id, data.clone(), window, cx);
            }))
        }
        InlineKeyboardButtonType::CallbackGame => {
            let game_short_name = game_short_name.map(str::to_string);
            element.on_click(cx.listener(move |this, _, _, cx| {
                this.press_game_button(chat_id, message_id, game_short_name.clone(), cx);
            }))
        }
        InlineKeyboardButtonType::User { user_id } => {
            let user_id = *user_id;
            element.on_click(cx.listener(move |this, _, window, cx| {
                this.open_user_chat(user_id, window, cx);
            }))
        }
        InlineKeyboardButtonType::SwitchInline { query, .. } => {
            let query = query.clone();
            element.on_click(cx.listener(move |this, _, window, cx| {
                this.insert_switch_inline_query(&query, window, cx);
            }))
        }
        InlineKeyboardButtonType::CopyText { text } => {
            let text = text.clone();
            element.on_click(cx.listener(move |this, _, _, cx| {
                this.copy_inline_text(&text, cx);
            }))
        }
        _ => element.disabled(true),
    }
}

/// Short hint for unsupported / unknown inline buttons.
fn button_tooltip(button: &InlineKeyboardButton) -> &'static str {
    match &button.kind {
        InlineKeyboardButtonType::Url { .. }
        | InlineKeyboardButtonType::LoginUrl { .. }
        | InlineKeyboardButtonType::WebApp { .. }
        | InlineKeyboardButtonType::Callback { .. }
        | InlineKeyboardButtonType::CallbackWithPassword { .. }
        | InlineKeyboardButtonType::CallbackGame
        | InlineKeyboardButtonType::SwitchInline { .. }
        | InlineKeyboardButtonType::CopyText { .. }
        | InlineKeyboardButtonType::User { .. } => "",
        InlineKeyboardButtonType::Buy => "Payment buttons are not supported yet (payments slice)",
        InlineKeyboardButtonType::Disabled => "This button is disabled",
        InlineKeyboardButtonType::Unknown { .. } => "Unsupported button",
    }
}

/// Phase 4.2: `messagePoll` row — the question, one tappable option row per
/// option with a percentage bar and voter count, chosen option(s) marked;
/// closed polls render results without voting affordance. Vote taps go
/// through `setPollAnswer` (`QuillApp::vote_on_poll`); counts refresh live
/// via `updatePoll`.
fn poll_body(
    chat_id: ChatId,
    message_id: MessageId,
    content: &PollContent,
    cx: &mut Context<QuillApp>,
) -> AnyElement {
    let poll = &content.poll;
    let kind_label = match &poll.poll_type {
        PollType::Quiz { .. } => "Quiz",
        PollType::Regular => "Poll",
    };
    let mut body = div()
        .id(("poll", message_id.0 as u64))
        .flex()
        .flex_col()
        .gap_1()
        .mt_1()
        .child(div().text_sm().font_semibold().child(poll.question.clone()));
    if !content.description.is_empty() {
        body = body.child(
            div()
                .text_xs()
                .text_color(rgb(0x8b949e))
                .child(content.description.clone()),
        );
    }
    body = body.child(div().text_xs().text_color(rgb(0x8b949e)).child(format!(
        "{} · {} · {}",
        kind_label,
        voter_count_label(poll.total_voter_count),
        if poll.is_closed {
            "closed"
        } else if poll.is_anonymous {
            "anonymous"
        } else {
            "public"
        },
    )));
    for (index, option) in poll.options.iter().enumerate() {
        body = body.child(poll_option_row(
            chat_id, message_id, index, option, poll, cx,
        ));
    }
    body.into_any_element()
}

/// One poll option: text + percentage, a bar split by `flex_grow`
/// (no percentage widths in GPUI), the per-option voter count, and the
/// chosen / quiz-correct marks. Tappable while the poll is open.
fn poll_option_row(
    chat_id: ChatId,
    message_id: MessageId,
    index: usize,
    option: &PollOption,
    poll: &quill::telegram::Poll,
    cx: &mut Context<QuillApp>,
) -> AnyElement {
    let fill = poll_bar_fraction(option.vote_percentage);
    let chosen = option.is_chosen;
    let votable = poll.can_vote();
    let quiz_correct = poll.is_closed
        && matches!(&poll.poll_type, PollType::Quiz { correct_option_ids }
            if correct_option_ids.contains(&(index as i32)));
    let option_label = if chosen {
        format!("✓ {}", option.text)
    } else {
        option.text.clone()
    };
    let option_label = if quiz_correct {
        format!("{option_label} · correct answer")
    } else {
        option_label
    };
    let stats = if option.voter_count > 0 {
        format!(
            "{}% · {} {}",
            option.vote_percentage,
            option.voter_count,
            if option.voter_count == 1 {
                "vote"
            } else {
                "votes"
            },
        )
    } else {
        format!("{}%", option.vote_percentage)
    };
    let mut row = div()
        .id(("poll-option", message_id.0 as u64 * 64 + index as u64))
        .flex()
        .flex_col()
        .gap_0p5()
        .px_3()
        .py_1p5()
        .rounded_md()
        .border_1()
        .border_color(if chosen { rgb(0x58a6ff) } else { rgb(0x30363d) })
        .bg(rgb(0x161b22))
        .child(
            div()
                .flex()
                .items_center()
                .justify_between()
                .child(
                    div()
                        .text_sm()
                        .text_color(if quiz_correct {
                            rgb(0x3fb950)
                        } else {
                            rgb(0xe6edf3)
                        })
                        .child(option_label),
                )
                .child(div().text_sm().text_color(rgb(0x8b949e)).child(stats)),
        )
        .child(
            div()
                .flex()
                .flex_row()
                .h(px(6.))
                .rounded_md()
                .overflow_hidden()
                .bg(rgb(0x0d1117))
                .child(
                    div()
                        .flex_grow(fill)
                        .bg(if chosen { rgb(0x1f6feb) } else { rgb(0x30363d) }),
                )
                .child(div().flex_grow(1.0 - fill)),
        );
    if votable {
        row = row
            .cursor_pointer()
            .on_click(cx.listener(move |this, _, _, cx| {
                this.vote_on_poll(chat_id, message_id, index, cx);
            }));
    }
    row.into_any_element()
}

/// Phase C2i: the peer (user id + display name) of a call entry,
/// when the call message is in a 1:1 chat. Group calls have no single
/// peer — `None` hides "Call again".
fn call_message_peer(session: Option<&Session>, chat_id: ChatId) -> Option<(i64, String)> {
    let session = session?;
    let chat = session.chats.get(&chat_id.0)?;
    let user_id = match chat.kind {
        ChatKind::Private { user_id } | ChatKind::Secret { user_id, .. } => user_id.0,
        _ => return None,
    };
    let name = session
        .user(user_id)
        .map(|user| user.display_name())
        .unwrap_or_else(|| format!("User {user_id}"));
    Some((user_id, name))
}

/// MED4: `show_caption_above_media` (TDLib 1.8.67, `schema/td_api.tl:6117`
/// photo / `:6128` video / animation). Documents / audio / voice notes
/// have no such field — their captions always render below.
fn caption_above_media(content: &MessageContent) -> bool {
    match content {
        MessageContent::Photo(photo) => photo.show_caption_above_media,
        MessageContent::Video(video) => video.show_caption_above_media,
        MessageContent::Animation(animation) => animation.show_caption_above_media,
        _ => false,
    }
}

fn session_history_row(
    message: &HistoryMessage,
    files: &HashMap<i32, ParsedFile>,
    downloading: &std::collections::HashSet<i32>,
    failed: &std::collections::HashSet<i32>,
    media_roots: &[PathBuf],
    label: String,
    quote_preview: Option<String>,
    forward_from: Option<String>,
    selected_forward: bool,
    reaction_open: bool,
    // Seek-bar view for audio/voice rows (`None` for other content).
    seek_bar: Option<SeekBarView>,
    animation_playing: bool,
    animation_frame: Option<PathBuf>,
    video_playing: bool,
    video_frame: Option<PathBuf>,
    revealed: &std::collections::HashSet<(i64, u64, u64, bool)>,
    // Phase B4: whether the row's chat is a secret chat — selects the
    // "Self-destruct" vs "Auto-delete" service-row wording.
    is_secret: bool,
    // Phase C2i: session for `messageCall` peer resolution ("Call
    // again" only for 1:1 chats).
    session: Option<&Session>,
    cx: &mut Context<QuillApp>,
) -> AnyElement {
    // Phase B4: timer-change service rows (`messageChatSetMessageAutoDeleteTime`,
    // schema 1.8.67 line 5387) render as a centered neutral notice — no
    // bubble, no reply/react/edit/delete controls.
    if let MessageContent::ChatTtlChanged { secs } = &message.content {
        return div()
            .id(("ttl-service-row", message.id.0 as u64))
            .flex()
            .justify_center()
            .py_1()
            .child(
                div()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child(chat_ttl_service_label(*secs, is_secret)),
            )
            .into_any_element();
    }
    // Phase S1: `messageScreenshotTaken` service row (schema 1.8.67,
    // line 5375) — centered neutral notice, attributed via
    // `message.is_outgoing` (TGX `YouTookAScreenshot` /
    // `XTookAScreenshot`).
    if matches!(message.content, MessageContent::ScreenshotTaken) {
        let text = if message.is_outgoing {
            "You took a screenshot".to_string()
        } else {
            format!("{label} took a screenshot")
        };
        return div()
            .id(("screenshot-service-row", message.id.0 as u64))
            .flex()
            .justify_center()
            .py_1()
            .child(
                div()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child(text),
            )
            .into_any_element();
    }
    // Phase C2f: `messageGroupCall` invitation service row (schema
    // 1.8.67, line 5288) — incoming and pending: Accept / Decline.
    if let MessageContent::GroupCallInvitation {
        is_active,
        was_missed,
        is_video,
        ..
    } = &message.content
    {
        return QuillApp::group_call_invitation_row(
            message,
            *is_active,
            *was_missed,
            *is_video,
            cx,
        )
        .into_any_element();
    }
    // Phase C2i: `messageCall` service row (schema 1.8.67, line 5277)
    // — reason-aware label + "Call again" for 1:1 chats.
    if let MessageContent::Call {
        is_video,
        discard_reason,
        duration,
    } = &message.content
    {
        return QuillApp::call_message_row(
            message,
            *is_video,
            discard_reason,
            *duration,
            session,
            cx,
        )
        .into_any_element();
    }
    let quote = message.reply_to.as_ref().and_then(|reply| {
        let preview = quote_preview.clone()?;
        Some(reply_quote_strip(message.id, reply.message_id, preview, cx))
    });
    let forward_strip = forward_from.map(|label| forward_from_strip(message.id, label));
    let header = match (forward_strip, quote) {
        (Some(fwd), Some(reply)) => Some(
            div()
                .id(("row-headers", message.id.0 as u64))
                .flex()
                .flex_col()
                .child(fwd)
                .child(reply)
                .into_any_element(),
        ),
        (Some(fwd), None) => Some(fwd),
        (None, Some(reply)) => Some(reply),
        (None, None) => None,
    };
    let reply_id = format!("reply-{}", message.id.0);
    let reply_target =
        ComposerReplyTo::new(message.chat_id, message.id, effective_preview(message));
    let reply_btn = Button::new(reply_id)
        .label("Reply")
        .ghost()
        .on_click(cx.listener(move |this, _, window, cx| {
            this.begin_reply_to(reply_target.clone(), window, cx);
        }));
    let chat_id = message.chat_id;
    let message_id = message.id;
    let pending = message.pending;
    // Phase S1: TGX only offers Forward when
    // `messageProperties.canBeForwarded` (`MessagesController.java:5287`);
    // TDLib sets it false for secret-chat messages — the chat kind is the
    // faithful equivalent here.
    let forward_btn = (!is_secret)
        .then(|| ForwardDraft::from_message(chat_id, message_id, pending))
        .flatten()
        .map(|_| {
            Button::new(format!("forward-{}", message_id.0))
                .label("Forward")
                .ghost()
                .on_click(cx.listener(move |this, _, window, cx| {
                    this.begin_forward_one(chat_id, message_id, pending, window, cx);
                }))
        });
    let select_btn = (!is_secret)
        .then(|| ForwardDraft::from_message(chat_id, message_id, pending))
        .flatten()
        .map(|_| {
            Button::new(format!("select-forward-{}", message_id.0))
                .label(if selected_forward {
                    "Selected"
                } else {
                    "Select"
                })
                .ghost()
                .on_click(cx.listener(move |this, _, _, cx| {
                    this.toggle_forward_select(chat_id, message_id, pending, cx);
                }))
        });
    let edit_btn = ComposerEdit::from_own_content(
        message.chat_id,
        message.id,
        message.is_outgoing,
        message.pending,
        &message.content,
    )
    .map(|edit| {
        Button::new(format!("edit-{}", message.id.0))
            .label("Edit")
            .ghost()
            .on_click(cx.listener(move |this, _, window, cx| {
                this.begin_edit(edit.clone(), window, cx);
            }))
    });
    let delete_btn = DeleteConfirm::own(
        message.chat_id,
        message.id,
        message.is_outgoing,
        message.pending,
    )
    .map(|confirm| {
        Button::new(format!("delete-{}", message.id.0))
            .label("Delete")
            .ghost()
            .on_click(cx.listener(move |this, _, _, cx| {
                this.begin_delete(confirm.clone(), cx);
            }))
    });
    let react_btn = message.can_react().then(|| {
        Button::new(format!("react-{}", message_id.0))
            .label(if reaction_open { "Reacting" } else { "React" })
            .ghost()
            .on_click(cx.listener(move |this, _, _, cx| {
                if this
                    .pending_react
                    .is_some_and(|(chat, id)| chat == chat_id && id == message_id)
                {
                    this.close_reaction_picker(cx);
                } else {
                    this.open_reaction_picker(chat_id, message_id, cx);
                }
            }))
    });
    let pin_btn = message.can_pin().then(|| {
        let pinned = message.is_pinned;
        Button::new(format!("pin-{}", message_id.0))
            .label(if pinned { "Unpin" } else { "Pin" })
            .ghost()
            .on_click(cx.listener(move |this, _, _, cx| {
                this.toggle_pin_message(chat_id, message_id, cx);
            }))
    });
    // Broadcast posts (Phase 2.2): eye glyph + compact view count, like the
    // official clients' post footer. Renders whenever views exist; only
    // channel posts carry a view count in practice.
    let views_footer = message
        .interaction_info
        .as_ref()
        .map(|info| info.view_count)
        .filter(|&count| count > 0)
        .map(|count| {
            div()
                .id(("row-views", message_id.0 as u64))
                .mt_1()
                .text_xs()
                .opacity(0.75)
                .child(format!("👁 {}", format_view_count(count)))
        });
    // Phase D2: author signature (`message.author_signature`, schema 1.8.67
    // lines 3155/3165). The official clients show it under channel posts
    // and anonymous admin messages. Suppressed when the message is
    // forwarded — `forward_from_strip` already attributes the signature
    // there, and a second line would double-attribute.
    let author_signature_line = message
        .author_signature
        .as_ref()
        .filter(|_| message.forward_info.is_none())
        .map(|signature| {
            div()
                .id(("row-signature", message_id.0 as u64))
                .mt_1()
                .text_xs()
                .text_color(cx.theme().muted_foreground)
                .child(signature.clone())
        });
    let chips = message.emoji_reaction_chips();
    let chip_row = (!chips.is_empty()).then(|| {
        let mut row = div()
            .id(("reaction-chips", message_id.0 as u64))
            .flex()
            .flex_wrap()
            .gap_1()
            .mt_1();
        for (index, chip) in chips.into_iter().enumerate() {
            let Some(label) = chip.chip_label() else {
                continue;
            };
            let emoji = chip.reaction_type.emoji_text().unwrap_or("").to_string();
            let chosen = chip.is_chosen;
            row = row.child(
                div()
                    .id(("reaction-chip", message_id.0 as u64 * 64 + index as u64))
                    .px_2()
                    .py_1()
                    .rounded_md()
                    .text_xs()
                    .cursor_pointer()
                    .when(chosen, |this| {
                        this.bg(rgb(0x1f6feb))
                            .text_color(rgb(0xffffff))
                            .border_1()
                            .border_color(rgb(0x58a6ff))
                    })
                    .when(!chosen, |this| {
                        this.bg(rgb(0x21262d))
                            .text_color(rgb(0xc9d1d9))
                            .border_1()
                            .border_color(rgb(0x8b949e))
                    })
                    .on_click(cx.listener(move |this, _, _, cx| {
                        this.toggle_emoji_reaction(chat_id, message_id, emoji.clone(), cx);
                    }))
                    .child(label),
            );
        }
        row
    });
    // M2: ephemeral content replaces the regular content for rendering
    // (bot-built flows show the ephemeral variant to the current user).
    let text_body = match effective_content(&message.content, message.ephemeral.as_ref()) {
        MessageContent::Text(text) => Some(message_text_block(
            (message.chat_id.0, message.id.0 as u64),
            text,
            files,
            downloading,
            media_roots,
            revealed,
            cx,
        )),
        _ => None,
    };
    let extra_media = match effective_content(&message.content, message.ephemeral.as_ref()) {
        MessageContent::Photo(photo) => Some(photo_attachment(
            message.id.0 as u64,
            photo,
            files,
            downloading,
            media_roots,
            None,
            Some((message.chat_id, message.id)),
            cx,
        )),
        MessageContent::Document(doc) => Some(document_chip(
            message.id.0 as u64,
            doc,
            files,
            downloading,
            failed,
            None,
            cx,
        )),
        MessageContent::Sticker(sticker) => Some(sticker_attachment(
            message.id.0 as u64,
            sticker,
            files,
            downloading,
            media_roots,
            cx,
        )),
        MessageContent::VoiceNote(note) => Some(voice_note_row(
            message.chat_id,
            message.id,
            message.is_outgoing,
            note,
            files,
            downloading,
            seek_bar.as_ref().expect("voice row always has a seek view"),
            cx,
        )),
        MessageContent::Audio(audio) => Some(audio_row(
            message.id,
            audio,
            files,
            downloading,
            media_roots,
            seek_bar.as_ref().expect("audio row always has a seek view"),
            cx,
        )),
        MessageContent::Animation(animation) => Some(animation_attachment(
            message.id,
            animation,
            files,
            downloading,
            media_roots,
            animation_playing,
            animation_frame.as_deref(),
            None,
            cx,
        )),
        MessageContent::Video(video) => Some(video_attachment(
            message.id,
            video,
            files,
            downloading,
            media_roots,
            video_playing,
            video_frame.as_deref(),
            None,
            Some((message.chat_id, message.id)),
            cx,
        )),
        MessageContent::VideoNote(note) => Some(video_note_attachment(
            message.chat_id,
            message.id,
            message.is_outgoing,
            note,
            files,
            downloading,
            media_roots,
            video_playing,
            video_frame.as_deref(),
            cx,
        )),
        MessageContent::Poll(poll) => Some(poll_body(message.chat_id, message.id, poll, cx)),
        MessageContent::Location(location) => Some(location_row(
            message.id.0 as u64,
            &location.location,
            location.live.as_ref(),
            cx,
        )),
        MessageContent::Venue(venue) => Some(venue_row(message.id.0 as u64, venue, cx)),
        MessageContent::Contact(contact) => Some(contact_row(message.id.0 as u64, contact)),
        MessageContent::Dice(dice) => Some(dice_row(message.id.0 as u64, dice)),
        MessageContent::Text(_)
        | MessageContent::RichMessage(_)
        | MessageContent::Game { .. }
        | MessageContent::GroupCallInvitation { .. }
        | MessageContent::Call { .. }
        | MessageContent::ChatTtlChanged { .. }
        | MessageContent::ScreenshotTaken
        | MessageContent::Unsupported { .. } => None,
    };
    let keyboard = inline_keyboard(message, cx);
    // Phase B3: self-destruct timer badge (`message.self_destruct_type` /
    // `message.self_destruct_in`, schema 1.8.67 lines 3146–3147). The
    // countdown decays locally against `unix_ms_now()` (same pattern as
    // the Phase A1 slow-mode countdown); TDLib removes the row via
    // `updateDeleteMessages` when the timer fires. The 1-second render
    // tick (see `ensure_self_destruct_tick`) keeps this fresh.
    let self_destruct_badge = message.self_destruct_badge(unix_ms_now()).map(|label| {
        div()
            .id(("self-destruct-badge", message.id.0 as u64))
            .mt_1()
            .text_xs()
            .text_color(rgb(0xffd479))
            .child(label)
    });
    // Phase B4: auto-delete countdown chip (`message.auto_delete_in`,
    // schema 1.8.67 line 3148) — "🗑 59m left", decaying on the same
    // 1-second tick as the self-destruct badge.
    let auto_delete_chip = message.auto_delete_chip(unix_ms_now()).map(|label| {
        div()
            .id(("auto-delete-chip", message.id.0 as u64))
            .mt_1()
            .text_xs()
            .text_color(rgb(0xffd479))
            .child(label)
    });
    // MED4: caption element + position (`show_caption_above_media`,
    // schema 1.8.67 lines 6117/6128). Above → bubble body; below →
    // inside `extra` right after the media (the previous code always
    // rendered the caption above the media).
    let caption_above_el: Option<AnyElement>;
    let caption_below_el: Option<AnyElement>;
    {
        let caption: Option<(&str, &[TextEntity])> = match &message.content {
            MessageContent::Photo(photo) => (!photo.caption.is_empty())
                .then_some((photo.caption.as_str(), photo.caption_entities.as_slice())),
            MessageContent::Document(doc) => (!doc.caption.is_empty())
                .then_some((doc.caption.as_str(), doc.caption_entities.as_slice())),
            MessageContent::Animation(animation) => (!animation.caption.is_empty()).then_some((
                animation.caption.as_str(),
                animation.caption_entities.as_slice(),
            )),
            MessageContent::Video(video) => (!video.caption.is_empty())
                .then_some((video.caption.as_str(), video.caption_entities.as_slice())),
            MessageContent::VoiceNote(note) => (!note.caption.is_empty())
                .then_some((note.caption.as_str(), note.caption_entities.as_slice())),
            MessageContent::Audio(audio) => (!audio.caption.is_empty())
                .then_some((audio.caption.as_str(), audio.caption_entities.as_slice())),
            _ => None,
        };
        let el = caption.map(|(caption_text, caption_entities)| {
            rich_text_line(
                caption_text,
                caption_entities,
                (message.chat_id.0, message.id.0 as u64),
                true,
                revealed,
                cx,
            )
        });
        if caption_above_media(&message.content) {
            caption_above_el = el;
            caption_below_el = None;
        } else {
            caption_above_el = None;
            caption_below_el = el;
        }
    }
    let extra = Some(
        div()
            .id(("bubble-extra", message.id.0 as u64))
            .when_some(extra_media, |this, media| this.child(media))
            // MED4: caption below the media.
            .when_some(caption_below_el, |this, el| this.child(el))
            .when_some(self_destruct_badge, |this, badge| this.child(badge))
            .when_some(auto_delete_chip, |this, chip| this.child(chip))
            .when_some(keyboard, |this, keyboard| this.child(keyboard))
            .when_some(views_footer, |this, footer| this.child(footer))
            .when_some(author_signature_line, |this, line| this.child(line))
            .when_some(chip_row, |this, chips| this.child(chips))
            .child(
                div()
                    .flex()
                    .gap_2()
                    .child(reply_btn)
                    .when_some(react_btn, |this, btn| this.child(btn))
                    .when_some(pin_btn, |this, btn| this.child(btn))
                    .when_some(forward_btn, |this, btn| this.child(btn))
                    .when_some(select_btn, |this, btn| this.child(btn))
                    .when_some(edit_btn, |this, btn| this.child(btn))
                    .when_some(delete_btn, |this, btn| this.child(btn)),
            )
            .into_any_element(),
    );
    let unsupported_body = match &message.content {
        MessageContent::Unsupported { type_name } => format!("({type_name})"),
        _ => String::new(),
    };
    // M2: `messageRichMessage` (schema 1.8.67, line 5143) renders its
    // `pageBlock*` list as a block stack; ephemeral content wins here too.
    let rich_body = match effective_content(&message.content, message.ephemeral.as_ref()) {
        MessageContent::RichMessage(rich) => Some(message_rich_block(
            (message.chat_id.0, message.id.0 as u64),
            message.chat_id,
            message.id,
            rich,
            revealed,
            cx,
        )),
        _ => None,
    };
    if let Some(rich_body) = rich_body {
        return session_bubble_rich(
            message.id.0 as u64,
            label,
            message.is_outgoing,
            rich_body,
            extra,
            header,
        );
    }
    if let Some(text_body) = text_body {
        return session_bubble_rich(
            message.id.0 as u64,
            label,
            message.is_outgoing,
            text_body,
            extra,
            header,
        );
    }
    // MED4: caption above the media → bubble body. Caption below the
    // media already rides inside `extra` (after the media), so it falls
    // through to the quoted fallback with an empty body.
    if let Some(caption_el) = caption_above_el {
        return session_bubble_rich(
            message.id.0 as u64,
            label,
            message.is_outgoing,
            caption_el,
            extra,
            header,
        );
    }
    session_bubble_quoted(
        message.id.0 as u64,
        label,
        unsupported_body,
        message.is_outgoing,
        extra,
        header,
    )
}

/// Monospace family for `code` / `pre` entity runs (Phase 4.1). The generic
/// family resolves through the platform font stack (fontconfig on Linux).
const MONO_FONT: &str = "monospace";

/// Render message text or a caption with text-entity styling (Phase 4.1).
///
/// Runs come from `styled_runs`, so nested entities combine additively
/// (bold inside italic renders bold italic). `code` is a monospace chip,
/// `pre` a full-width monospace block, and spoilers render as opaque blocks
/// until tapped — reveal state lives on the app, keyed by
/// `(row_id, run index, is_caption)`. Links keep their existing
/// accent-color + open-on-click behavior.
fn rich_text_line(
    text: &str,
    entities: &[TextEntity],
    msg_key: (i64, u64),
    is_caption: bool,
    revealed: &std::collections::HashSet<(i64, u64, u64, bool)>,
    cx: &mut Context<QuillApp>,
) -> AnyElement {
    let mut line = div()
        .id(("msg-rich-text", msg_key.1 * 2 + is_caption as u64))
        .text_sm()
        .flex()
        .flex_wrap()
        .gap_0();
    for (index, run) in styled_runs(text, entities).into_iter().enumerate() {
        if run.text.is_empty() {
            continue;
        }
        let run_id = format!(
            "msg-run-{}-{}-{}-{index}",
            msg_key.0, msg_key.1, is_caption as u64
        );
        let style = &run.style;
        let revealed =
            !style.spoiler || revealed.contains(&(msg_key.0, msg_key.1, index as u64, is_caption));
        if !revealed {
            let key = (msg_key.0, msg_key.1, index as u64, is_caption);
            line = line.child(
                div()
                    .id(run_id)
                    .bg(rgb(0x444c56))
                    .rounded_sm()
                    .px_1()
                    .text_color(rgb(0x444c56))
                    .cursor_pointer()
                    .on_click(cx.listener(move |this, _, _, cx| {
                        this.spoiler_revealed.insert(key);
                        cx.notify();
                    }))
                    .child(run.text),
            );
            continue;
        }
        let mut el = div().id(run_id);
        if style.bold {
            el = el.font_weight(FontWeight::BOLD);
        }
        if style.italic {
            el = el.italic();
        }
        if style.underline {
            el = el.underline();
        }
        if style.strikethrough {
            el = el.line_through();
        }
        if style.code || style.pre {
            el = el.font_family(MONO_FONT);
        }
        if style.pre {
            el = el
                .w_full()
                .bg(rgb(0x22262d))
                .rounded_md()
                .px_2()
                .py_1()
                .my_1();
        } else if style.code {
            el = el.bg(rgb(0x444c56)).rounded_sm().px_1();
        }
        if let Some(href) = run.href {
            el = el
                .text_color(rgb(0x9ecbff))
                .underline()
                .cursor_pointer()
                .on_click(cx.listener(move |this, _, _, cx| {
                    this.open_message_url(&href, cx);
                }));
        }
        line = line.child(el.child(run.text));
    }
    line.into_any_element()
}

/// Phase 4.1: plain/link message text (with optional link-preview card).
/// `msg_key` is (chat id, message id); the spoiler-reveal lookup needs the
/// chat id because message ids are only unique within a chat.
fn message_text_block(
    msg_key: (i64, u64),
    text: &quill::telegram::envelope::TextContent,
    files: &HashMap<i32, ParsedFile>,
    downloading: &std::collections::HashSet<i32>,
    media_roots: &[PathBuf],
    revealed: &std::collections::HashSet<(i64, u64, u64, bool)>,
    cx: &mut Context<QuillApp>,
) -> AnyElement {
    let row_id = msg_key.1;
    let line = rich_text_line(&text.text, &text.entities, msg_key, false, revealed, cx);
    let card = text.link_preview.as_ref().and_then(|preview| {
        preview
            .has_card()
            .then(|| link_preview_card(row_id, preview, files, downloading, media_roots, cx))
    });
    let above = text
        .link_preview
        .as_ref()
        .is_some_and(|preview| preview.show_above_text);
    let has_text = !text.text.is_empty();
    let mut block = div().id(("msg-text-block", row_id)).flex().flex_col();
    if above {
        block = block.when_some(card, |this, card| this.child(card));
        if has_text {
            block = block.child(line);
        }
    } else {
        if has_text {
            block = block.child(line);
        }
        block = block.when_some(card, |this, card| this.child(card));
    }
    block.into_any_element()
}

fn link_preview_card(
    row_id: u64,
    preview: &quill::telegram::envelope::LinkPreview,
    files: &HashMap<i32, ParsedFile>,
    downloading: &std::collections::HashSet<i32>,
    media_roots: &[PathBuf],
    cx: &mut Context<QuillApp>,
) -> AnyElement {
    let site_empty = preview.site_name.is_empty();
    let title_empty = preview.title.is_empty();
    let description_empty = preview.description.is_empty();
    let site = preview.site_name.clone();
    let title = preview.title.clone();
    let description = preview.description.clone();
    let display = if preview.display_url.is_empty() {
        preview.url.clone()
    } else {
        preview.display_url.clone()
    };
    let thumb = preview.photo.as_ref().map(|photo| {
        preview_thumb(
            row_id,
            photo,
            preview.show_large_media,
            files,
            downloading,
            media_roots,
        )
    });
    // MED4: embedded players get a play/duration badge over the
    // thumbnail (schema:4434/:4443/:4452). Tap opens the embed URL in
    // the browser — inline playback is out of slice (DECISIONS.md MED4).
    let thumb = match &preview.kind {
        quill::telegram::envelope::LinkPreviewKind::EmbeddedPlayer {
            duration_secs,
            audio,
            ..
        } => thumb.map(|thumb| {
            let badge = if *duration_secs > 0 {
                format!(
                    "{} {}:{:02}",
                    if *audio { "♪" } else { "▶" },
                    duration_secs / 60,
                    duration_secs % 60
                )
            } else if *audio {
                "♪".to_string()
            } else {
                "▶".to_string()
            };
            div()
                .relative()
                .child(thumb)
                .child(
                    div()
                        .absolute()
                        .bottom_1()
                        .right_1()
                        .px_1()
                        .rounded_sm()
                        .bg(rgb(0x000000))
                        .text_xs()
                        .text_color(rgb(0xffffff))
                        .child(badge),
                )
                .into_any_element()
        }),
        _ => thumb,
    };
    // MED4: album previews (`linkPreviewTypeAlbum`, schema:4392) show a
    // strip of up to 4 thumbnails under the card copy.
    let album_strip: Option<AnyElement> = match &preview.kind {
        quill::telegram::envelope::LinkPreviewKind::Album { thumbnails }
            if !thumbnails.is_empty() =>
        {
            let mut strip = div()
                .id(("link-preview-album", row_id))
                .flex()
                .gap_1()
                .mt_1();
            for (index, thumb_photo) in thumbnails.iter().enumerate() {
                strip = strip.child(preview_thumb(
                    row_id * 100 + index as u64,
                    thumb_photo,
                    false,
                    files,
                    downloading,
                    media_roots,
                ));
            }
            Some(strip.into_any_element())
        }
        _ => None,
    };
    let mut copy = div()
        .id(("link-preview-copy", row_id))
        .flex()
        .flex_col()
        .min_w_0()
        .gap_0();
    if !site_empty {
        copy = copy.child(
            div()
                .text_xs()
                .font_medium()
                .text_color(rgb(0x58a6ff))
                .child(site),
        );
    }
    if !title_empty {
        copy = copy.child(div().text_sm().font_medium().child(title));
    }
    if !description_empty {
        copy = copy.child(div().text_xs().text_color(rgb(0xc9d1d9)).child(description));
    }
    if site_empty && title_empty && description_empty && !display.is_empty() {
        copy = copy.child(div().text_xs().text_color(rgb(0x58a6ff)).child(display));
    }
    let body = if preview.show_large_media {
        let mut column = div()
            .id(("link-preview-large", row_id))
            .flex()
            .flex_col()
            .gap_1();
        if preview.show_media_above_description {
            column = column.when_some(thumb, |this, thumb| this.child(thumb));
            column = column.child(copy);
        } else {
            column = column.child(copy);
            column = column.when_some(thumb, |this, thumb| this.child(thumb));
        }
        column
            .when_some(album_strip, |this, strip| this.child(strip))
            .into_any_element()
    } else {
        div()
            .id(("link-preview-small", row_id))
            .flex()
            .flex_col()
            .gap_1()
            .child(
                div()
                    .flex()
                    .items_start()
                    .gap_2()
                    .child(copy.flex_1())
                    .when_some(thumb, |this, thumb| this.child(thumb)),
            )
            .when_some(album_strip, |this, strip| this.child(strip))
            .into_any_element()
    };
    let preview_for_tap = preview.clone();
    div()
        .id(("link-preview", row_id))
        .mt_2()
        .px_2()
        .py_1()
        .rounded_md()
        .border_l_2()
        .border_color(rgb(0x58a6ff))
        .bg(rgb(0x161b22))
        .cursor_pointer()
        .on_click(cx.listener(move |this, _, _, cx| {
            // MED4: `instant_view_version > 0` (schema:4570) opens the IV
            // reader (mode-gated); otherwise the browser. Embedded
            // players open their embed URL instead of the page URL.
            this.open_preview_url(&preview_for_tap, cx);
        }))
        .child(body)
        .into_any_element()
}

/// M2: render a `messageRichMessage` (schema 1.8.67, line 5143) as a stack
/// of `pageBlock*` elements. Styled text reuses `rich_text_line` (M1
/// entities); inline buttons and button rows reuse
/// `inline_keyboard_button` (URL / callback / switchInline / copy
/// handlers — the same honest tap behavior as reply-markup keyboards).
/// A partial message (`is_full == false`, schema line 123) offers a
/// "Load full message" button that fetches the rest via
/// `getFullRichMessage` instead of pretending to be complete.
fn message_rich_block(
    msg_key: (i64, u64),
    chat_id: ChatId,
    message_id: MessageId,
    rich: &quill::telegram::envelope::RichMessageContent,
    revealed: &std::collections::HashSet<(i64, u64, u64, bool)>,
    cx: &mut Context<QuillApp>,
) -> AnyElement {
    let row_id = msg_key.1;
    let mut stack = div()
        .id(format!("msg-rich-block-{row_id}"))
        .flex()
        .flex_col()
        .gap_2();
    for (index, block) in rich.blocks.iter().enumerate() {
        if let Some(child) =
            rich_block_element(index, block, msg_key, chat_id, message_id, revealed, cx)
        {
            stack = stack.child(child);
        }
    }
    if !rich.is_full {
        stack = stack.child(
            Button::new(format!("rich-load-full-{row_id}"))
                .label("Load full message")
                .ghost()
                .on_click(cx.listener(move |this, _, _, cx| {
                    if let Some(live) = this.live.as_mut() {
                        match live.driver.fetch_full_rich_message(chat_id, message_id) {
                            Ok(_) => this.status_note = "loading full message…".into(),
                            Err(_) => this.status_note = "could not load full message".into(),
                        }
                        cx.notify();
                    }
                })),
        );
    }
    stack.into_any_element()
}

/// M2: one `RichBlock` as an element. `None` for invisible/unsupported
/// blocks (`pageBlockAnchor`, unknown types) — parsed, never rendered as
/// fake content.
#[allow(clippy::too_many_arguments)]
fn rich_block_element(
    index: usize,
    block: &RichBlock,
    msg_key: (i64, u64),
    chat_id: ChatId,
    message_id: MessageId,
    revealed: &std::collections::HashSet<(i64, u64, u64, bool)>,
    cx: &mut Context<QuillApp>,
) -> Option<AnyElement> {
    let row_id = msg_key.1;
    match block {
        RichBlock::Paragraph {
            text,
            entities,
            buttons,
        } => {
            let mut col = div()
                .id(format!("rich-para-{row_id}-{index}"))
                .flex()
                .flex_col()
                .gap_1();
            if !text.is_empty() {
                col = col.child(rich_text_line(text, entities, msg_key, false, revealed, cx));
            }
            for (button_index, button) in buttons.iter().enumerate() {
                col = col.child(
                    div()
                        .id(format!("rich-para-btn-{row_id}-{index}-{button_index}"))
                        .flex()
                        .child(
                            inline_keyboard_button(
                                chat_id,
                                message_id,
                                index,
                                button_index,
                                button,
                                None,
                                cx,
                            )
                            .flex_1(),
                        ),
                );
            }
            Some(col.into_any_element())
        }
        RichBlock::Heading {
            level,
            text,
            entities,
        } => {
            let heading = div()
                .id(format!("rich-heading-{row_id}-{index}"))
                .font_semibold();
            let heading = match level {
                1 => heading.text_xl(),
                2 => heading.text_lg(),
                _ => heading.text_base(),
            };
            Some(
                heading
                    .child(rich_text_line(text, entities, msg_key, false, revealed, cx))
                    .into_any_element(),
            )
        }
        RichBlock::List { ordered, items } => {
            let mut col = div()
                .id(format!("rich-list-{row_id}-{index}"))
                .flex()
                .flex_col()
                .gap_1();
            for (item_index, item) in items.iter().enumerate() {
                let marker = match item.checked {
                    Some(true) => "☑",
                    Some(false) => "☐",
                    None if *ordered => &format!("{}.", item_index + 1),
                    None => "•",
                };
                col = col.child(
                    div()
                        .id(format!("rich-list-item-{row_id}-{index}-{item_index}"))
                        .flex()
                        .gap_2()
                        .child(div().text_sm().child(marker.to_string()))
                        .child(div().text_sm().child(item.text.clone())),
                );
            }
            Some(col.into_any_element())
        }
        RichBlock::Collapsible { header, body, .. } => Some(
            div()
                .id(format!("rich-details-{row_id}-{index}"))
                .flex()
                .flex_col()
                .gap_1()
                .child(div().text_sm().font_semibold().child(format!("▾ {header}")))
                .child(
                    div()
                        .ml_4()
                        .text_sm()
                        .text_color(cx.theme().muted_foreground)
                        .child(body.clone()),
                )
                .into_any_element(),
        ),
        RichBlock::Document {
            file_name, caption, ..
        } => {
            let mut col = div()
                .id(format!("rich-document-{row_id}-{index}"))
                .flex()
                .flex_col()
                .gap_1()
                .child(
                    div()
                        .flex()
                        .items_center()
                        .gap_2()
                        .child(div().text_sm().child("📄"))
                        .child(div().text_sm().font_medium().child(file_name.clone())),
                );
            if !caption.is_empty() {
                col = col.child(div().text_xs().child(caption.clone()));
            }
            Some(col.into_any_element())
        }
        RichBlock::Table { rows } => {
            let mut table = div()
                .id(format!("rich-table-{row_id}-{index}"))
                .flex()
                .flex_col()
                .gap_1();
            for (row_index, row) in rows.iter().enumerate() {
                let mut line = div()
                    .id(format!("rich-table-row-{row_id}-{index}-{row_index}"))
                    .flex()
                    .gap_2();
                for (cell_index, cell) in row.iter().enumerate() {
                    line = line.child(
                        div()
                            .id(format!(
                                "rich-table-cell-{row_id}-{index}-{row_index}-{cell_index}"
                            ))
                            .flex_1()
                            .text_sm()
                            .child(cell.clone()),
                    );
                }
                table = table.child(line);
            }
            Some(table.into_any_element())
        }
        RichBlock::ButtonRow { buttons } => {
            let mut line = div()
                .id(format!("rich-button-row-{row_id}-{index}"))
                .flex()
                .gap_1();
            for (button_index, button) in buttons.iter().enumerate() {
                line = line.child(
                    inline_keyboard_button(
                        chat_id,
                        message_id,
                        index,
                        button_index,
                        button,
                        None,
                        cx,
                    )
                    .flex_1(),
                );
            }
            Some(line.into_any_element())
        }
        RichBlock::Divider => Some(
            div()
                .id(format!("rich-divider-{row_id}-{index}"))
                .h_px()
                .w_full()
                .bg(cx.theme().border)
                .into_any_element(),
        ),
        RichBlock::Empty | RichBlock::Unsupported { .. } => None,
    }
}

fn preview_thumb(
    row_id: u64,
    photo: &quill::telegram::envelope::PhotoContent,
    large: bool,
    files: &HashMap<i32, ParsedFile>,
    downloading: &std::collections::HashSet<i32>,
    media_roots: &[PathBuf],
) -> AnyElement {
    let (w, h) = if large {
        (px(240.), px(140.))
    } else {
        (px(72.), px(72.))
    };
    if let Some(path) = photo_display_path(photo, files, media_roots) {
        return img(path)
            .id(("link-preview-img", row_id))
            .w(w)
            .h(h)
            .rounded_md()
            .object_fit(ObjectFit::Cover)
            .flex_shrink_0()
            .with_fallback(move || {
                div()
                    .w(w)
                    .h(h)
                    .rounded_md()
                    .bg(rgb(0x444c56))
                    .into_any_element()
            })
            .into_any_element();
    }
    let file_id = photo
        .thumb_size()
        .map(|size| size.file_id)
        .unwrap_or(FileId(0));
    let label = if file_is_downloading(file_id, files, downloading) {
        "…"
    } else {
        "Preview"
    };
    div()
        .id(("link-preview-ph", row_id))
        .w(w)
        .h(h)
        .rounded_md()
        .bg(rgb(0x444c56))
        .flex()
        .flex_shrink_0()
        .items_center()
        .justify_center()
        .child(div().text_xs().text_color(rgb(0xffffff)).child(label))
        .into_any_element()
}

